// ════════════════════════════════════════
//  デモシーン ▸ 電磁気学
// ════════════════════════════════════════
//  ★共通の見せ方と実装関数の約束は js/app/demo-kit.js にある（先に読むこと）。
//    どのデモがどの単元に並ぶかは目録 js/app/demos.js の側で決まる。

// ── 箔検電器 ───────────────────────────────────────────────
//  ★このエンジンは誘導電荷を持たない（em/circuit.js の CONDROD_THICK の★）。物体の
//    charge は重心の1点に固定されていて、外から電場をかけても中で動かない。だから
//    「導体を1つの物体として置き、静電誘導で箔が開く」は原理的に作れない。
//    そこで**導体を中空にして、動ける電荷を粒として中に入れる**。器・円板・箔は
//    どれも電気量 0 で、電気を持っているのは粒だけ＝誘導電荷をエンジンに足すのではなく、
//    「動ける電荷」を実体として置いて、その移動を見せる。
//  ★粒は正負を同数入れる。片方（＝自由電子だけ）を動かす作りにすると、正の棒では
//    筋が通るが負の棒では逆に閉じる。箔検電器は符号によらず開くので、それでは一般則を破る。
//  ★箔の本体が電気量 0 だということは、**箔は電場から力を受けない**。箔を動かすのは
//    中へ入ってきた粒が壁を押す接触力だけ。ここが設計のいちばん効くところで、
//    途中で次の2つに実測でぶつかった：
//      ・箔の口を溝より狭くすると、口の両脇が「棚」になって粒がそこに乗ったまま
//        箔へ落ちない（実測：6個のうち箔に入ったのは 2個/0個。残りは溝の肩に居座り、
//        しかも外側から箔を内へ押して −12° ＝ 逆に閉じた）
//      ・箔の中を広くすると、粒が左右の壁を逆向きに押して打ち消す
//        （実測：2個入った箔の開きは 1.2°、1個だけの箔は 16.5°）
//    → **口は溝の幅いっぱい・中は粒1個ぶんの幅**を同時に満たす形＝漏斗にした。
//      これで同符号の6個が必ず 3個ずつ箔に入り、1列に並んで同じ壁を押す。
//      左右差は 4.9°→0.2°、符号差は 0.0° になった。
//  ★粒には重力を効かせない（hasGravity:false）。金属の中の電荷に重さの影響は無い
//    （電子にかかる重力は電気力の 10⁻³⁰ 程度）。ここを入れると粒が底にたまるだけになる。
//  ★粒の抗力 Cd=2.5 は金属の電気抵抗の代わり。これが無いと粒がいつまでも振動し、
//    どの配置に落ち着くかが毎回変わった（実測：同じ条件で開きが 2.6°と19.8°に割れた）。
//  ★ビンは**お絵描きの線だけ**（annotations）。物理には一切参加しない（CLAUDE.md の第一の
//    不変条件）ので、中の箔がビンの壁で止まることはないし、ビンが電荷に影響することもない。
//    本物の箔検電器がガラス容器に入っているのは、風と湿気で箔が動くのを防ぐため。
//    このデモにはどちらも無いので、あるのは見た目の理由だけ＝線で描くのが正直な扱い。
const ES_K       = 0.2;      // 実効クーロン定数（world.coulombK）
const ES_QE      = 0.075;    // [C] 動ける電荷1粒の電気量（正負とも）
const ES_NPAIR   = 6;        // 正負の組の数
const ES_QROD    = 10;       // [C] 棒の電気量の既定値（つまみの上限＝右パネルと同じ ±10）
const ES_TH      = 10;       // [px] 導体の板の厚み
// 胴（空洞）の大きさ。★ここは「T字の縦棒を中空にする」のではない。縦棒を細くして
//   首を作ると粒の通り道が1本の喉になり、先に入った側へ雪崩れて片方の箔だけが満タンに
//   なる（実測：⊕6個が 0個/5個 に割れ、開きは 2.6°/2.8° しか出ず、棒を離しても片方が
//   15.9° のまま閉じなかった）。**首は「行き」だけでなく「帰り」も塞ぐ**のがやっかいで、
//   棒を床へ戻しても粒が首から出てこられず、箔が 33.5°/40.2° 開いたまま閉じなくなる。
//   ★この「帰れない」は棚とは別物。頭の底を首へ向かう下り坂にして棚を消し（坂の下端は
//     首の壁の**内**面に合わせること。外面に着けると壁の上端に厚みぶんの窪みが残って
//     また棚になる）、さらに箔を重くして開きを 1〜3°まで抑えても、戻すと 6.5〜14.2°の
//     ままだった。仕切りの頭を三角にしても直らない。
//   **左右の箔がそれぞれ自分の真上に受け口を持っている**ことが要るので、胴は割らずに
//   1つの空洞のままにし、幅だけ円板よりずっと細くしてT字の見た目を出す。
//   ★縦長の空洞そのものも駄目だった（首だけの 170px：3.2°/1.5°、箔に 1個/0個）。
//     棒と同じ符号でない粒の逃げ場が箔の真上に来て、箔を内へ引き戻す。
const ES_HW      = 55;       // [px] 胴（空洞）の半幅。外側は 130px ＝ 円板 250px の約半分
const ES_HH      = 80;       // [px] 胴（空洞）の高さ
const ES_DISK_W  = 250;      // [px] 円板の幅
const ES_DISK_H  = 12;       // [px] 円板の厚み
const ES_SKIRT   = 40;       // [px] すその深さ（箔の口の外側を覆う）
const ES_SLOT_IN = 10;       // [px] 中央の柱の半幅（＝溝の内端）
const ES_CHAN    = 20;       // [px] 箔の中の通路の幅（粒の直径 14px より少しだけ広い）
const ES_FUNNEL  = 45;       // [px] 漏斗の高さ
const ES_CHANL   = 150;      // [px] 通路の長さ
const ES_FWALL   = 6;        // [px] 箔の板の厚み
const ES_FMASS   = 0.003;    // [kg] 箔1枚の質量。★軽くすると大きく開くが、棒を離した
                             //   あとの戻りが悪くなる（実測 0.0015kg：開き 8.1°/11.5° で
                             //   戻りが −2.4°。0.003kg なら 6.3°/8.4° で戻りは 0.0°）
                             //   ★2026-09 電磁気の力を半分ずつ効かせる積分（step.js の★）の
                             //   あと、棒を円板の上 60／120px に固定して ±10C の4通り：開き
                             //   旧 4.8〜10.9° → 新 3.9〜8.3°（旧でも条件で 5.1〜10.9° と散る）、
                             //   戻り 旧 4通りとも 0.0° → 新 −0.6°・0.2° が1回ずつ
const ES_PINM    = 0.1;     // [kg] 箔の軸棒（mkLeaf の★）。★ちょうつがいの点そのものにあるので、
                             //   重くしても重力のトルクは増えず、慣性もほぼ増えない（幅 42px）。箔の質量
                             //   ES_FMASS はそのまま。★軽いと溶接と軸がたわむ：0.0001kg では棒を離したあと
                             //   箔が 50° 回って口から外れ、0.001kg では回りっぱなしになった。
                             //   ★棒を円板のすぐ上まで下ろすと、溶接と軸のたわみがはっきり出る。手でつまんで
                             //   持ち上げ、真上へ運んで円板の上 30〜70px に下ろす18通り（±10C、5px刻み）で
                             //   「左右に開いた」回数（2026-10-02、ユーザーの指摘「同じ向きに傾く」で測り直し）：
                             //     軸棒を足す前（箔にじかにヒンジ） 12/18（4回は左の箔が内へ入って同じ向きに傾く）
                             //     0.01kg  6/18（同じ向き2・片方だけ10。30px では箔が1回転した）
                             //     0.03kg 17/18　　0.1kg 18/18 ← これ　　（刻みを16に上げても 11/18 で効かない）
                             //   遠めの10通り（棒を 70〜150px に固定、各30秒の最後の300tick平均）も 0.1kg で
                             //   開き平均 4.2°→5.6°・戻り平均 0.31°→0.31°、内へ入るものは 2→0。
const ES_ER      = 7;        // [px] 粒の半径
const ES_EM      = 0.002;    // [kg] 粒の質量
const ES_EDRAG   = 2.5;      // 粒の抗力係数（＝金属の抵抗。上の★）
const ES_ROD_W   = 180;      // [px] 棒の長さ
const ES_ROD_H0  = 250;      // [px] 棒のはじめの高さ（円板の上面から棒の下面まで）。下の★
const ES_ROD_V   = 0.3;      // [m/s] リモコンで上げ下げする速さ
// 衝突レイヤー（4枚しかないので割り振りを1か所に書く）。マスクは共有ビットがあれば衝突。
//   ★導体・左の箔・右の箔を分けるのは、箔が開くときに口の部分がすそと重なるため
//     （機械的に噛むと箔が止まる）。
//   ★棒だけ4枚目に置く。**電荷が触れてよいのは容器と箔だけ**にしたいが、棒は円板を
//     突き抜けずに止まってほしい。マスクは推移的でないので、容器に「電荷用」と「棒用」の
//     2ビットを持たせれば、容器↔電荷と容器↔棒だけが成立して電荷↔棒は成立しない。
//       容器 1|8 ／ 左の箔 2 ／ 右の箔 4 ／ 電荷 1|2|4 ／ 棒 8
const ES_L_ROD  = 8;
const ES_L_CASE = 1 | ES_L_ROD, ES_L_FL = 2, ES_L_FR = 4, ES_L_Q = 1 | 2 | 4;

function demoElectroscope() {
  resetDemoWorld();
  updateGroundTerrain(true);
  world.sleeping   = false;
  world.substeps   = 8;
  world.coulombOn  = true;
  world.coulombK   = ES_K;

  const TH = ES_TH, HW = ES_HW;
  const TOP = -ES_HH, BOT = 0;                      // 胴（空洞）の天井と底
  const WBOT = BOT + TH + ES_SKIRT;                 // 導体の下端（すその底）
  const LEAF_LEN = ES_FUNNEL + ES_CHANL + ES_FWALL; // 箔の長さ（口から先まで）
  // ★据え付けの高さ。箔の先が地面から 70px 浮くように置く（ビンの底が地面）。
  const gy = ground.y, oy = gy - (BOT + TH + LEAF_LEN + 70);
  const grey = { fillColor:'#90a4ae', strokeColor:'#cfd8dc', strokeWidth:1.5 };
  const mkBox = o => new Body(Object.assign({ type:'box', friction:0, frictionStatic:0,
                                              restitution:0 }, o));
  const put = o => { const b = mkBox(Object.assign({}, o, { y: o.y + oy })); objects.push(b); return b; };

  // ── 導体：T字（幅の広い円板 ＋ その下の細い胴）。胴の中が空洞 ──
  //   ★側面のすそ（下へ伸ばした分）は溝の外側にだけ出す。溝の中に出っぱりを作ると
  //     そこが棚になる（ファイル冒頭の★）。
  const wall = (x, y0, y1, w) => put(Object.assign({ x, y:(y0 + y1)/2, w, h:y1 - y0,
                                       isStatic:true, layers:ES_L_CASE }, grey));
  wall(-(HW + TH/2), TOP, WBOT, TH);  wall( (HW + TH/2), TOP, WBOT, TH);   // 胴の横
  put(Object.assign({ x:0, y:TOP - ES_DISK_H/2, w:ES_DISK_W, h:ES_DISK_H,
                      isStatic:true, layers:ES_L_CASE, label:'円板' }, grey));
  put(Object.assign({ x:0, y:(BOT + WBOT)/2, w:ES_SLOT_IN*2, h:WBOT - BOT,
                      isStatic:true, layers:ES_L_CASE }, grey));      // 2つの溝を分ける柱

  // ── 箔：溝の幅いっぱいの口から、粒1個ぶんの通路へ絞った漏斗 ──
  const mkLeaf = (sgn, layer) => {
    const px = sgn * (ES_SLOT_IN + HW) / 2, py = BOT + TH + oy;   // ちょうつがい＝口の中心
    const W2 = (HW - ES_SLOT_IN) / 2, c2 = ES_CHAN / 2, t = ES_FWALL;
    const gold = { fillColor:'#ffd54f', strokeColor:'#fff8e1', strokeWidth:1.5 };
    // 斜めの板は「両端を結ぶ線分」として置く（回した箱。手でも回して作れる）
    const seg = (x1, y1, x2, y2) => mkBox(Object.assign({
      x: px + (x1 + x2)/2, y: py + (y1 + y2)/2,
      w: Math.hypot(x2 - x1, y2 - y1) + t, h: t,
      angle: Math.atan2(y2 - y1, x2 - x1) }, gold));
    const leaf = demoUnion([
      seg(-W2, 0, -c2, ES_FUNNEL), seg(W2, 0, c2, ES_FUNNEL),                    // 漏斗
      mkBox(Object.assign({ x:px - c2 - t/2, y:py + ES_FUNNEL + ES_CHANL/2,
                            w:t, h:ES_CHANL }, gold)),                           // 通路（内）
      mkBox(Object.assign({ x:px + c2 + t/2, y:py + ES_FUNNEL + ES_CHANL/2,
                            w:t, h:ES_CHANL }, gold)),                           // 通路（外）
      mkBox(Object.assign({ x:px, y:py + ES_FUNNEL + ES_CHANL + t/2,
                            w:ES_CHAN + t*2, h:t }, gold)),                       // 底
    ]);
    leaf.setMass(ES_FMASS);
    leaf.charge = 0;                 // ★箔そのものは電気を持たない（冒頭の★）
    leaf.layers = layer; leaf.drag = 1.5;
    leaf.friction = 0; leaf.frictionStatic = 0; leaf.restitution = 0;
    // ── 軸棒：口に渡した細い棒。ちょうつがいはここに打つ ──
    //   ★ヒンジは画鋲（重なった2つを1点で留める）。ちょうつがいの点＝口の中心には箔の板が
    //     無い（粒の通り道）ので、以前のように箔へじかに打つと留め点が箔の外になり、手では
    //     組めなかった（2026-10-02 に直した）。そこで口に棒を渡して箔の板と溶接し、棒の中心を
    //     背景にヒンジで留める。
    //   ★棒は何とも当たらない（layers:0）。粒の通り道を横切るので、当たると口をふさぐ。
    //     4枚のレイヤーは使い切っている（上の割り振り）ので、0 しか空いていない。
    //   ★幅は口より 3px 狭い（両脇 1.5px）。棒の端は溶接の点（左の板の中）まで届く。
    const pin = mkBox(Object.assign({ x:px, y:py, w:2 * W2 - 3, h:3, mass:ES_PINM, layers:0 }, gold));
    objects.push(pin);
    const wx = px - W2 + 2.5, wy = py + 1;          // 溶接の点：左の板の中（中心線から 2.1px）かつ棒の中
    //   ★打つのは手のツールと同じ入口（demo-kit.js の demoPin）
    demoPin('fixjoint', wx, wy, 'pair', { expect:[leaf, pin] });
    demoPin('hinge', px, py, 'pair', { expect:[pin, null], opts:{ color:'#ffd54f' } });   // 口の中心には棒しか無い
    return leaf;
  };
  mkLeaf(-1, ES_L_FL); mkLeaf(+1, ES_L_FR);

  // ── 動ける電荷：正負を同数（導体全体は中性）──
  //   ★並びは左右対称にする（＋−−＋＋−−＋…）。単純な交互にすると列の左端が＋・
  //     右端が−になり、その偏りが落ち着いたあとも左右の箔の個数差として残った。
  const n = ES_NPAIR * 2;
  for (let i = 0; i < n; i++) {
    const pos = (i % 4 === 0 || i % 4 === 3);
    objects.push(new Body({
      type:'circle', x: -HW + 20 + i * ((HW*2 - 40) / (n - 1)),
      y: TOP + ES_HH/2 + oy,
      radius:ES_ER, mass:ES_EM, charge: pos ? ES_QE : -ES_QE,
      hasGravity:false, drag:ES_EDRAG, fixedRotation:true, layers:ES_L_Q,
      friction:0, frictionStatic:0, restitution:0,
      fillColor: pos ? '#ef5350' : '#42a5f5', strokeColor:'#ffffff', strokeWidth:1.2 }));
  }

  // ── 帯電した棒：円板の真上に固定。リモコン（↑↓）で上げ下げする ──
  //   ★2026-10-02 ユーザーの指示で、つかむツールで運ぶ形からリモコンで上げ下げする形にした。
  //   ★固定した物体にする。リモコン〈手で動かす〉は固定した物体も動かせ、放せばその場で止まる。
  //     動く物体のままだと、宙で放したあと電荷に引かれて下がっていく（実測：重力を切って
  //     縦のレールに載せても 10 秒で 2〜3.5px）。固定した物体は力を受けないので動かない。
  //     場をつくる側には参加するので、棒が電荷を動かす、は成り立つ（実測：円板の上 150px で
  //     箔が 2.4°／−4.0° 開く）。
  //   ★はじめの高さは円板の上 ES_ROD_H0。200px より近いと開いた画面から箔が開いている
  //     （実測：150px で 2.4°／−4.0°、200px 以上は 0.0°／−0.1° 以内）。
  //   ★限り：固定した物体どうしは当たらないので、↓ を押し続けると棒は円板にめり込む。
  //     リモコンには止まる位置の設定が無い（本文で「円板の手前で止める」と案内する）。
  const diskTop = TOP - ES_DISK_H + oy;
  const rod = new Body({ type:'box', x:0, y:diskTop - 7 - ES_ROD_H0, w:ES_ROD_W, h:14,
    isStatic:true, mass:0, charge:ES_QROD, fixedRotation:true, layers:ES_L_ROD,
    friction:0.6, frictionStatic:0.8, restitution:0, label:'帯電した棒',
    fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.5 });
  objects.push(rod);

  // ── 操作：棒の上げ下げ（↑↓）と電気量のつまみ ──
  //   ★上げ下げは〈手で動かす〉2台（↑ 上げる・↓ 下げる）。速さ ES_ROD_V は「円板の上 250px から
  //     8 秒で着く」くらい（0.3 m/s ＝ 30px/s）。速いと止めどきを逃してめり込む。
  //   ★電気量は「手では変えられない量」。符号を入れ替える・0 にする、が読みどころ。
  const knob = addRemote('prop', rod, 'body');
  if (knob) {
    knob.kind = 'prop'; knob.prop = 'charge'; knob.lo = -ES_QROD; knob.hi = ES_QROD;
    knob.fx = 0.055; knob.fy = 0.62;
    placeRemotePanel(knob); syncRemotePanel(knob);
  }
  //   ★2台は横に並べ、電気量のつまみの窓（fy 0.62）のすぐ上に置く。縦に積むと窓どうしが重なる
  for (const [key, dir, fx] of [['ArrowUp', 90, 0.055], ['ArrowDown', 270, 0.235]]) {
    const r = addRemote('drive', rod, 'body');
    if (!r) continue;
    Object.assign(r, { kind:'drive', key, dir, speed:ES_ROD_V, mode:'on', collapsed:true, fx, fy:0.45 });
    placeRemotePanel(r); syncRemotePanel(r);
  }

  // ── ビン（お絵描きの線。物理には参加しない）──
  //   ★口は導体の縦棒より広くし、肩から下は箔が開ききっても触れない幅にする
  //     （箔の先は最大で中心から 95px。ビンの半幅は 120px）。
  const JAR = 'rgba(176,222,236,0.5)';
  const jarTop = BOT + 26 + oy, jarBot = gy;
  demoPath([{ x:-88, y:jarTop }, { x:-72, y:jarTop + 5 }, { x:-72, y:jarTop + 28 },
            { x:-104, y:jarTop + 66 }, { x:-104, y:jarBot - 16 }, { x:-90, y:jarBot },
            { x:  90, y:jarBot }, { x: 104, y:jarBot - 16 }, { x: 104, y:jarTop + 66 },
            { x:  72, y:jarTop + 28 }, { x:  72, y:jarTop + 5 }, { x: 88, y:jarTop }],
           JAR, 4);
  demoPath([{ x:-80, y:jarTop + 104 }, { x:-80, y:jarBot - 36 }], 'rgba(176,222,236,0.3)', 3);

  // ── 画面 ──
  //   ★倍率 1.0。地面から円板まで 463px あり、さらにその上へ棒を持ち上げる高さが要る
  //     （画面に入る地面より上の高さ ＝ 0.8×736/倍率 ＝ 589px）。
  setDemoCam(-251, 1.0);
  //   ★棒をはじめから円板の上 250px に置くので、画面を 130px 上へずらして場所を作る
  //     （地面は画面の下端の 18px 上まで下がる。地面の下は使っていない）
  cam.y -= 130;
  const ts = demoTextScale(cam.zoom);
  demoLabel(ES_DISK_W/2 + 18, TOP - ES_DISK_H + oy, '円板', '#cfd8dc', DEMO_NOTE_SIZE * ts);
  demoLabel(132, BOT + TH + LEAF_LEN - 30 + oy, '箔', '#ffd54f', DEMO_NOTE_SIZE * ts);
  demoLabel(ES_ROD_W/2 + 14, rod.y + 6, '帯電した棒（↑↓）', '#ef5350', DEMO_NOTE_SIZE * ts);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '箔検電器', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    'T字の導体の中が空洞になっていて、動ける電荷が⊕と⊖の粒として入っている。\n'
  + '導体も箔もそれ自体は電気を持っていない。下の2枚の箔は口の開いた入れ物で、\n'
  + '中へ入ってきた粒のぶんだけ帯電する。ビンは絵で、物理には参加しない。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・↓ キー（左のリモコン）で棒を下ろしていく。円板に触れる手前で止める（↑ で上げる）\n'
  + '・中の電荷が上下に分かれ、棒と同じ符号のほうが箔へ落ちていく\n'
  + '・2枚の箔が同じ符号に帯電して反発し、開く\n'
  + '・棒を上げて遠ざけると電荷は散らばり、箔は閉じる\n'
  + '・つまみで棒の電気量を − にしても、やはり開く（動く電荷の向きが入れ替わるだけ）\n'
  + '・つまみを 0 にすると、いくら近づけても開かない',
    DEMO_NOTE_SIZE * ts);

  // ★粒を落ち着かせ、棒を床に着かせてから開く。置いた直後は格子状に並んでいる。
  demoRunAhead(600);
}

// ── オームの法則モデル（金属の中の自由電子）───────────────────────
//  ★回路ツール（em/circuit.js の MNA ソルバ）は使わない。あちらは「枝と節点の回路網を
//    解いて電流という数を出す」道具で、電流の中身は出てこない。この題材の読みどころは
//    その中身＝**電子が1粒ずつ動いているところ**なので、通路・電場・粒だけで組む。
//  ★通路は「大きい四角から一回り小さい四角を型抜きした枠」＋「中の島」の2つ。
//    型抜きは左ツールバーの図形和とまったく同じ経路（demoBoolean('diff')）で、穴あきの
//    物体がそのまま衝突にも効く（実測：電子20個を最大 300px/s の無作為な向きで
//    600tick 走らせて、通路の外へ出たのは延べ 0 tick）。
//  ★電子を押しているのは**通路に置いた電場の領域8枚**で、電池は絵（annotations）だけ。
//    起電力という部品はこのエンジンに無いし、あっても「電池が電子を吸い上げる」絵に
//    なってしまう。導線の中の電子を動かしているのは導線の中の電場そのもの、という
//    のが実際の描像なので、場を置いて電池を絵にするほうが正直になる。
//  ★電場の向きは一周して時計回り（＝電流の向き）。電子は負なので F=qE は逆を向き、
//    反時計回りに流れる。**「電流の向きと電子の動く向きは逆」がこのデモの芯**なので、
//    ここを反転させないこと。
//  ★**角は直角にしない。円弧にする**（OHM_CR の★）。直角の角では電子は外側の壁へ
//    正面からぶつかって行き足を全部失い、そこから斜めの場に押し直されて出ていく。
//    つまり角そのものが抵抗として働いていて、「抵抗を通ると遅くなる」という読みどころを
//    薄めていた。実測（乱数固定・1500tick 落ち着かせてから 3000tick の時間平均。
//    電気量は当時の −0.002・電圧 3 のままで、角だけを丸めた対照）：
//      直角：電流 33・速さ 導線 131／抵抗 48（比 2.7）
//      円弧：電流 43・速さ 導線 218／抵抗 50（比 4.4）
//    抵抗の中の速さは 48→50 と動かず、変わったのは導線の側だけ＝角で失っていた行き足が
//    そのまま戻った。通路の外へ出た電子は延べ 0 tick（電圧 20 まで確認）。
//  ★どの区画にも場が要る。以前は長い帯4枚を角で 90×90 だけ重ね、重ね合わせで斜めの場を
//    作っていた（帯を島の幅まで縮めて角を無風にすると、角で止まった電子を押し直すものが
//    無くなり、電流が 93 → 11 に落ちた）。角を丸めるとこの重なりは曲がりの外側 1/4 しか
//    覆わないので、直線は角の手前で終わらせ、角には斜めの帯を1枚置く（曲がりを
//    ちょうど覆う正方形）。重なりが無くなったので、場の大きさは角でも √2 倍にならず
//    一周そろう。
//  ★**陽イオンは固定しない。ばねで格子点につないだ玉にする。** ここがこのデモの要で、
//    動かないイオンでは抵抗が作れなかった。理由は幾何で、逃げ道が無い：
//      ・障害物を壁に近づけると、電子が壁と障害物のあいだに楔のように挟まって永久に
//        止まる（壁の法線と障害物の法線が電場の向きを挟み込む。摩擦0でも外れない）
//      ・壁から離すと、壁沿いにまっすぐな車線が空いて素通りになる
//    そして「電子が壁に触れたまま障害物にも触れられる距離」と「車線が電子より狭くなる
//    距離」は厳密に同じ値なので、この2つに中間が無い。実測（乱数固定・1200tick の
//    時間平均、電流＝左の辺の中央を横切った回数。対照＝抵抗区間なしで 46）：
//      イオンを詰める 40／通路を細くする 1／互い違いの板 0／ぎざぎざの壁 43。
//    しかも 40 へ落ちたぶんは全部「止まった電子」で説明がついた（動いている電子1個
//    あたりの通過回数は対照 46/16＝2.9、詰めた条件 29/10＝2.9 で一致）＝**流れている
//    電子はイオンの密度に一切影響されていなかった**。
//    ★この2択に中間が無いのは「障害物を壁の内側にしか置けない」ときの話。壁をすり抜ける
//      レイヤーにして玉を**壁より外へ**置くと中間が作れる（下の4段の★）。
//  ★玉をばねで吊ると、抵抗の効きは**滑らかに**なる。ぶつかった行き足は玉の振動に移り、
//    それが格子へ渡るジュール熱そのものになる。実測（4000tick、対照＝抵抗区間なしで
//    181）：詰めかたを変えると 181 → 139 → 91 → 79 → 44 → 13 と単調に効く。
//  ★**ただし、ばねでは楔は解けなかった。** 以前ここに「玉を押しのけて抜けられる」と
//    書いていたが、静かに押されている玉は動かない：ばね 20N/m（当時の表記。実際は 2N/m。
//    OHM_BALL_K の★）に対して電子が押す力は qE＝0.014N なので、釣り合いのずれは 0.0007m ＝ **0.07px**
//    （実際の 2N/m でも 0.7px）しかない。玉は事実上
//    壁の一部になる。実測（乱数固定・6000tick＝100秒）で 18個中1個が、島の壁と玉の
//    あいだの楔に嵌まって走行 541px（他は 15000px 前後）、1tick も動かなかった tick が
//    33% だった。玉が揺すられているあいだは抜けられるので「凍結」としては見えにくいが、
//    運悪く静まると戻らない。**解くべきは力ではなく幾何のほう**（OHM_ROWS の★）。
//  ★ばねの減衰は 0 にする。0.02 でも入れると玉が静まり、揺すられなくなった電子が
//    1個だけ島の壁との楔に嵌まって二度と動かなかった（12000tick＝200秒、走行 4px）。
//    減衰 0 でも発散しない：玉のずれの平均は 2.6→2.9px で頭打ちになり、電流も
//    4等分した各期間で 103/110/111/103 と一定だった。**エネルギーの捨て場は
//    ばねではなく、反発 0 の衝突のほう**だから。
//  ★イオンの並びは「中央の2段＋壁に半分埋めた2段」の**4段**を順に繰り返す
//    （もとは中心・左・右の3段＋±4px のゆらぎ）。埋めた段が壁ぎわの車線を塞ぎ、
//    しかも楔を作らない。この2つを同時に満たせるのは玉を壁より外に置いたときだけで、
//    そこが 3段では取れなかった「中間」にあたる。詳しくは OHM_ROWS の★。
//    古い並べかたとの比較（4000tick）：電流 69→71 と同じだが、抵抗の中で隣と接触して
//    いる割合が 0.18→0.029 に落ちた＝**詰まって遅いのではなく、弾かれて遅い**に変わった。
//  ★**この模型が I ∝ V に見えても、オームの法則が出ているのではない。** 単元の名前に
//    引かれて「オームの法則が出る」と書かないこと。本物がオーム則になるのは衝突の間隔が
//    熱運動の速さで決まっていてドリフト速度に依らないからで、熱運動を持たないこの模型に
//    その足場は無い。つまみを回したときの見かけは、1本の曲線のどこに居るかで決まる。
//    実測（電場を設定してから 1500tick 落ち着かせ、3000tick の時間平均）。電流は
//    **ほぼ積 qE だけの関数**で、q を5倍して E を 1/5 にした点どうしが 4% 以内で一致する：
//      qE    0.0025  0.006  0.0125  0.025  0.04  0.05  0.1   0.2
//      電流     26     43      69    124   196   228   413   754
//      （qE = 0.0025 / 0.006 / 0.04 は q=−0.002 で測った点。ほかは q=−0.01）
//    この1本の曲線の両対数の傾きは、qE が小さいところで 0.6、0.0125 より上では 0.87。
//    q=−0.002・直角の角だった頃の既定（qE=0.006）は傾き 0.6 の側で、速さはきれいに √E
//    （E=1.25〜20 で 70 / 99 / 133 / 195 / 274 px/s ＝ 指数 0.51）だった。これは
//    「1周に決まった回数だけ角で止まる」弾道的なふるまい。いまの既定（qE=0.03）は
//    傾き 0.87 の側なので、つまみを回すとほぼ比例しているように見える。
//    **曲線の上の居場所が変わっただけで、機構は足されていない。** 対照として角を丸める
//    だけ（q は −0.002 のまま）では傾きは 0.65 → 0.73・速さの指数は 0.51 → 0.55 しか
//    動かず、指数が上がったぶんの大半は電気量のほうから来ている。
//    見せられるのは「電圧を上げれば流れが速くなる・抵抗を通ると遅くなる」までで、
//    デモの本文もそこまでしか書いていない。
//  ★電子どうしのクーロン反発は**入れてある**が、実効定数 50 は既定（2）の 25 倍で、
//    これは物理の要請ではなく見せかたの都合。そこは正直に書いておく：
//      ・本物の金属では、電子どうしの反発は陽イオンの正電荷に遮蔽されて隣の電子との
//        あいだにはほとんど残らない。だからこそ「自由」電子模型が成り立つ。
//        金属の物理としていちばん正しいのは、実は切っておくことのほう。
//      ・一方、既定の 2 では効きが電場の 1/300 しかなく、電子が数珠つなぎにくっついて
//        並ぶ。遮蔽の話を知らない人には、そちらのほうが嘘に見える。
//      ★この 1/300 は q=−0.002 だった頃の比。反発は積 k·q で効き、押す力は qE で効くので、
//        q=−0.01 にした今なら同じ k=2 で 1/60 にあたる（換算。実測ではない）。
//        k を 50 に置いているのは、この比を 1 前後まで戻すため。
//  ★**スイッチを切ると電子は押し合って縮む。これは残っている嘘**（ただし電気量を
//    −0.01 にしてからは、接触するほどの行列にはならない）。本物の金属なら、切れ目に
//    電荷が溜まったとたんにその電場が電池の電場を打ち消すので、電子はその場で止まるだけで
//    詰まらない（余剰は電子全体の 10⁻¹⁶ 程度＝目に見えない）。この模型の電場は外から
//    与えっぱなしで打ち消されないので、押し続けられて縮む。
//    ★縮んだ列の隙間は **√(k·q/E)** で決まる（反発 kq²/r² が押す力 17qE と釣り合う所）。
//      実測3点がこの式に乗る（乱数固定・スイッチを切って 1500tick 置いてからの 1500tick、
//      隣との距離／接触している割合）：
//        k=50・q=0.002・E=7 → 14.2px／0.87    k=400・q=0.002・E=7 → 25.5px／0.19
//        k=50・q=0.01 ・E=3 → 29.6px／0.245   ＝ 予測 31px
//        k=50・q=0.01 ・E=2 → 35.7px／0.052   ＝ 予測 38px（★いまの既定）
//      ★**q を上げるのは k を上げるのと同じ効き**（どちらも積 kq）だが、q は押す力 qE も
//        一緒に上げるので、流れが速くなるぶんが代償として付く。いまの kq=0.5 は
//        「k=250・q=0.002」と等価で、下の表で凍結が出た k=1500（kq=3）よりずっと手前。
//        実測でも電圧 0.5〜20 のどこでも凍結なし（静止率 ≤0.004・最大 0.01）。
//    ★**反発を強くして離すのは、上限の壁に当たる。** 行列の先頭は後ろ17個ぶん（17qE）を
//      受け止めるので、接触距離 14px で釣り合わせる k は 17·E·(r²+ε²)/q ≈ 1550 要る。
//      ところがそこまで上げると、こんどは弱い電場で反発が電子を格子へ押しつけて止める。
//      実測（★以下は q=−0.002 だった頃の表。乱数固定・落ち着かせてから 3000tick の
//      時間平均。「切ったあと」はスイッチを閉じて 1500tick 置いてからの 1500tick。
//      隣との距離／接触している割合）：
//        k=  50：電圧7 電流55・凍結なし ／ 切ったあと 14.2px・0.87
//        k= 400：電圧7 電流51・凍結なし ／            25.5px・0.19
//        k=1500：電圧7 電流55・凍結なし ／            48.4px・0.003
//                **ただし電圧1で1個が完全に凍結**（静止率 1.00）
//        k=3000：電圧2 で凍結・電流は 8 まで落ちる
//      ★対照：k=0 と k=50 なら電圧1でも凍結しない＝上の凍結は電圧ではなく反発が原因。
//    ★2026-09-22、遮蔽つき（湯川型 F = kq₁q₂/r²·e^(−r/λ)、k=8000・λ=0.25m）を実装して
//      撤去した。数字は良かった（電圧 20/7/2/1/0.5 のどれでも凍結なし・接触ほぼ0、
//      電流は 107／52／36／19／19 で k=50 の 105／55／26／17 と同じ）。撤去したのは、
//      **遮蔽が新しい力ではなく、まわりの電荷がつくるふつうのクーロン力の和だから**。
//      本来は電荷を並べれば自然に出るもので、この模型で出ないのは陽イオンに電荷を
//      持たせていない・電子が18個しかない、というこちらの都合による。和で出るはずの
//      ものを別の法則として足すのは、この app の流儀に合わない（js/app/clipper.js の★）。
//    いま効いている手は2つ。**電場を弱くする**（OHM_E0 = 2）と**電気量を上げる**
//    （OHM_E_Q = −0.01）で、切ったあとの接触は 0.87 → 0.052・隣との距離は 14.2 → 35.7px
//    になった＝電子は縮むが、もう触れ合わない。めり込みは元から無い。
//  ★重力も切る（電子に重さの影響は無い。箔検電器と同じ理由）。この図は回路図と同じく
//    正面から見た図なので、世界の重力ごと 0 にして地面も出さない。
//  ★2026-09-23 当たり判定（_satCirclePoly、js/physics/collision.js）を直した：分解でできた細い
//    三角形が、向こう側の面の向きで電子を押し抜いていた。この輪では**丸めた四隅**で起きていて、
//    角が隠れたブレーキになっていた。直したあとの実測（電圧 2・1500tick 落ち着かせてから
//    4000tick。左の辺の中央を横切った回数／導線と抵抗の中の速さ）：
//      直す前 147・導線 437／抵抗 126 px/s（比 3.47） → 直したあと 163・494／142（比 3.48）
//    流れが 1 割ほど速くなった。比は変わらない。下の★の表はどれも直す前の値。
//  ★2026-09 電磁気の力を半分ずつ位置の前後で効かせるようにした（step.js の★）。同じ手順で
//    旧／新（横切った回数・導線／抵抗の速さ px/s）：
//      電圧 0.5  48・135／61 →  41・126／58      電圧 5   326・818／318 →  315・800／301
//      電圧 1    83・262／84 →  80・262／84      電圧 20 1172・2374／1706 → 1328・2643／2071
//      電圧 2   164・497／141 → 166・500／142（既定。上の 163・494／142 が旧で再現した）
//    凍結はどの電圧でも新旧とも無し（静止率 最大 0.001）。切ったあと（下の OHM_E0 の表と同じ手順）
//    の隣との距離／接触：電圧 2 33.4px／0.054 → 33.9／0.052、5 26.3／0.187 → 26.7／0.146、
//    7 23.5／0.220 → 22.7／0.287。
const OHM_WALL   = 40;     // [px] 枠の厚み
const OHM_CORR   = 90;     // [px] 通路の幅
const OHM_OUT_W  = 880;    // [px] 枠の外寸
const OHM_OUT_H  = 540;
// 通路の中心線（枠の内側と島の外側のちょうど真ん中）。ここを一周する角丸長方形を基準に、
//   イオンも電子も電場の帯も並べる（角の丸みは OHM_CR）。
const OHM_XR = OHM_OUT_W/2 - OHM_WALL - OHM_CORR/2;   // 355
const OHM_YB = OHM_OUT_H/2 - OHM_WALL - OHM_CORR/2;   // 185
const OHM_XL = -OHM_XR, OHM_YT = -OHM_YB;
// 角の丸み（通路の中心線がたどる円弧の半径 [px]）。
//   ★直角の角では、電子は外側の壁に正面からぶつかって行き足を失い、斜めの場に押し直されて
//     出ていく。角を円弧にすると外側の壁の法線がなめらかに回るので、電子は当たったまま
//     壁に沿って滑って曲がれる（円弧は detectArcs が本物の円弧として持つので、
//     多角形の角のたびに法線方向の速度を吸われることもない）。
//     実測は冒頭の★（導線の中の速さ 131 → 218 px/s・一周 27 → 21秒。抵抗の中の速さは
//     48 → 50 で動かない）。★ただし I-V の指数はほとんど動かなかった（速さの指数
//     0.51 → 0.55）＝**√E のふるまいは角だけのせいではない**。
//   ★この値は「通路の幅と同じ」。中心線の半径 90 ＝ 外側の壁の丸み 135・島の角の丸み 45 で、
//     どちらも 0 にならない（島の側も丸くなる＝通路の幅がどこでも 90 で一定になる）。
//     45 未満にすると島の角が尖ったまま残り、丸めた意味が外側の壁だけになる。
const OHM_CR = 90;
const OHM_ION_R   = 16;    // [px] 陽イオンの半径。★13 から上げてある（下の段の並べかたの★）
// 抵抗の段。中央の2段（±OHM_OFF_C）と、壁に半分埋めた2段（±OHM_OFF_E）を順に繰り返す。
//   ★**玉の中心を置いてよい場所には、通ってはいけない帯がある**。壁の面から電子の直径
//     （14px）より狭い隙間に玉の面が立つと、そこが電子の抜けられない楔になるため。
//     半幅 h=45・玉 r・電子 e=7 として、危ないのは h−r−2e < |off| < h−e ＝ **15〜38**。
//     中央の段（±6）はこの下、埋めた段（±45）はこの上にある。
//   ★埋めた段を「面の上」に置く意味。電子の中心が来られるのは面から半径ぶん内側までで
//     38 が限界なので、玉の中心（45）は必ずそれより外にある＝どこで触れても玉は電子を
//     **通路の内側へ**押し返す。玉が壁をすり抜けられること（OHM_LAYER_ION）が前提。
//   ★中央の段を ±6 で振るのは、通路の中心線に乗った電子が正面衝突のまま釣り合うのを
//     防ぐため（もとは ±4px の乱れで崩していた）。決め打ちなので開くたび同じ形になる。
//   ★4段で通路の幅（電子の中心が居られる −38〜+38）を隙間なく覆う：
//     中央 +6 が −17〜+29、中央 −6 が −29〜+17、埋めた ±45 が ±22 から外。
//     どの高さを選んでも、1周期のあいだに必ずどれか1つに行く手を塞がれる。
const OHM_OFF_C   = 6;     // [px] 中央の段の振り分け幅
const OHM_OFF_E   = OHM_CORR / 2;   // [px] 壁に埋めた段（＝通路の面の上）
const OHM_ROWS    = [OHM_OFF_C, OHM_OFF_E, -OHM_OFF_C, -OHM_OFF_E];
const OHM_PITCH_R = 34;    // [px] 抵抗のイオン間隔。★1周期が3個から4個になったぶん、
                           //   46 では覆いが半分の密度になる。玉の半径と2つで決めた。
                           //   実測（乱数固定・落ち着かせてから 4000tick の時間平均。
                           //   電流＝左の辺の中央を横切った回数／抵抗の中と導線の速さ）：
                           //     半径13 間隔46  電流92  抵抗136・導線235 px/s（1.7倍）
                           //     半径13 間隔34  電流83  抵抗102・導線231     （2.3倍）
                           //     半径16 間隔34  電流71  抵抗 78・導線235     （3.0倍）★これ
                           //     半径16 間隔26  電流67  抵抗 70・導線237     （3.4倍）
                           //     半径19 間隔26  電流59  抵抗 56・導線239     （4.3倍）
                           //   これより詰めても比は伸びず、抵抗の中の電子どうしの接触だけが
                           //   増える（0.029→0.038）。前の並べかた（半径13・間隔46・±28 の
                           //   3段）は 電流69・抵抗68/導線241 で、比は近いが中身が違う：
                           //   あちらは時間の 41% を抵抗の中で過ごし接触 0.18 ＝**詰まって**
                           //   遅かった。こちらは 42% を過ごして接触 0.029 ＝弾かれて遅い
const OHM_RES_HALF = 200;  // [px] 抵抗の区間（下の辺の中央から左右へ）
// 衝突レイヤー。★マスク方式は推移的でない（js/core/units.js の★）ことをそのまま使う：
//   玉は壁をすり抜け、電子は両方に当たる。これで玉を壁に半分埋めて置ける。
//   埋められないと、壁の面から電子の直径より狭い隙間に玉が立つことになり、そこが
//   電子の抜けられない楔になる（ファイル冒頭の★）。
const OHM_LAYER_WALL = 0b0001;   // 壁・スイッチの板
const OHM_LAYER_ION  = 0b0010;   // 陽イオン（壁とは当たらない）
const OHM_LAYER_E    = 0b0011;   // 自由電子（壁にも玉にも当たる）
const OHM_LAYER_SPR  = 0b1000;   // ばね（誰とも当たらない。玉の中に隠れている飾り）
const OHM_BALL_M  = 0.02;  // [kg] 玉の質量（電子の2倍。よく弾かれ、よく戻る）
const OHM_BALL_K  = 2;     // [N/m] 玉をつなぐばねの定数。★2026-10-04 まで 20 と書いてあったが、demoSpring の
                           //   自然長の切り上げの食い違い（demo-kit.js の★）で実際は 10分の1 の 2 N/m で効いていた。
                           //   このファイルの★の実測はすべてその 2 N/m で取ったものなので、直したときに値のほうを
                           //   実際に効いていた 2 へ合わせた（挙動は変わらない）。本当に 20 N/m にすると、
                           //   電圧 2 で 電流 134 → 65・導線 514 → 351 px/s・抵抗 158 → 89 px/s と流れが半分になった
                           //   （1500tick 落ち着かせて 4000tick。凍結・通路外は 0 のまま）
const OHM_BALL_C  = 0;     // [N·s/m] ばねの減衰。★0 にすること（ファイル冒頭の★）
const OHM_E_R  = 7;        // [px] 電子の半径（箔検電器の動ける電荷と同じ）
const OHM_E_M  = 0.01;     // [kg] 電子の質量
const OHM_E_Q  = -0.01;    // [C]  電子の電気量。★符号が負であることが読みどころ
                           //   ★比電荷 q/m = 1.0（−0.002 から5倍にした）。実物の値ではなく
                           //     「目で追える速さ」で決めてある。実測（乱数固定・角丸の通路・
                           //     電圧 3・1500tick 落ち着かせてから 3000tick の時間平均。
                           //     電流＝左の辺の中央を横切った回数）：
                           //       q=−0.002：電流  43・導線 218／抵抗 50 px/s（比 4.4）一周 21秒
                           //       q=−0.01 ：電流 154・導線 547／抵抗 183 px/s（比 3.0）一周 5.8秒
                           //     ★代償は2つ。**流れが速い**（電圧 3 で一周 5.8秒。既定の倍率だと
                           //       画面を 1.6秒 で横切る）ことと、**抵抗の中と導線の速さの比が
                           //       4.4 → 3.0 に縮む**こと。速さを戻すのは電気量ではなく
                           //       OHM_E0（つまみの初期値）を下げるほうで、既定は 2：一周 8.3秒・
                           //       導線 420／抵抗 128（比 3.3）。さらに 電圧 1 で 210／79（比 2.7）、
                           //       電圧 0.5 で 113／58（比 2.0）。
                           //     ★得は、スイッチを切ったときの行列がほぐれること。反発は q² で
                           //       効くのに押す力は q なので、q を上げると反発だけが勝つ
                           //       （切ったあとの接触 0.53 → 0.057。ファイル冒頭の★）
const OHM_N_E  = 18;       // 電子の数
const OHM_E0   = 2;        // [V/m] 電場の強さ（＝つまみ〈電圧〉の初期値）。
                           //   ★7 → 3 → 2 と下げてきた。スイッチを切ったときに電子が押し潰されて
                           //     並ぶのを、いちばん小さい作りで緩めるため（下の★）。
                           //     実測（乱数固定・角丸の通路・q=−0.01。1500tick 落ち着かせてから
                           //     板を実体にし、さらに 1500tick 置いて 3000tick の時間平均。
                           //     切ったあとの 隣との距離／接触している割合）：
                           //       電圧 7 → 23.3px／0.260
                           //       電圧 5 → 25.9px／0.202
                           //       電圧 3 → 29.6px／0.245
                           //       電圧 2 → 35.7px／0.052  ★これ
                           //     めり込みはどれも無い（電子の直径は 14px）。
                           //     ★この表は測り直した値で、3 を既定にしたときの記録（7→23.2／0.267、
                           //       5→26.6／0.144、3→33.4／0.057）とは電圧 3 の行が再現しない。
                           //       種を変えても板を閉じる位相を 40tick ずらしても動かない
                           //       （0.245→0.253）ので、ばらつきではなく測りかたか作りの差。
                           //       **接触の割合は 3 付近では信用しない**。2 は距離・接触とも余裕がある。
                           //     ★q=−0.002 だった頃の同じ表は 14.2／14.7／16.9px＝どの電圧でも
                           //       接触していた。いまほぐれているのは電気量のほうの効き
                           //       （ファイル冒頭の √(k·q/E) の★）。
                           //   ★代償は流れが遅くなること：電圧 7 と 2 で 電流 290 → 108、
                           //     導線の中の速さは 892 → 420 px/s、抵抗の中は 407 → 128 px/s。
                           //     比はむしろ 2.2 → 3.3 と開く（速いほど抵抗を素通りする）
const OHM_COULOMB_K = 50;  // 実効クーロン定数。★既定は 2。上げ幅の根拠はファイル冒頭の★
const OHM_EMAX = 5;        // [V/m] つまみの上限。★既定 2 の 2.5倍まで。20 まで振れると
                           //   つまみの手前 1/10 に題材が全部入ってしまい、上へ回すほど
                           //   電子が押し潰されて並ぶだけ（上の表の 7 の行）になる
const OHM_GATE_X = 200;    // [px] スイッチの位置（上の辺）。★説明文は画面の左うえなので、
                           //   文字に掛からない右寄りに置く
const OHM_GATE_T = 18;     // [px] 板の厚み（通路に沿った向き）
const OHM_GATE_H = OHM_CORR + 8;   // [px] 板の丈。★通路の幅いっぱい＋壁へ 4px ずつ食い込ませる。
                           //   遊びを残すと電子（半径7）が縁をかすめて抜ける。壁も板も固定
                           //   なので、めり込ませても物どうしの当たりには何も起きない

// 通路の中心線を一周する。s は周長に沿った長さ [px]。角は半径 OHM_CR の円弧をたどる。
//   返す n は通路の幅方向の単位ベクトル（イオンを左右へ振り分けるのに使う）。
//   ★n は「通路の内側＝島の側」を向く。円弧では弧の中心を向く向きがそれにあたり、
//     手前の直線の n と継ぎ目でぴったり一致する（＝off の意味が一周そろう）。
const OHM_STRX = () => (OHM_XR - OHM_XL) - 2*OHM_CR;   // 上下の直線の長さ
const OHM_STRY = () => (OHM_YB - OHM_YT) - 2*OHM_CR;   // 左右の直線の長さ
const OHM_ARC  = () => Math.PI/2 * OHM_CR;             // 角1つの弧長
function ohmLoopPoint(s) {
  const LX = OHM_STRX(), LY = OHM_STRY(), ARC = OHM_ARC();
  const PER = 2*(LX + LY) + 4*ARC;
  s = ((s % PER) + PER) % PER;
  // 角の円弧。(cx,cy) は弧の中心、a0 から t（0→1）で 90°進む
  const arc = (cx, cy, a0, t) => {
    const a = a0 + (Math.PI/2) * t;
    return { x: cx + OHM_CR*Math.cos(a), y: cy + OHM_CR*Math.sin(a),
             nx: -Math.cos(a), ny: -Math.sin(a) };
  };
  const XI = OHM_XR - OHM_CR, XJ = OHM_XL + OHM_CR;    // 角の弧の中心（通路より内側）
  const YI = OHM_YT + OHM_CR, YJ = OHM_YB - OHM_CR;
  if (s < LX)  return { x: OHM_XL + OHM_CR + s, y: OHM_YT, nx: 0, ny: 1 };  s -= LX;
  if (s < ARC) return arc(XI, YI, -Math.PI/2, s/ARC);                       s -= ARC;
  if (s < LY)  return { x: OHM_XR, y: YI + s,            nx:-1, ny: 0 };    s -= LY;
  if (s < ARC) return arc(XI, YJ, 0,          s/ARC);                       s -= ARC;
  if (s < LX)  return { x: OHM_XR - OHM_CR - s, y: OHM_YB, nx: 0, ny:-1 };  s -= LX;
  if (s < ARC) return arc(XJ, YJ, Math.PI/2,  s/ARC);                       s -= ARC;
  if (s < LY)  return { x: OHM_XL, y: YJ - s,            nx: 1, ny: 0 };    s -= LY;
  return             arc(XJ, YI, Math.PI,     s/ARC);
}
function ohmLoopPerimeter() { return 2*(OHM_STRX() + OHM_STRY()) + 4*OHM_ARC(); }
// 抵抗の区間（下の辺の中央）の始まり。周に沿った長さ [px] で返す。
//   下の直線は「上の直線 → 角 → 右の直線 → 角」の次なので、その先頭から中央へ寄せた分だけ進む。
function ohmResistorStart() {
  return OHM_STRX() + OHM_STRY() + 2*OHM_ARC() + (OHM_STRX()/2 - OHM_RES_HALF);
}
// その場所が抵抗の区間の中か
function ohmInResistor(p) { return p.y === OHM_YB && Math.abs(p.x) <= OHM_RES_HALF; }

// 陽イオン（抵抗の区間の玉）を置く。オームの法則モデルと平行板コンデンサーモデルで共用。
function ohmPlaceIons(CX, CY) {
  // ── 陽イオン：ばねで格子点につないだ玉（ファイル冒頭の★）──
  //   ★ばねは自然長ゼロ（Slinky の下限 0.01m ＝ 1px）で格子点に留める。長さを持たせて
  //     壁へ渡すと、たるんだ向きには戻す力が無いので玉が通路を横へ流れていく。
  //     自然長ゼロなら「どの向きへずれても同じだけ引き戻す」＝格子に縛られた1個の
  //     イオンそのものになる（手で作るときは、ばねを張ってから自然長を下限まで縮める）。
  //   ★玉には重力を効かせない。この図は正面から見た回路図で、世界の重力も 0 にしてある
  //     （両方切っておくと、あとで重力を入れて遊んでも格子が垂れ下がらない）。
  //   ★玉を置くのは**抵抗の区間だけ**。導線の側には置かない。導線は「抵抗を無視する」
  //     のが回路の約束で、そこにも玉を散らすと「どこが抵抗なのか」がぼやける。
  //   ★**壁より先に置く**。objects の並び＝描画順（後ろほど手前）なので、あとから置く壁が
  //     壁に埋めた段の外半分を隠してくれる。逆にすると、玉が壁の上に乗っているように
  //     見える＝導線の外にイオンがあることになってしまう。手で作るときは一覧で並べ替える。
  const ions = [];
  { let s = 0, k = 0;
    while (s < OHM_RES_HALF * 2) {
      const p = ohmLoopPoint(ohmResistorStart() + s);
      const off = OHM_ROWS[k % OHM_ROWS.length];      // 中央±・壁埋め± を順に
      const bx = CX + p.x + p.nx*off, by = CY + p.y + p.ny*off;
      const b = new Body({ type:'circle', x:bx, y:by, radius:OHM_ION_R,
        mass:OHM_BALL_M, hasGravity:false, fixedRotation:true, layers:OHM_LAYER_ION,
        friction:0, frictionStatic:0, restitution:0,
        fillColor:'#ef5350', strokeColor:'#ffcdd2', strokeWidth:1.2 });
      objects.push(b); ions.push(b);
      const spr = demoSpring({ bodyB:b, anchorAx:bx, anchorAy:by, restLength:0,
                   stiffness:OHM_BALL_K, damping:OHM_BALL_C, radius:5, color:'#ff8a65' });
      if (spr) spr.layers = OHM_LAYER_SPR;
      s += OHM_PITCH_R; k++;
    }
  }
  return ions;
}

function demoOhmModel() {
  resetDemoWorld();
  setDemoGravity(0);              // ★正面から見た図。地面も重力も出さない
  updateGroundTerrain(false);
  world.sleeping  = false;
  world.substeps  = 8;
  world.coulombOn = true;                 // ★電子どうしの反発。強さの根拠はファイル冒頭の★
  world.coulombK  = OHM_COULOMB_K;

  setDemoCam(0, 0.62);
  const CX = 0, CY = cam.y + 180;   // ★説明文の下へ輪を置く（本文は画面の左うえ）
  const metal = { fillColor:'#78909c', strokeColor:'#b0bec5', strokeWidth:1.5,
                  friction:0, frictionStatic:0, restitution:0 };

  const ions = ohmPlaceIons(CX, CY);

  // ── 通路：外側の枠と内側の枠。どちらも型抜きした「わっか」で、中は空 ──
  //   ★内側も型抜きする。ここを中身の詰まった板にすると、金属の塊に溝を彫ったように
  //     見えてしまう。**これは導線なので、描くべきは管の壁2枚と、そのあいだを通る電荷**。
  //     輪の内側は導線の外（＝何も無い）でなければならない。
  //   ★角の丸みは「縦の板＋横の板＋四隅の円」の図形和で作る（OHM_CR の★）。
  //     手で作るときもこの6部品を図形和するだけで、専用の道具は要らない。
  //     型抜きのあと detectArcs（js/app/clipper.js）が円の区間を円弧として拾い直すので、
  //     丸めた角は48角形ではなく本物の円弧として残る＝電子が滑っても行き足を失わない。
  const roundParts = (A, B, R) => {
    const mk = o => new Body(Object.assign({ isStatic:true }, metal, o));
    const ps = [ mk({ type:'box', x:CX, y:CY, w:2*A,       h:2*(B - R) }),
                 mk({ type:'box', x:CX, y:CY, w:2*(A - R), h:2*B       }) ];
    for (const sx of [-1, 1]) for (const sy of [-1, 1])
      ps.push(mk({ type:'circle', x:CX + sx*(A - R), y:CY + sy*(B - R), radius:R }));
    return ps;
  };
  // 角丸の板から、一回り小さい角丸の板を抜く（型抜きは「最初 − あと全部」）
  const ring = (A, B, R) => demoBoolean('diff',
    [ demoUnion(roundParts(A, B, R)),
      ...roundParts(A - OHM_WALL, B - OHM_WALL, R - OHM_WALL) ]);
  ring(OHM_OUT_W/2, OHM_OUT_H/2, OHM_CR + OHM_CORR/2 + OHM_WALL);    // 外側の壁
  ring(OHM_XR - OHM_CORR/2, OHM_YB - OHM_CORR/2, OHM_CR - OHM_CORR/2);   // 内側の壁（島）

  // ── 自由電子：イオンの隙間へ入れる ──
  //   ★置き場所は「周に沿って等間隔」を狙いつつ、イオンに重なる所は避けて少しずらす。
  //     重ねて置くと開いた瞬間に位置補正で弾かれ、壁の中へ押し出されることがある。
  { const PER = ohmLoopPerimeter(), step = PER / OHM_N_E;
    const clear = (x, y) => ions.every(i => (i.x - x)**2 + (i.y - y)**2
                                          > (OHM_ION_R + OHM_E_R + 4)**2);
    for (let i = 0; i < OHM_N_E; i++) {
      let put = null;
      for (let d = 0; d < 60 && !put; d += 4)                    // 周に沿って前後へ探す
        for (const sgn of (d ? [1, -1] : [0]))
          for (const off of [0, 30, -30, 15, -15]) {
            if (put) continue;
            const p = ohmLoopPoint(i*step + sgn*d);
            const x = CX + p.x + p.nx*off, y = CY + p.y + p.ny*off;
            if (clear(x, y)) put = { x, y };
          }
      if (!put) continue;
      objects.push(new Body({ type:'circle', x:put.x, y:put.y, radius:OHM_E_R,
        mass:OHM_E_M, charge:OHM_E_Q, hasGravity:false, fixedRotation:true, layers:OHM_LAYER_E,
        friction:0, frictionStatic:0, restitution:0,
        fillColor:'#42a5f5', strokeColor:'#e3f2fd', strokeWidth:1.2 }));
    }
  }

  // ── 電場：通路の直線4本と角4つに、それぞれ1枚ずつ帯を置く ──
  //   向きは一周して時計回り（＝電流の向き）。角の1枚は前後の直線のちょうど中間＝斜め。
  //   ★強さは8枚とも同じにする。抵抗のところだけ強くすれば「どこでも電流が同じ」に
  //     近づけられる（実際の回路でも電位は抵抗のところで大きく下がる）が、〈電圧〉の
  //     つまみは相手全部へ**同じ値**を書くので、触った瞬間にその比が消える。
  //     「電池の電圧を変えたのに導線の電場だけ変わった」になるほうが嘘が大きいので、
  //     均一のままにして、溜まりは抵抗の詰めかた（OHM_PITCH_R）で加減する。
  //   ★角に専用の1枚を置く。以前は長い帯4枚を角で 90×90 だけ重ね、重ね合わせで斜めの
  //     場を作っていた。角を丸めるとその重なりは曲がりの外側 1/4 しか覆わず、島の側に
  //     場のない区画ができる（角を無風にすると電流が 93 → 11 に落ちる）。それに重なりの
  //     ぶんは大きさが √2 倍になっていて、「導線の中の電場の大きさは一周そろっている」
  //     という約束からも外れていた。直線を角の手前で終わらせて角に1枚置くと、
  //     曲がりの全体が覆われ、大きさもどこでも同じになる。
  const CS = OHM_CR + OHM_CORR/2;                 // 角の帯の一辺（曲がりをちょうど覆う）
  const band = (x, y, w, h, angle) => emFields.push(new EMField({
    kind:'E', x:CX + x, y:CY + y, w, h, strength:OHM_E0, angle }));
  band(0, OHM_YT, OHM_STRX(), OHM_CORR,  0);          // 上の直線：→
  band(OHM_XR, 0, OHM_CORR, OHM_STRY(),  Math.PI/2);  // 右の直線：↓（内部yは下向きが正）
  band(0, OHM_YB, OHM_STRX(), OHM_CORR,  Math.PI);    // 下の直線：←
  band(OHM_XL, 0, OHM_CORR, OHM_STRY(), -Math.PI/2);  // 左の直線：↑
  //   ★並べる順は右上→右下→左下→左上（＝場の向きが π/2 ずつ回る向き）。
  for (let i = 0; i < 4; i++) {
    const sx = (i <= 1) ? 1 : -1, sy = (i === 0 || i === 3) ? -1 : 1;
    band(sx * (OHM_XR + OHM_CORR/2 - CS/2), sy * (OHM_YB + OHM_CORR/2 - CS/2),
         CS, CS, Math.PI/4 + i * Math.PI/2);
  }

  // ── スイッチ：通路をふさぐ板。上の辺に差し込んである ──
  //   ★**動かすのではなく、すり抜けるかどうかを切り替える**。刃を上下させる作りだった
  //     ときは、閉じる・開くで2台のリモコンが要り、押しっぱなしの行き過ぎで板が壁から
  //     抜けてしまう余地もあった（〈手で動かす〉は逆質量0なので当て止めが効かない）。
  //     スイッチに要るのは「通るか通らないか」の2状態だけなので、位置ではなく
  //     衝突レイヤーを切り替える。1台のリモコンで、行き過ぎも途中の状態も無い。
  //   ★固定した物体にする（電子に押されて動いてほしくない）。
  const gate = new Body({ type:'box', x:CX + OHM_GATE_X, y: CY + OHM_YT,
    w:OHM_GATE_T, h:OHM_GATE_H, isStatic:true, layers:0,
    friction:0, frictionStatic:0, restitution:0,
    label:'スイッチの板', fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1.5 });
  objects.push(gate);

  // ── 操作：電圧のつまみ1つと、スイッチ1つ ──
  //   ★電圧のつまみは4枚の帯を**1台で**まとめて動かす。4台に割ると「4つの別々の
  //     電源」に見えるし、ばらばらに動かせてしまう（1本の導線の中の電場なので、
  //     一周そろって強くなる以外の状態は題材に無い）。
  const volt = addRemote('prop', emFields[0], 'emfield', emFields.map(f => f.id));
  if (volt) {
    volt.prop = 'strength'; volt.lo = 0; volt.hi = OHM_EMAX;
    volt.fx = 0.795; volt.fy = 0.04;
    placeRemotePanel(volt); syncRemotePanel(volt);
  }
  // ★スイッチは〈すり抜けにする〉1台。板は最初すり抜け（layers 0）＝電流が流れている姿で
  //   開き、押すと実体になって通路をふさぐ。戻す先は壁と同じレイヤーにしておく。
  const sw = addRemote('ghost', gate, 'body');
  if (sw) {
    sw.key = 'ArrowDown'; sw.savedLayers = OHM_LAYER_WALL;
    sw.fx = 0.795; sw.fy = 0.28;
    placeRemotePanel(sw); syncRemotePanel(sw);
  }

  // ── 電池（絵。物理には参加しない）──
  //   ★向きは実際の流れと合わせる：左の辺の電流は上向きなので、電池の中を下から上へ
  //     通る＝下が − ・上が ＋。ここを逆に描くと絵だけが嘘をつく。
  //   ★左の辺のまん中に置く。玉は抵抗の区間にしか居ないので、ここに重なる物は無い
  //     （注釈は物体より奥に描かれるので、玉と重ねると極板がその下へ隠れる）。
  const BAT = '#ffd54f';
  const bx = CX + OHM_XL, by = CY;
  const plate = (dy, half) => demoPath([{ x:bx - half, y:by + dy }, { x:bx + half, y:by + dy }], BAT, 5);
  plate(-24, 34); plate(-10, 15); plate(6, 34); plate(20, 15);
  const ts = demoTextScale(cam.zoom);
  demoLabel(bx - 92, by - 48, '＋', BAT, DEMO_NOTE_SIZE * ts, true);
  demoLabel(bx - 92, by + 34, '−', BAT, DEMO_NOTE_SIZE * ts, true);
  demoLabel(bx - 176, by + 62, '電源（絵）', BAT, DEMO_NOTE_SIZE * ts, true);
  // 図の中の札は輪の内側（導線の外＝何も無いところ）に置く。
  //   通路の上に置くと電子と重なって読めない
  demoLabel(CX - 250, CY - 78, '● 陽イオン（ばねで格子点につないである）',
            '#ef5350', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 250, CY - 42, '● 自由電子（たがいに反発する）',
            '#42a5f5', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 44, CY + 64, '抵抗', '#ef5350', DEMO_NOTE_SIZE * ts, true);
  // 導線の札は輪の上の空きへ（内側は凡例2行で埋まり、右はリモコンの窓が来る）。
  //   ★角を丸めたぶん、輪の左うえの外は壁から遠い。上の直線の真上に置く
  demoLabel(CX - 250, CY - OHM_OUT_H/2 - 26, '導線', '#b0bec5', DEMO_NOTE_SIZE * ts, true);

  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'オームの法則モデル', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    '導線を輪にして、管の壁を切って中を覗いた図。青い粒が自由電子で、たがいに反発する。\n'
  + '電池は絵で、電子を押しているのは通路にかけた電場。輪の内側は導線の外＝何も無い。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・電場の矢印＝電流の向きは時計回り。電子は負なので逆向きに流れる\n'
  + '・下の赤い玉を詰めたところが抵抗。玉は格子に並んだ陽イオンで、ばねでつないである\n'
  + '　電子はぶつかるたびに行き足を失い、失った分は玉の振動へ移る（これが発熱にあたる）\n'
  + '・〈電圧〉を上げると電場が強くなり、電子の流れが速くなる\n'
  + '・〈スイッチの板〉を押すと板が実体になって通路をふさぐ＝回路が切れる。\n'
  + '　もう一度押すと板がすり抜け（黄色の破線）に戻り、また流れ出す',
    DEMO_NOTE_SIZE * ts);

  // ★流れが定常になってからの姿で開く（立ち上がりは題材ではない）
  demoRunAhead(600);
}

// ── 平行板コンデンサーモデルの極板と仕切り（CAP_*）─────────────────────
//  ★2026-09-23 デモ本体は、電源と C1 の輪に並列の C2 の輪を足した版（旧・電気量保存モデル。
//    下の demoCapacitorModel）に置き換えた（指示）。以下の★は、輪1つだけだった頃の
//    平行板コンデンサーモデルで測った CAP_* の根拠として残す。
//  ★輪・電子・電場の帯・電池の絵は、オームの法則モデルと同じ作り（寸法も OHM_* を
//    そのまま使う）。違いは4つ：
//      ・右の辺の通路を膨らませた部屋＝極板（CAP_W × CAP_H）
//      ・部屋を上下に分ける仕切り（絶縁体。固定した板で、電子は通れない）
//      ・スイッチは通路をふさぐ板ではなく〈電源を切る〉＝電場の帯を全部 0 にする
//      ・**抵抗（陽イオンの玉）は置かない**。見たいのはコンデンサーの働きで、抵抗があると
//        「電流が止まったのは仕切りのせいか、抵抗で詰まったせいか」が分からなくなる（指示）
//  ★**放電を押しているのは、下の極板に詰まった電子どうしの反発**。電源を切ると、
//    仕切りに押しつけられていた電子が押し合って広がり、来た道を逆に流れる。
//    本物の放電は「−極板の余分な電子どうしの反発」と「+極板にむき出しになった陽イオンの
//    引力」の2つで押されるが、この模型の陽イオンは電荷を持たないので前半しかない。
//    しかも反発の強さ k=50 は見た目の都合で決めた値（OHM_COULOMB_K の★）。
//    ＝放電の**向きと起きること**は正しく、**強さ**は作りもの。
//  ★以前は仕切りの代わりに**ゴム膜**（実体のばね）を張っていた。膜が押し返して放電させる、
//    という水の回路の模型の見立てだった。やめた理由は3つ：
//      ・膜なしでも放電は起きた（下の実測。放電の流れは膜のとき 25→78→124→64 px/s）。
//        「反発だけでは押せない」と書いていたのは、電源を1か所に置いて押しを反発で
//        伝えさせる別の実験の結果で、放電は測っていなかった。
//      ・「電圧を上げると膜が大きくふくらむ」は電荷が増えたせいではなかった。どちらの作りでも
//        動ける電子はほぼ全部が極板へ集まり、変わったのは押す強さだけ（Q = CV に見えて違う）。
//      ・重い（膜だけで 1 tick に 2.3ms。オームの法則モデルまるごとと同じ）うえ、膜の端と
//        斜めの天井のあいだに電子が挟まる楔ができていた（CAP_HS の★）。
//  ★**電場は輪の全体にかけたまま**（オームの法則モデルと同じ）。電源の電圧を帯の全部で
//    表す作りなので、「電源を切り離して導線でつなぐ」はそのまま「帯を全部 0 にする」になる。
//    ★この作りの嘘は1つ残る：本物なら極板にたまった電荷の電場が導線の中の場を打ち消して
//      電流が止まるが、ここでは場が外から与えっぱなしなので、電子は止まる代わりに
//      仕切りの手前へ寄り集まり、**上の辺の導線は空になる**（下の実測の「上の辺」）。
//      オームの法則モデルの「スイッチを切ると縮む」と同じ嘘で、電子を 52 個まで増やしても
//      行き着く先が極板になるだけで消えなかった。同じ理由で **Q = CV も出ない**：たまる電子の
//      数は電圧でほとんど変わらない（下の表）。本文では「上の極板から出ていく」までしか言わない。
//  ★重さ（1 tick の計算時間。電源を入れた直後の 120tick の平均）：電子20・仕切り … 2.6ms
//    （ゴム膜のときは 4.7ms、オームの法則モデルは 2.1ms）。
//    膜を張っていた頃は 電子52・膜の節点93 で 18.3ms あり、60tick/秒 に追いつかず画面が詰まった。
//  ★仕切りと部屋の横の壁の角は丸めてある（CAP_FILLET の★。放電が最初の 5 秒で 2 倍前後に
//    速くなる）。下の表は丸める前の直角の値。
//  ★実測（乱数固定・電源を切って 300tick 置いてから。「流れ」は電子の輪に沿った速さの平均
//    [px/s]、−が充電の向き。「下の極板」は仕切りより下にいる電子の数）：
//      電圧 │ 充電 0〜10秒  10〜20秒 │ 下の極板 上の辺 │ 放電 0〜1秒 1〜3秒 3〜5秒 5〜20秒
//       1   │    −99       −1.1    │  11.8個   0個  │    +26     +77   +92    +56
//       2   │   −100       −2.6    │  15.9個   0個  │    +23     +58   +73    +58
//       3   │   −104       +0.4    │  17.1個   0個  │    +18     +45   +69    +65
//    （電子は全部で 20 個。上の極板に残った電子は充電 10〜20秒で 0 個）
//    充電の流れは止まり、切ると逆向きに流れる。★抵抗が無いので放電は減衰しにくく、
//    電子の行き足を奪うのは壁への反発0の衝突だけ。電子が仕切りを抜けたのも、通路の外へ
//    出たのも延べ 0 回。
//  ★部屋を膨らませる意味は面積 S（C = εS/d）。ただし上のとおり、この模型で電子がたまる数は
//    面積ではなく「動ける電子の数」で決まるので、たまる量の差としては出ない。
//    広い部屋は、たまった電子を仕切りに沿って並べて見せる場所として効いている。
const CAP_W    = 250;      // [px] 極板の部屋の幅（通路を横切る向き。通路は OHM_CORR = 90）
const CAP_H    = 190;      // [px] 部屋の丈（通路に沿った向き。右の辺の直線いっぱい）
// [px] 部屋の左右の壁の半分の丈。そこから上下は、通路の口へ向かって斜めにすぼまる（六角形）。
//   ★部屋の天井と床を**平らにしない**。平らだと、口（幅 OHM_CORR）の外側の天井が
//     電場に押し上げられた電子の行き止まりになる：場は部屋の中で真上（下）向きなので、
//     平らな天井に押しつけられた電子には横へ動かす力が無い。斜めにすれば、面に沿った
//     成分 qE·sinθ がいつも口のほうを向き、口が部屋のいちばん高い（低い）点になる。
//     ★角を丸めるのでは足りない：円弧のてっぺんは水平で、そこが通路の壁と直角に
//       ぶつかる隅になる（最も高い点がまた隅にできる）。
//   実測（乱数固定・電圧 2・充電を入れて 10〜20秒の時間平均。上の極板に残った電子。
//     ★ゴム膜を張っていた頃の値）：
//     平らな天井        … 4.0個（うち止まっている 2.1個）
//     斜め・縦の壁 20px … 1.0個（0.5個）
//     斜め・縦の壁 40px … 0個 ★これ
//   ★20 で残った1個は、膜の端の留め具のすぐ上＝膜と斜めの天井のあいだの楔にいた。
//     仕切り（平らな板）にしたいまはその楔は無いが、40 のままで実測 0 個なので変えていない
//     （仕切りでの値は冒頭の★の表）。
//   ★ここを変えると部屋の電子の置き場所（dy=25 の段）も見直すこと。
const CAP_HS   = 40;
const CAP_N_E  = 20;       // 電子の数（通路に沿って並べるぶん＋部屋に足すぶん）。★重さの★
const CAP_N_ROOM = 6;      // そのうち部屋に足す数（面積のぶん多く入れておく）
const CAP_E0   = 2;        // [V/m] 電源を入れたときの電場（オームの法則モデルの OHM_E0 と同じ）
const CAP_EMAX = 3;        // [V/m] つまみの上限。★膜を張っていた頃、4 で膜が部屋からはみ出した名残。
                           //   仕切りにした今ははみ出す物は無いが、オームの法則モデルの OHM_EMAX（5）
                           //   より低くしておく：電圧を上げても、たまる電子はほとんど増えない（冒頭の表）
// [px] 仕切りの厚み。★電子の直径（14px）より薄くてよい：固定した板なので押されても
//   たわまず、当たり判定は板の面そのもの（すり抜けは実測 0）。薄いほど「極板のすき間 d は
//   小さい」という平行板の形に見える
const CAP_GAP  = 10;
// [px] 仕切りと部屋の横の壁の角の丸み（直角の角を四分円でつなぐ。指示）。
//   ★実測（旧・電気量保存モデル＝いまの平行板コンデンサーモデル。S2 を入れるタイミングを 5 通りずらした平均。C1 の下の極板の電子 [個]）：
//                 S2 から 5〜20秒   40〜60秒（C2 の下の極板）
//     直角（0）        7.5           4.6（4.1）
//     15px ★これ      4.8           4.4（3.6）
//     30px             7.0           7.0（3.6）…5 回とも 7.0 で止まった
//   15 は、半分ずつに分かれるまでが速くなる（行き着く先は直角とほぼ同じ）。30 は横の壁の
//   縦の部分（仕切りの面から 35px）をほとんど丸みが食い、C1 に電子が残ったまま動かなくなる。
//   ★輪1つだった頃の平行板コンデンサーモデルにも同じ丸みを付けた（指示）。実測（電源を 20 秒入れて切る。
//     「流れ」は輪の中心まわりの電子の速さの平均 [px/s]、−が充電の向き。下＝充電 10〜20秒に
//     下の極板の部屋にいる電子の平均 [個]、全部で 20 個）：
//       電圧 丸み │ 充電 0〜10秒 10〜20秒 │ 下の極板 │ 放電 0〜1秒 1〜3秒 3〜5秒 5〜20秒
//        1   0   │    −103      −1      │  15.1   │    +27    +47   +58    +66
//        1   15  │     −95      −1      │  10.0   │    +35    +85  +117    +47
//        2   0   │    −101      −2      │  16.0   │    +27    +53   +64    +63
//        2   15  │     −98      −2      │  13.0   │    +34    +95  +133    +51
//        3   0   │    −106      +1      │  17.7   │    +11    +31   +47    +68
//        3   15  │    −104      +1      │  15.1   │    +43   +106  +139    +49
//     放電は最初の 5 秒で 2 倍前後に速くなる（5〜20秒 が下がるのは、先に出きってしまうため）。
//     下の極板にたまる数は 2〜5 個減る：丸みの側の角に入っていた電子が、部屋の外の縦の通路に
//     並ぶようになる。充電の流れと止まり方はほとんど変わらない。
//     ★右の壁（部屋の横の壁と斜めの壁の境）に一瞬めり込む電子が延べ 2〜3 サンプル出るが、
//       丸みの無い直角でも同じ所・同じ数で出る（丸みのせいではない）。
const CAP_FILLET = 15;
// 仕切りと部屋の横の壁の角4つに置く「すみ肉」（四角から円を抜いた形）。壁と一緒に図形和する。
//   ★手で作るときも、四角と円を置いて図形和の diff をするだけ（専用の部品は要らない）
function capFillets(rx, cy, metal) {
  const out = [], RW = CAP_W/2, r = CAP_FILLET;
  if (!(r > 0)) return out;
  for (const sx of [-1, 1]) for (const sy of [-1, 1]) {
    const yf = cy + sy*CAP_GAP/2;                          // 仕切りの面
    const fx = rx + sx*(RW - r), fy = yf + sy*r;           // 丸みの円の中心
    const x1 = rx + sx*(RW + OHM_WALL/2), y0 = yf - sy*2;  // 四角は壁と仕切りへ食い込ませる
    out.push(demoBoolean('diff', [
      new Body(Object.assign({ isStatic:true, type:'box', x:(fx + x1)/2, y:(y0 + fy)/2,
        w:Math.abs(x1 - fx), h:Math.abs(fy - y0) }, metal)),
      new Body(Object.assign({ isStatic:true, type:'circle', x:fx, y:fy, radius:r }, metal)) ]));
  }
  return out;
}

// ── 平行板コンデンサーモデル（電源と C1 の輪に、並列の C2 の輪を足す）─────────
//  ★以前は「電気量保存モデル」という別のデモで、輪1つの平行板コンデンサーモデルを置き換えた
//    （指示。名前は平行板コンデンサーモデルのまま）。輪1つの版にあった「スイッチを切ると
//    電源の枝を通って放電する」手順は無くなり、放電は S2 で C2 へ分けることで見せる。
//  ★回路はこう（左の輪が電源と C1、右の輪が C1 と C2。C1 の枝を2つの輪が共有する）：
//        ┌──S1──┬──S2──┐
//      電源      C1      C2
//        └──S1──┴──S2──┘
//    S1 を入れて C1 を充電 → S1 を切る → S2 を入れると、C1 が電源になって C2 へ電子を送る。
//  ★輪・電子・電場の帯・電池の絵・極板の部屋と仕切りは平行板コンデンサーモデルと同じ作り
//    （寸法も OHM_*／CAP_* をそのまま使う）。違いは2つ：
//      ・電場の帯は**左の輪だけ**に置く。右の輪は電源とつながっていない
//      ・スイッチは**通路をふさぐ板を上下2枚**にして、枝を丸ごと切り離す
//  ★スイッチを2枚にする理由：1枚だと、切り離したはずの枝が片方の節点にぶら下がって残る。
//    S1 が1枚なら、電源の枝が C1 の上下を導線でつなぎっぱなしになり、電場を切った瞬間に
//    C1 がそこを通って放電する（平行板コンデンサーモデルの〈切る〉そのもの）。S2 が1枚なら、
//    充電中に C2 の片側が節点の一部になり、電子の出入りが起きる。
//    ＝S1 を切ると電源の枝が、S2 を入れるまでは C2 の輪が、電子ごと孤立する。
//  ★S1 は窓が2つ（電場の帯8枚の〈切る〉と、板2枚の〈すり抜け〉）で、同じキー ↓ にしてある
//    （〈切る〉は領域、〈すり抜け〉は物体にしか効かず、1つの窓にまとめられない）。
//    最初は電場 0・板は実体＝S1 は切。↓ で電場が入り板がすり抜ける。
//  ★この模型で「電気量」と読めるのは**節点ごとの電子の数**で、極板の部屋の中の数ではない。
//  ★**電子は最初、左の輪（電源と C1）にしか置かない**（指示）。右の輪は空で始まる。
//    実測（乱数は使っていないので結果は決定的。電子は全部で 15 個。S1 を 10 秒入れて切り、
//    5 秒置いてから S2 を入れる。時間平均 [個]。「C1 の縦の辺」は極板の部屋を除いた縦の通路、
//    「C2 の側」は縦の辺より右）：
//                      C1の極板 上/下 │ C1の縦の辺 上/下 │ C2の極板 上/下 │ C2の側の導線 上/下
//      最初              2.5 / 1.3   │    1.5 / 1.7     │   0   / 0     │  0   / 0
//      S1 を切ったあと    0   / 11.1  │    0   / 1.9     │   0   / 0     │  0   / 0
//      S2 から 5〜20秒    0   / 7.3   │    0   / 0.2     │   0   / 4.1   │  0   / 1.3
//      S2 から 40〜60秒   0   / 4.0   │    0   / 1.1     │   0   / 4.2   │  0   / 3.6
//      （対照：S2 を入れずに 5〜20秒） 0 / 10.2 │ 0 / 2.8 │ 0 / 0 │ 0 / 0
//    ・仕切りより下の電子は 13 → 4.0＋1.1＋4.2＋3.6 ＝ 12.9 で保存される（粒は消えないので、
//      スイッチで孤立させさえすれば構造的に成り立つ）。
//    ・C1 の下の極板は 11.1 → 4.0 と減り、C2 の下の極板は 0 → 4.2 と増える＝C1 が電源になって
//      C2 と分け合う絵になる。★板を平らにして口の先（縦の辺から 150px）に立てていた頃は、
//      T字の先に行き止まりの導線が残ってそこにも電子がたまり、C1 の極板は 6.1 → 6.0 と
//      変わらなかった（C2 へ流れた電子は導線から来ていた）。
//    ・C2 の上の極板は最初から空なので、出ていく電子が無い。C2 が受け取るのは下の側だけ。
//    ・充電中（S1 を入れた直後の 3 秒）の電子の速さ：T字の上 157 → 175・下 211 → 292 px/s、
//      導線の直線 156 → 262 px/s（平らな板のとき → 円弧の板）。
//    ・通路の外へ出た電子は延べ 0。重さは 1 tick 2.4〜2.8ms。
//    ★2026-09 電磁気の力を半分ずつ位置の前後で効かせるようにした（step.js の★）。いまの角を
//      丸めた作りで同じ手順の旧／新（C1 の下の極板・C2 の下の極板 [個]）：S1 を切ったあと
//      10.0 → 9.4・0／S2 から 5〜20秒 5.1・3.8 → 5.0・4.4／40〜60秒 5.0・4.0 → 5.0・4.0。
//      対照（S2 なし）の 5〜20秒 8.9 → 9.1。上の表は角が直角だった頃の値で、旧でも再現しない。
//  ★**仕切りに貼りついた電子は、角の形では外へ出せない。** S1 を切ったあと、C1 の下の極板の
//    電子は全部が仕切りの面に接して一列に並ぶ（中心の高さ＝仕切りの半厚 5＋半径 7 ＝ 12px）。
//    押しているのは下（縦の辺と C2 の側）にいる電子の反発で、列の中どうしの反発は横向きしか
//    無い＝同符号の電荷が導体の端へ寄るのと同じ。列の端の電子は横（隣）と下から押されて角に
//    収まり、その合力の向きへ滑れる面はどう角を作っても無い。
//    実測（仕切りの高さで横の壁を内側へすぼめ、仕切りと壁を鈍角で交わらせた。S2 から 40〜60秒の
//    C1 の下の極板）：すぼめ 0（直角）4.0 個／15px 11.0 個／30px 12.0 個。すぼめると壁の
//    いちばん広い所が新しいくぼみになって、電子がそこへ落ち込んだ。
//    ★出ていかないのは模型として正しい面もある。同じ形の C2 とつなげば C1 には半分が残るはずで、
//      直角のままの 40〜60秒 は C1 4.0／C2 4.2 個と、ほぼ半分ずつになっている。遅いのは
//      押す力が反発（強さ k=50 は見た目の値）だけだから。
//    ★いまは角を**すぼめずに丸めて**ある（CAP_FILLET の★）。上の表は丸める前の直角の値。
//  ★壁は外側の壁・島2つ・仕切り2枚を図形和した**1つの物体**で、角の円弧が 18 本ある。
//    これで arcIndexOwning（js/physics/arc.js）の穴が表に出た：島の角の円弧が、向いている先の
//    外側の壁の接触まで拾って消し、電子 28 個のうち 15 個が 300tick で壁を抜けた
//    （両方の輪に電子を置いていた頃の値）。
//    直したのはエンジンの側（円弧から遠い接触は拾わない）。
const QC_LOOP  = 460;      // [px] 輪1つの幅（通路の中心線どうし）。★部屋の張り出し（CAP_W/2 − 通路の半幅
                           //   ＝ 80px）と島の中の空洞の壁（OHM_WALL）が、右の島の左右から
                           //   食い込んでも空洞が残る幅（残り 130px）
const QC_GATE_LIP = 20;    // [px] スイッチの板が、ふさぐ側の通路へ差し込む深さ（口の縁から）
const QC_TOP     = 285;    // [画面px] 本文の左うえから輪の上端まで（本文 10 行ぶん）

function demoCapacitorModel() {
  resetDemoWorld();
  setDemoGravity(0);
  updateGroundTerrain(false);
  world.sleeping  = false;
  world.substeps  = 8;
  world.coulombOn = true;
  world.coulombK  = OHM_COULOMB_K;

  setDemoCam(0, 0.62);
  // ★輪は本文の下・画面の左寄せ（右はリモコンの窓が3つ縦に並ぶ）
  const p = demoTextTopLeft();
  const XM = p.x + OHM_WALL + OHM_CORR/2 + QC_LOOP;   // 真ん中の縦の辺（C1）の中心線
  const CY = p.y + QC_TOP / cam.zoom * demoFitScale() + OHM_OUT_H/2;
  const XL = XM - QC_LOOP, XR = XM + QC_LOOP; // 左の辺（電源）・右の辺（C2）
  const YT = CY + OHM_YT, YB = CY + OHM_YB;
  const H = OHM_CORR/2, W = OHM_WALL;
  const metal = { fillColor:'#78909c', strokeColor:'#b0bec5', strokeWidth:1.5,
                  friction:0, frictionStatic:0, restitution:0 };
  const box = (x, y, hw, hh) => new Body(Object.assign({ isStatic:true, type:'box',
    x, y, w:2*hw, h:2*hh }, metal));
  // 角丸の板（中心 cx・半幅 A,B・角の半径 R）を部品6つで
  const roundParts = (cx, A, B, R) => {
    const mk = o => new Body(Object.assign({ isStatic:true }, metal, o));
    const ps = [ mk({ type:'box', x:cx, y:CY, w:2*A,       h:2*(B - R) }),
                 mk({ type:'box', x:cx, y:CY, w:2*(A - R), h:2*B       }) ];
    for (const sx of [-1, 1]) for (const sy of [-1, 1])
      ps.push(mk({ type:'circle', x:cx + sx*(A - R), y:CY + sy*(B - R), radius:R }));
    return ps;
  };
  const RW = CAP_W/2, RH = CAP_H/2;
  const room = rx => new Body(Object.assign({ isStatic:true, type:'polygon', x:rx, y:CY, verts:[
    { x:-RW, y:-CAP_HS }, { x:-H, y:-RH }, { x:H, y:-RH }, { x:RW, y:-CAP_HS },
    { x:RW, y: CAP_HS }, { x:H, y: RH }, { x:-H, y: RH }, { x:-RW, y: CAP_HS } ] }, metal));
  const roomBox = rx => box(rx, CY, RW + W, RH + W);

  // ── 通路：外側の壁1枚と、島2つ ──
  //   外側の壁：角丸の板＋C2 の部屋を包む箱 から、一回り小さい角丸の板と C2 の部屋を抜く
  const XC = (XL + XR)/2, A0 = QC_LOOP + H + W, B0 = OHM_OUT_H/2, RO = OHM_CR + H + W;
  const outer = demoBoolean('diff', [
    demoUnion(roundParts(XC, A0, B0, RO), roomBox(XR)),
    ...roundParts(XC, A0 - W, B0 - W, RO - W), room(XR) ]);
  //   島：それぞれの輪の内側。中の空洞は、食い込む部屋の側を壁の厚みぶん削っておく
  //   （平行板コンデンサーモデルの島と同じ。削らずに部屋を抜くと空洞とつながる）
  const IA = QC_LOOP/2 - H, IB = OHM_YB - H, IR = OHM_CR - H;
  const island = (cx, rooms) => {
    const hole = demoBoolean('diff', [
      demoUnion(roundParts(cx, IA - W, IB - W, IR - W)), ...rooms.map(roomBox) ]);
    return demoBoolean('diff', [ demoUnion(roundParts(cx, IA, IB, IR)), hole, ...rooms.map(room) ]);
  };
  const isL = island((XL + XM)/2, [XM]);
  const isR = island((XM + XR)/2, [XM, XR]);
  // 仕切り（絶縁体）2枚を壁と図形和して1つの物体にする
  const part = rx => new Body(Object.assign({ type:'box', x:rx, y:CY,
    w:CAP_W + 2*W, h:CAP_GAP, isStatic:true }, metal));
  // 仕切りと部屋の横の壁の角（直角）は丸みでつなぐ（CAP_FILLET の★）
  const fillets = [...capFillets(XM, CY, metal), ...capFillets(XR, CY, metal)];
  const walls = demoUnion(outer, isL, isR, part(XM), part(XR), ...fillets);
  walls.layers = OHM_LAYER_WALL;

  // ── スイッチ：T字の分かれ道をふさぐ板。S1 は左の口、S2 は右の口を、上下1枚ずつ ──
  //   ★板の通路側の面は**円弧**にする（指示）。ふさいだとき、残った輪の角が平行板
  //     コンデンサーモデルの角（中心線の半径 OHM_CR）と同じ丸みでつながる：
  //       S1 がふさぐ → 右の輪（C1＋C2）が丸い角で一周できる
  //       S2 がふさぐ → 左の輪（電源＋C1）が丸い角で一周できる
  //     平らな板を口の先に立てていた頃は、T字の外側の壁が平らなまま残り、口の先には
  //     行き止まりの短い導線ができていた（電子が正面から当たって行き足を失う。
  //     オームの法則モデルの「角を直角にしない」の★と同じ理由）。
  //   ★形は「四角 − 円」の型抜き（手で作るときも図形和の diff だけ）。四角は壁と島へ
  //     食い込ませてある（固定どうしは当たらないので、重なっても何も起きない）。
  //   ★板を置く位置は分かれ道そのもの。S1 と S2 を両方ふさぐと、2枚の四角は口の上で
  //     重なり、縦の辺（C1）だけが残る。
  //   sx：円の中心が縦の辺のどちら側か（+1 なら右＝左の口をふさぐ）。sy：上の分かれ道なら −1
  const gateArcs = [];                                     // 電子の置き場所を避けるためだけに使う
  const gate = (sx, sy, label) => {
    const R = OHM_CR + H;                                   // 通路の外側の縁の半径
    const cx = XM + sx*OHM_CR, cy = (sy < 0 ? YT : YB) - sy*OHM_CR;
    const x0 = XM - sx*(H + QC_GATE_LIP), y0 = (sy < 0 ? YT : YB) + sy*(H + W/2);
    const col = { fillColor:'#ffb74d', strokeColor:'#ffe0b2', strokeWidth:1.5,
                  friction:0, frictionStatic:0, restitution:0 };
    const g = demoBoolean('diff', [
      new Body(Object.assign({ type:'box', isStatic:true, x:(x0 + cx)/2, y:(y0 + cy)/2,
        w:Math.abs(cx - x0), h:Math.abs(cy - y0) }, col)),
      new Body(Object.assign({ type:'circle', isStatic:true, x:cx, y:cy, radius:R }, col)) ]);
    Object.assign(g, col, { isStatic:true, layers:OHM_LAYER_WALL, label });
    gateArcs.push({ cx, cy, R, x0, y0 });
    return g;
  };
  const s1 = [ gate( 1, -1, 'スイッチ S1'), gate( 1, 1, 'スイッチ S1') ];
  const s2 = [ gate(-1, -1, 'スイッチ S2'), gate(-1, 1, 'スイッチ S2') ];
  const inGate = (x, y) => gateArcs.some(q =>
    (x - q.x0)*(x - q.cx) <= 0 && (y - q.y0)*(y - q.cy) <= 0
    && Math.hypot(x - q.cx, y - q.cy) > q.R - OHM_E_R - 6);

  // ── 自由電子：左の輪（電源と C1）だけに置く。右の輪（C2 の側）は空で始める ──
  //   ★指示。電子は最初、電源の回りにしかない（冒頭の★の表は置き直したあとの値）
  const clear = (x, y) =>
    !inGate(x, y)
    && [XM, XR].every(rx => Math.abs(x - rx) > RW || Math.abs(y - CY) > OHM_E_R + 8)
    && objects.every(o => !o.charge || (o.x - x)**2 + (o.y - y)**2 > (2*OHM_E_R + 4)**2);
  const putE = (x, y) => objects.push(new Body({ type:'circle', x, y, radius:OHM_E_R,
    mass:OHM_E_M, charge:OHM_E_Q, hasGravity:false, fixedRotation:true, layers:OHM_LAYER_E,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:'#42a5f5', strokeColor:'#e3f2fd', strokeWidth:1.2 }));
  //   角丸の輪（中心線。左の辺 x0・右の辺 x1）の上の点。ohmLoopPoint と同じ並べかた
  const loopPoint = (x0, x1, s) => {
    const R = OHM_CR, LX = (x1 - x0) - 2*R, LY = (YB - YT) - 2*R, ARC = Math.PI/2 * R;
    const arc = (cx, cy, a0, t) => ({ x: cx + R*Math.cos(a0 + Math.PI/2*t),
                                      y: cy + R*Math.sin(a0 + Math.PI/2*t) });
    if (s < LX)  return { x: x0 + R + s, y: YT };                      s -= LX;
    if (s < ARC) return arc(x1 - R, YT + R, -Math.PI/2, s/ARC);        s -= ARC;
    if (s < LY)  return { x: x1, y: YT + R + s };                      s -= LY;
    if (s < ARC) return arc(x1 - R, YB - R, 0, s/ARC);                 s -= ARC;
    if (s < LX)  return { x: x1 - R - s, y: YB };                      s -= LX;
    if (s < ARC) return arc(x0 + R, YB - R, Math.PI/2, s/ARC);         s -= ARC;
    if (s < LY)  return { x: x0, y: YB - R - s };                      s -= LY;
    return             arc(x0 + R, YT + R, Math.PI, s/ARC);
  };
  { const PER = 2*((QC_LOOP - 2*OHM_CR) + (OHM_YB - OHM_YT - 2*OHM_CR)) + 2*Math.PI*OHM_CR;
    const step = ohmLoopPerimeter() / (CAP_N_E - CAP_N_ROOM);   // ★平行板コンデンサーモデルと同じ密度
    const n = Math.round(PER / step);
    { const x0 = XL, x1 = XM;
      for (let i = 0; i < n; i++) {
        let put = null;
        for (let d = 0; d < 60 && !put; d += 4)
          for (const sgn of (d ? [1, -1] : [0])) {
            if (put) continue;
            const p = loopPoint(x0, x1, ((i + 0.5)*PER/n + sgn*d + PER) % PER);
            if (clear(p.x, p.y)) put = p;
          }
        if (put) putE(put.x, put.y);
      } }
    for (const rx of [XM])
      for (const sy of [-1, 1]) for (const sx of [-1, 1]) putE(rx + sx*(RW - 25), CY + sy*25);
  }

  // ── 電場：左の輪だけに8枚（時計回り）。真ん中の縦の辺は C1 の部屋の大きさ ──
  //   上下の角（縦の辺どうしの T 字）は、平行板コンデンサーモデルの右の角と同じ斜めの1枚
  const CS = OHM_CR + H;
  const band = (x, y, w, h, angle) => emFields.push(new EMField({
    kind:'E', x, y, w, h, strength:0, angle }));
  const SX = QC_LOOP - 2*OHM_CR, SY = (OHM_YB - OHM_YT) - 2*OHM_CR;
  band((XL + XM)/2, YT, SX, OHM_CORR,  0);             // 上：→
  band(XM, CY, CAP_W, CAP_H,           Math.PI/2);     // C1：↓
  band((XL + XM)/2, YB, SX, OHM_CORR,  Math.PI);       // 下：←
  band(XL, CY, OHM_CORR, SY,          -Math.PI/2);     // 電源：↑
  for (let i = 0; i < 4; i++) {
    const sx = (i <= 1) ? 1 : -1, sy = (i === 0 || i === 3) ? -1 : 1;
    band((sx > 0 ? XM : XL) + sx*(H - CS/2), (sy > 0 ? YB : YT) + sy*(H - CS/2),
         CS, CS, Math.PI/4 + i*Math.PI/2);
  }

  // ── 操作：S1（電場と板）と S2（板） ──
  //   ★S1 は窓が2つで同じキー。入れる＝電場を入れて板をすり抜けに、切る＝電場を 0 にして
  //     板を実体に。電源を外すと同時に電源の枝も切り離す（冒頭の★）。
  const swE = addRemote('ghost', emFields[0], 'emfield', emFields.map(f => f.id));
  if (swE) {
    swE.key = 'ArrowDown'; swE.savedStrength = CAP_E0;
    swE.fx = 0.795; swE.fy = 0.04;
    placeRemotePanel(swE); syncRemotePanel(swE);
  }
  const sw1 = addRemote('ghost', s1[0], 'body', s1.map(g => g.id));
  if (sw1) {
    sw1.key = 'ArrowDown';
    sw1.fx = 0.795; sw1.fy = 0.27;
    placeRemotePanel(sw1); syncRemotePanel(sw1);
  }
  const sw2 = addRemote('ghost', s2[0], 'body', s2.map(g => g.id));
  if (sw2) {
    sw2.key = 'ArrowUp';
    sw2.fx = 0.795; sw2.fy = 0.50;
    placeRemotePanel(sw2); syncRemotePanel(sw2);
  }

  // ── 絵（物理には参加しない）──
  const BAT = '#ffd54f';
  const bx = XL, by = CY;
  const plate = (dy, half) => demoPath([{ x:bx - half, y:by + dy }, { x:bx + half, y:by + dy }], BAT, 5);
  plate(-24, 34); plate(-10, 15); plate(6, 34); plate(20, 15);
  const ts = demoTextScale(cam.zoom);
  // ★札は輪の内側へ（輪を画面の左端へ寄せたので、外側には置き場が無い）
  demoLabel(bx + 44, by - 48, '＋', BAT, DEMO_NOTE_SIZE * ts, true);
  demoLabel(bx + 44, by + 34, '−', BAT, DEMO_NOTE_SIZE * ts, true);
  demoLabel(bx + H + W + 12, by - 12, '電源（絵）', BAT, DEMO_NOTE_SIZE * ts, true);
  demoLabel(XM - 22, CY - RH - 60, 'C1', '#b0bec5', DEMO_NOTE_SIZE * ts, true);
  demoLabel(XR + RW + W + 12, CY - 14, 'C2', '#b0bec5', DEMO_NOTE_SIZE * ts, true);
  demoLabel(XM - H - 60, YT - H - W - 34, 'S1', '#ffb74d', DEMO_NOTE_SIZE * ts, true);
  demoLabel(XM + H + 20, YT - H - W - 34, 'S2', '#ffb74d', DEMO_NOTE_SIZE * ts, true);

  demoTitle(p.x, p.y, '平行板コンデンサーモデル', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    'オームの法則モデルの輪の一部を広げて極板にし、絶縁体で仕切った（C1）。\n'
  + '右に同じ形のコンデンサー C2 を並列につないである。電子は仕切りを通れない。\n'
  + 'スイッチ S1・S2 は上下2枚の板で、切ると枝を丸ごと切り離す。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・↓ キーで S1 を入れる：電子が仕切りの下の側へ流れ込む（C1 の充電）\n'
  + '・もう一度 ↓ で S1 を切る：電源が外れ、電子はたまったまま\n'
  + '・↑ キーで S2 を入れる：たまった電子が C2 の下の極板へ流れる。\n'
  + '　C1 が電源としてはたらく\n'
  + '・仕切りの下の側にある電子の数は、S2 を入れる前と後で同じ（電気量保存）\n'
  + '・S1 は窓が2つ（電場と板）。↓ キーで押すと2つが一緒に切り替わる',
    DEMO_NOTE_SIZE * ts);

  demoRunAhead(300);
}

// ── コイルモデル（自己誘導）───────────────────────────────────
//  ★輪・抵抗・電場の帯・電池の絵はオームの法則モデルと同じ作り（寸法も OHM_* をそのまま使う）。
//    違いは3つ：左うえの角に**羽根車**（コイルの見立て）・電子を 18 → 50 個・スイッチは
//    平行板コンデンサーモデルと同じ〈電源を切る〉＝電場の帯を全部 0 にする。羽根車には
//    〈すり抜けにする〉の窓が付き、同じ装置で有り無しを比べる。
//  ★**羽根車は見立て**。本物のコイルで電流の変化を妨げるのは誘導起電力（磁場のエネルギー
//    ½LI²）で、このエンジンは動く電荷から磁場を作らない。そこで水の回路のたとえどおり、
//    磁場のエネルギーを羽根車の回転のエネルギー ½Iω² に置き換えた。電池を絵にして電場で
//    押しているのと同じく、本文で見立てだと言う。羽根車は円1つ＋板8枚の図形和とヒンジ
//    だけ（手で作れる部品）で、エンジンには何も足していない。
//  ★**羽根車は角に置く**。軸を角の円弧の中心に、羽根の先を外側の壁の円弧の 4px 手前に
//    置くと、羽根と壁のすき間が円弧に沿って一定になり、電子は羽根車を回さないと通れない。
//    最初は上の辺の直線に置いていて、最下点の隣の羽根では壁とのすき間が 14px（電子の直径）
//    開いて漏れていた。羽根車の残り 3/4 は島の中（導線の外＝何も無い所）を回る。
//    羽根車は陽イオンと同じレイヤーなので、壁はすり抜けて電子にだけ当たる。
//    ★羽根に押された電子が角の外側の壁へ最大 2.3px めり込むことがある（入れて40秒・切って40秒で
//      延べ 11 tick・1個。すぐ戻り、通路の外へ抜けた電子は 0）。
//  ★**電子を 50 個に増やす**。18 個では羽根車と導線の電流が一致しなかった（実測・4kg：
//    切って 20秒のあいだ羽根車は 80% の速さで回っているのに、導線の電流は定常の 23%）。
//    羽根は前の電子を押せても後ろの電子を吸い込めず、電子がまばらだと空の区画を回るため。
//    電子どうしの反発でつながった列は、詰めるほど縮みにくくなって羽根車と一緒に動く。
//    反発を切ると（接触だけで押す）羽根車はまた空回りした（16kg：電流 0 のまま 1.35rad/s）。
//    実測（乱数固定・電源を切った輪で落ち着かせ、入れて 40秒・切って 40秒。電流は左の辺に
//    いる電子の速さの和÷辺の長さ＝1秒あたりに通る電子の数、1秒ごとの時間平均）：
//        電子 │ 羽根車 │ 定常の電流 │ 63% まで │ 切って 37% まで │ 切ったあと流れた量÷定常
//         50  │  なし  │   8.0     │   2秒   │     3秒       │   1.6秒
//         50  │  16kg  │   5.6     │   9秒   │     6秒       │  11.5秒   ★これ
//         70  │  なし  │  13.8     │   3秒   │     5秒       │   1.9秒
//         70  │  16kg  │   8.9     │   9秒   │     8秒       │  11.2秒
//        100  │  なし  │  30.9     │   9秒   │     5秒       │   3.1秒
//        100  │  16kg  │  14.9     │   9秒   │     7秒       │   9.6秒
//    増やすほど**羽根車なしでも**電子の質量そのものが遅れを作り、羽根車との差が縮む。
//    重さは 1 tick 5.3ms（50個・刻み4。100個・刻み8 は 20.5ms で 60tick/秒 に追いつかない）。
//    時間のほとんどは電子と羽根車・壁の接触で、反発は 8%。
//    ★2026-09 電磁気の力を半分ずつ位置の前後で効かせるようにした（step.js の★）。同じ手順の
//      旧／新（定常の電流・63% まで・切って 37% まで・切ったあと流れた量÷定常）：
//        16kg  5.8・10秒・6秒・11.4秒 → 5.6・10秒・5秒・10.9秒
//        なし  8.2・2秒・2秒・0.6秒   → 8.0・2秒・4秒・1.8秒（電子が行き足を失わなくなったぶん）
//  ★羽根車の重さ＝自己インダクタンス。電子 50 個で 63% まで 0/4/16/32/64kg → 2/5/9/13/17秒と
//    重いほど遅れる。16kg は「切ったあとも流れる」がはっきり見えて、立ち上がりを待てる長さ。
//    ★代償：羽根に当たる衝突（反発0）が抵抗として効き、定常の電流が 8.0 → 5.6 に落ちる。
//      本物のコイルの巻き線の抵抗にあたる。
//  ★刻みは 4（オームの法則モデルは 8）。電子を増やした重さを戻すため。羽根車の軸はヒンジ
//    （axle はリモコンが無いと目標0のモーター＝ブレーキになる）。
const COIL_N_E   = 50;     // 電子の数（上の★の表）
const COIL_M     = 16;     // [kg] 羽根車の質量（＝自己インダクタンス。上の★）
const COIL_NB    = 8;      // 羽根の板の枚数（直径1本で羽根2枚）
const COIL_GAP   = 4;      // [px] 羽根の先と外側の壁のすき間（電子の直径 14 より十分狭く）
const COIL_HUB_R = 30;     // [px] 軸の円。★島の角の丸み（45）より小さく＝通路に出さない
// 輪・陽イオン・電子・羽根車・電場の帯（強さ0）までを組む。★コイルモデルと
//   交流のコイルモデル（demoCoilAcModel）で共有する。違うのは羽根車の重さと、その先の窓・絵・本文だけ
function coilModelBuild(mass) {
  resetDemoWorld();
  setDemoGravity(0);              // ★正面から見た図（オームの法則モデルと同じ）
  updateGroundTerrain(false);
  world.sleeping  = false;
  world.substeps  = 4;            // ★冒頭の★（重さ）
  world.coulombOn = true;
  world.coulombK  = OHM_COULOMB_K;

  setDemoCam(0, 0.62);
  const CX = 0, CY = cam.y + 180;
  const metal = { fillColor:'#78909c', strokeColor:'#b0bec5', strokeWidth:1.5,
                  friction:0, frictionStatic:0, restitution:0 };
  const ions = ohmPlaceIons(CX, CY);

  // ── 通路：外側の枠と内側の枠（オームの法則モデルと同じ）──
  const roundParts = (A, B, R) => {
    const mk = o => new Body(Object.assign({ isStatic:true }, metal, o));
    const ps = [ mk({ type:'box', x:CX, y:CY, w:2*A,       h:2*(B - R) }),
                 mk({ type:'box', x:CX, y:CY, w:2*(A - R), h:2*B       }) ];
    for (const sx of [-1, 1]) for (const sy of [-1, 1])
      ps.push(mk({ type:'circle', x:CX + sx*(A - R), y:CY + sy*(B - R), radius:R }));
    return ps;
  };
  const ring = (A, B, R) => demoBoolean('diff',
    [ demoUnion(roundParts(A, B, R)),
      ...roundParts(A - OHM_WALL, B - OHM_WALL, R - OHM_WALL) ]);
  ring(OHM_OUT_W/2, OHM_OUT_H/2, OHM_CR + OHM_CORR/2 + OHM_WALL);
  ring(OHM_XR - OHM_CORR/2, OHM_YB - OHM_CORR/2, OHM_CR - OHM_CORR/2);

  // ── 羽根車（コイルの見立て）：左うえの角 ──
  const WX = CX + OHM_XL + OHM_CR, WY = CY + OHM_YT + OHM_CR;   // 角の円弧の中心
  const RT = OHM_CR + OHM_CORR/2 - COIL_GAP;                    // 羽根の先の半径
  const onBlade = (x, y, pad) => {               // 羽根（または軸）に重なるか
    const dx = x - WX, dy = y - WY;
    if (Math.hypot(dx, dy) > RT + pad) return false;
    if (Math.hypot(dx, dy) < COIL_HUB_R + pad) return true;
    for (let k = 0; k < COIL_NB; k++) {
      const a = k * Math.PI / COIL_NB;
      if (Math.abs(-Math.sin(a)*dx + Math.cos(a)*dy) < 4 + pad) return true;
    }
    return false;
  };

  // ── 自由電子：オームの法則モデルと同じ並べかたで 50 個 ──
  { const PER = ohmLoopPerimeter(), step = PER / COIL_N_E;
    const clear = (x, y) => !onBlade(x, y, OHM_E_R + 4)
      && ions.every(i => (i.x - x)**2 + (i.y - y)**2 > (OHM_ION_R + OHM_E_R + 4)**2)
      && objects.every(o => !o.charge || (o.x - x)**2 + (o.y - y)**2 > (2*OHM_E_R + 4)**2);
    for (let i = 0; i < COIL_N_E; i++) {
      let put = null;
      for (let d = 0; d < 60 && !put; d += 4)
        for (const sgn of (d ? [1, -1] : [0]))
          for (const off of [0, 30, -30, 15, -15]) {
            if (put) continue;
            const p = ohmLoopPoint(i*step + sgn*d);
            const x = CX + p.x + p.nx*off, y = CY + p.y + p.ny*off;
            if (clear(x, y)) put = { x, y };
          }
      if (!put) continue;
      objects.push(new Body({ type:'circle', x:put.x, y:put.y, radius:OHM_E_R,
        mass:OHM_E_M, charge:OHM_E_Q, hasGravity:false, fixedRotation:true, layers:OHM_LAYER_E,
        friction:0, frictionStatic:0, restitution:0,
        fillColor:'#42a5f5', strokeColor:'#e3f2fd', strokeWidth:1.2 }));
    }
  }

  // 羽根車は電子より後に置く（手前に描く＝羽根が電子を押しているのが見える）
  const COIL = { fillColor:'#c77c48', strokeColor:'#ffccbc', strokeWidth:1.5,
                 friction:0, frictionStatic:0, restitution:0 };
  const parts = [ new Body(Object.assign({ type:'circle', x:WX, y:WY, radius:COIL_HUB_R }, COIL)) ];
  for (let k = 0; k < COIL_NB; k++)
    parts.push(new Body(Object.assign({ type:'box', x:WX, y:WY, w:2*RT, h:8,
      angle:k * Math.PI / COIL_NB }, COIL)));
  const wheel = demoUnion(parts);
  Object.assign(wheel, COIL, { isStatic:false, hasGravity:false, layers:OHM_LAYER_ION,
                               label:'コイル（羽根車）' });
  wheel.setMass(mass);
  joints.push(new Joint({ type:'hinge', bodyA:null, bodyB:wheel,
    anchorAx:WX, anchorAy:WY, anchorBx:WX - wheel.x, anchorBy:WY - wheel.y }));

  // ── 電場：オームの法則モデルと同じ8枚。最初は 0（電源を切った姿で開く）──
  ohmLoopBands(CX, CY);

  return { CX, CY, WX, WY, wheel };
}
// 輪に沿った電場の帯8枚（直線4＋角4）を強さ 0 で置く。コイルモデルとコンデンサーの
//   リアクタンスモデルで共有する（向きは上の辺で右＝時計回り）。rightW は右の辺の帯の幅
//   （極板の部屋を張り出させたときは部屋の幅にして、部屋の中をすき間なく覆う）
function ohmLoopBands(CX, CY, rightW = OHM_CORR) {
  const CS = OHM_CR + OHM_CORR/2;
  const band = (x, y, w, h, angle) => emFields.push(new EMField({
    kind:'E', x:CX + x, y:CY + y, w, h, strength:0, angle }));
  band(0, OHM_YT, OHM_STRX(), OHM_CORR,  0);
  band(OHM_XR, 0, rightW, OHM_STRY(),    Math.PI/2);
  band(0, OHM_YB, OHM_STRX(), OHM_CORR,  Math.PI);
  band(OHM_XL, 0, OHM_CORR, OHM_STRY(), -Math.PI/2);
  for (let i = 0; i < 4; i++) {
    const sx = (i <= 1) ? 1 : -1, sy = (i === 0 || i === 3) ? -1 : 1;
    band(sx * (OHM_XR + OHM_CORR/2 - CS/2), sy * (OHM_YB + OHM_CORR/2 - CS/2),
         CS, CS, Math.PI/4 + i * Math.PI/2);
  }
}
// 交流電源の絵（物理には参加しない）：〇の中に ∿。中心 (sx, sy)
function acSourceSketch(sx, sy) {
  const SRC = '#ffd54f', sr = 30;
  const circ = [];
  for (let k = 0; k <= 36; k++) circ.push({ x: sx + sr*Math.cos(k*Math.PI/18), y: sy + sr*Math.sin(k*Math.PI/18) });
  demoPath(circ, SRC, 4);
  const wave = [];
  for (let k = 0; k <= 20; k++) wave.push({ x: sx - 18 + 36*k/20, y: sy - 10*Math.sin(2*Math.PI*k/20) });
  demoPath(wave, SRC, 3);
  demoLabel(sx - 196, sy + 56, '交流電源（絵）', SRC, DEMO_NOTE_SIZE * demoTextScale(cam.zoom), true);
}
function demoCoilModel() {
  const { CX, CY, WX, wheel } = coilModelBuild(COIL_M);

  // ── スイッチ：電場の帯を全部 0 にする〈電源を切る〉（平行板コンデンサーモデルと同じ）──
  const sw = addRemote('ghost', emFields[0], 'emfield', emFields.map(f => f.id));
  if (sw) {
    sw.key = 'ArrowDown'; sw.savedStrength = OHM_E0;
    sw.fx = 0.795; sw.fy = 0.04;
    placeRemotePanel(sw); syncRemotePanel(sw);
  }
  // ── 羽根車の有り無し：〈すり抜けにする〉1台（指示）──
  //   ★比べるのは同じ装置の切り替えで（2台並べない）。すり抜けにした羽根車は電子に当たらず、
  //     角はただの導線になる＝冒頭の★の表の「羽根車なし」の列そのもの。
  //   ★回っている途中ですり抜けにしても羽根車は回り続け（摩擦が無い）、戻すとたまった回転で
  //     いきなり電子を押す。物理としては正しいが「外したコイルに何か残っている」ように見えるので、
  //     本文で「電源を切って羽根車が止まってから」と頼む。止める仕掛けは足さない（専用の都合になる）。
  //   ★有り無しで比べると、定常の電流も 5.8 → 8.2 と増える。羽根に当たる抵抗（巻き線の抵抗）が
  //     消えたぶんで、本文で一言いう。
  const swW = addRemote('ghost', wheel, 'body');
  if (swW) {
    swW.key = 'ArrowUp'; swW.savedLayers = OHM_LAYER_ION;
    swW.fx = 0.795; swW.fy = 0.28;
    placeRemotePanel(swW); syncRemotePanel(swW);
  }

  // ── 絵（物理には参加しない）──
  const BAT = '#ffd54f';
  const bx = CX + OHM_XL, by = CY + 40;   // ★羽根車の下へ少しずらす
  const plate = (dy, half) => demoPath([{ x:bx - half, y:by + dy }, { x:bx + half, y:by + dy }], BAT, 5);
  plate(-24, 34); plate(-10, 15); plate(6, 34); plate(20, 15);
  const ts = demoTextScale(cam.zoom);
  demoLabel(bx - 92, by - 48, '＋', BAT, DEMO_NOTE_SIZE * ts, true);
  demoLabel(bx - 92, by + 34, '−', BAT, DEMO_NOTE_SIZE * ts, true);
  demoLabel(bx - 176, by + 62, '電源（絵）', BAT, DEMO_NOTE_SIZE * ts, true);
  // 札は輪の内側の右寄せ（左うえは羽根車が回る）
  demoLabel(CX - 60, CY - 78, '● 陽イオン', '#ef5350', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 60, CY - 42, '● 自由電子', '#42a5f5', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 44, CY + 64, '抵抗', '#ef5350', DEMO_NOTE_SIZE * ts, true);
  demoLabel(WX - 60, CY - OHM_OUT_H/2 - 26, 'コイル（羽根車で表した）', '#ffab91', DEMO_NOTE_SIZE * ts, true);

  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'コイルモデル', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    'オームの法則モデルの輪の角に、コイルの代わりの重い羽根車を入れた。\n'
  + '電子は羽根車を回さないと角を通れない。本物のコイルが電流の変化を妨げるのは\n'
  + '誘導起電力で、ここではそれを羽根車の回りにくさ・止まりにくさで表している。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・↓ キーで電源を入れる：羽根車が重くてすぐには回らず、電流はだんだん増える\n'
  + '・もう一度 ↓ で電源を切る：羽根車が回り続けて電子を押し、電流はしばらく流れる。\n'
  + '　抵抗で行き足を失って、だんだん止まる\n'
  + '・↑ キーで羽根車をすり抜けに（コイルを外す）：角はただの導線になり、すぐ流れてすぐ止まる。\n'
  + '　切り替えは電源を切り、羽根車が止まってから。羽根車は電子がぶつかるぶん抵抗にもなるので\n'
  + '　（巻き線の抵抗）、外すと流れる電流そのものも大きくなる',
    DEMO_NOTE_SIZE * ts);

  // ★電源を切った姿で落ち着かせてから開く（電子を反発で並ばせる）
  demoRunAhead(300);
}

// ── コイルのリアクタンスモデル（交流とコイル）──────────────────────────
//  ★コイルモデルの輪（coilModelBuild）を、電場の帯8枚に振動数を与えて交流で押す。
//    違いは3つ：羽根車 16 → 4kg・刻み 4 → 2＋2倍速・窓は〈羽根車をすり抜けに〉〈振動数〉と、
//    上の辺の導線に置いた通過カウンタ（電流の大きさはこのグラフの山の高さで読む）。
//    読みどころは「コイルは交流を流れにくくし、振動数が高いほど流れにくい（X = ωL）」。
//  ★**羽根車を 4kg に軽くする**。16kg のままだと交流にはコイルとして重すぎる。実測（E=2・刻み4、
//    2周期落ち着かせて3周期の時間平均。電流は各辺の「電子の速さの和÷辺の長さ」を電場の位相で
//    正弦波に当てはめた振幅、括弧は電場からの遅れ）：
//        羽根車 │ 直流 │ 周期80秒   │ 周期40秒   │ 周期20秒
//        なし   │ 8.1  │ 8.5（10°） │ 8.4（18°） │ 7.8（35°）
//        2kg    │ 6.9  │ 6.5（21°） │ 5.5（32°） │ 約3.6 辺ごとにばらつく
//        4kg    │ 7.0  │ 5.4（28°） │ 4.1（39°） │ 約2.2 辺ごとにばらつく   ★これ
//        16kg   │ 7.1  │  —         │ 約1.3 辺ごとにばらつく（羽根車を通るのは なし の 13%）
//    16kg は周期10〜40秒で羽根車を通る電流が なし の 3〜13% しかなく、流れないぶん羽根車から
//    遠い辺の電子がその場で往復する（電流が輪の上でそろわず、電場より進む＝コンデンサーの向き）。
//    電子の列が縮む流体だから（コイルモデルの★）。直流で入れても羽根車の回転は60秒たっても
//    上がり続けていた（時定数 約50秒）。軽くすると周期40秒以上で4辺の電流がそろう。
//  ★**周期は 40〜80秒**（振動数 0.0125〜0.025 Hz）。20秒より短いと 4kg でも辺ごとにばらつく。
//    羽根車なしは電子の質量そのものがコイルとして効き（時定数 約2秒）、周期が短いと
//    やはり流れにくくなるが、40〜80秒の範囲ではほとんど変わらない（8.4〜8.5）。
//    ★遅れは 30〜40°で 90° にはならない（抵抗がある RL 直列）。本文で「90°遅れる」とは言わない。
//  ★刻み 2・2倍速。刻み 2 と 4 で同じ手順（4kg・周期40/80秒）の電流は 4.2/5.8 と 4.2/5.5、
//    なしは 8.6/9.0 と 8.6/8.5（4% 以内）。1 tick 6.4 → 3.4ms。電気振動モデルと同じ作り。
const COILAC_M     = 4;       // [kg] 羽根車（＝L）。上の★
const COILAC_FREQ  = 0.025;   // [Hz] 振動数の初期値（周期40秒＝2倍速で見かけ20秒）
const COILAC_FMAX  = 0.05;    // [Hz] つまみの上限。★刻みは remotePropTicks で 0.00025
const COILAC_SPEED = 2;
const COILAC_SPAN  = 120;     // [s] カウンタのグラフの幅（上の addCounter の★）
function demoCoilAcModel() {
  const { CX, CY, WX, wheel } = coilModelBuild(COILAC_M);
  world.substeps = 2;             // ★冒頭の★（2倍速で毎秒 120 tick 回すため）
  setSpeed(COILAC_SPEED);
  // ★電源を切った姿（E=0）で電子を反発で並ばせてから交流を入れる。先に入れると先回しの
  //   300 tick で位相が進み、▶実行を押す前に電子が流れ始めた姿で開く
  demoRunAhead(300);
  // ★振幅はオームの法則モデルの電圧の初期値。位相 0（E=0）から▶実行で立ち上がる
  for (const f of emFields) { f.strength = OHM_E0; f.freq = COILAC_FREQ; f.acPhase = 0; }

  // ── 窓：羽根車の有り無し（↑）と振動数のつまみ。どちらも同じ装置1台で比べる ──
  const swW = addRemote('ghost', wheel, 'body');
  if (swW) {
    swW.key = 'ArrowUp'; swW.savedLayers = OHM_LAYER_ION;
    swW.fx = 0.795; swW.fy = 0.04;
    placeRemotePanel(swW); syncRemotePanel(swW);
  }
  // ★振動数は8枚を1台で（オームの法則モデルの電圧と同じ理由：1本の導線の電源は1つ）
  const fq = addRemote('prop', emFields[0], 'emfield', emFields.map(f => f.id));
  if (fq) {
    fq.prop = 'freq'; fq.lo = 0; fq.hi = COILAC_FMAX;
    fq.fx = 0.795; fq.fy = 0.28;
    placeRemotePanel(fq); syncRemotePanel(fq);
  }

  // ── 通過カウンタ：上の辺のまん中（抵抗も羽根車もない導線）で通路を横切る線。電子が1秒に何個通ったか＝電流の大きさ ──
  //   ★置き場所は何もない導線（指示。抵抗の中は陽イオンが並んでいて、何を数えているのか読みにくい）。
  //     コイルがあると輪の上で電流がそろわず（羽根車から遠い辺の電子が
  //     その場で往復する）、場所で読みが変わる。同じ辺に4本置いて測った（周期40秒・2秒幅の
  //     毎秒の個数を正弦波に当てはめた振幅と、そこからのずれの標準偏差。コイルあり／なし）：
  //         右の辺 3.62±1.95／8.73±1.29 ・ 上の辺 4.54±1.64／8.79±1.20   ★これ
  //         左の辺 4.76±1.55／8.67±1.35 ・ 抵抗の中 3.54±1.22／8.63±1.22
  //     抵抗の中がいちばん静か（陽イオンが往復を均す）だが、導線だけの辺では上がいちばん静か。
  //     左の辺は交流電源の絵と重なる。
  //     ★ずれは幅を伸ばしてもほとんど減らない（コイルありで 1秒 2.12・6秒 1.34）＝数えの粗さ
  //       ではなく電子の本当の揺れ。幅を伸ばすと遅れだけが増える（counter.js の COUNTER_RATE_WIN）。
  //   ★矢印は左向き＝電場が上の辺で右を向く半周期に電子が進む向き（電子は電場と逆へ動く）。
  //     数えるのは電子の数なので、電流の向きとは逆（いまは向きを問わず数えるので読みには出ない）。
  //   ★数えるのは〈電気を帯びた物体だけ〉（羽根車・陽イオンを拾わない）。
  //   ★グラフの幅は 120秒＝周期40秒の3周期。コイルを外す前と後の山が同じ窓に並ぶ。
  { const c = addCounter(CX, CY + OHM_YT - OHM_CORR/2 - 2, CX, CY + OHM_YT + OHM_CORR/2 + 2);
    if (c) {
      c.what = 'charged'; c.span = COILAC_SPAN;
      // ★毎秒・累計とも向きを問わず数える（指示）。正味だと交流の正と負が打ち消し合い、累計平均が 0 に
      //   近づいて比べる数にならない。両向きの毎秒の平均は周期40秒で コイルなし 6.0／あり 3.4 個/s。
      //   線の上で揺れるだけの電子も数えるので、電流の大きさ（2/π×振幅＝5.5／2.9）より1〜2割多い。
      c.absRate = true; c.absTotal = true;
      c.fx = 0.795; c.fy = 0.56;
      syncCounterPanel(c); placeCounterPanel(c);
    } }

  // ── 交流電源の絵（物理には参加しない）──
  acSourceSketch(CX + OHM_XL, CY + 40);
  const ts = demoTextScale(cam.zoom);
  demoLabel(CX - 60, CY - 78, '● 陽イオン', '#ef5350', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 60, CY - 42, '● 自由電子', '#42a5f5', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 44, CY + 64, '抵抗', '#ef5350', DEMO_NOTE_SIZE * ts, true);
  demoLabel(WX - 60, CY - OHM_OUT_H/2 - 26, 'コイル（羽根車で表した）', '#ffab91', DEMO_NOTE_SIZE * ts, true);

  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'コイルのリアクタンスモデル', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    'コイルモデルの輪を交流で押す。電場の向きが周期的に反転し、電子は行ったり来たりする。\n'
  + '羽根車（コイルの見立て）は重く、向きが変わるたびに止めて回し直さなければならない。\n'
  + '\n'
  + '【手順】▶実行 を押す（2倍速で再生している）\n'
  + '・カウンタは導線を1秒に通る電子の数（向きを問わず）＝電流の大きさ。\n'
  + '　グラフの山の高さか、累計平均で比べる（比べ直すときは 0 に戻す）\n'
  + '・↑ キーで羽根車をすり抜けに（コイルを外す）：山が高くなる＝よく流れる\n'
  + '・振動数のつまみを上げる：コイルがあると山が低くなる。外すとほとんど変わらない\n'
  + '　コイルは交流に対して抵抗のようにはたらき、振動数が高いほど強く妨げる（ωL）\n'
  + '・つまみを 0 にすると直流：羽根車が回り続けるようになり、よく流れる\n'
  + '・電流の向きが変わるのは電場より遅れる。羽根車が止まるのは、電場が反転してしばらくあと',
    DEMO_NOTE_SIZE * ts);
}

// ── コンデンサーのリアクタンスモデル（交流とコンデンサー）────────────────────
//  ★コイルのリアクタンスモデルの羽根車を外し、右の辺を平行板コンデンサーの極板の部屋と
//    仕切りにしたもの（壁は電気振動モデルと同じ capLoopWalls）。抵抗・電子50個・電場の帯8枚・
//    振動数・通過カウンタ・刻み2＋2倍速はコイルのほうとそろえてある。
//    読みどころは「コンデンサーは直流を通さないが交流は通し、振動数が高いほど通しやすい（1/ωC）」。
//  ★**仕切りは壁と図形和せず、別の物体にする**。〈すり抜けにする〉の窓（↑）で仕切りだけを
//    消し、同じ装置で「コンデンサーあり／なし（部屋はただの太い導線）」を比べるため。
//  ★なぜ交流が通るか：電子は仕切りを越えないが、下の極板へ寄る電子と上の極板から出ていく電子が
//    同時に動くので、輪の上では電流が流れる。半周期のうちに極板が満ちきれば電流は止まり、
//    満ちきる前に向きが変われば止まらない＝振動数が高いほど止まる間が無い。
//  ★実測（乱数は使っていない。E=2・刻み2。電源を切って300tick 並ばせ、2周期落ち着かせて3周期の
//    時間平均。電流は上の辺の「電子の速さの和÷辺の長さ」を電場の位相で正弦波に当てはめた振幅、
//    括弧は電場からの遅れ＝負なら進み。電荷は極板の部屋の下−上の電子の数の振幅）：
//        周期        │ 仕切りあり        │ 仕切りなし │ 電荷の振幅
//        80秒        │ 1.75（−71°）     │ 7.1（8°）  │ 23.1
//        40秒 ★初期値 │ 3.2（−51°）      │ 6.4（14°） │ 22.4
//        20秒        │ 5.1（−13°）      │ 6.6（29°） │ 18.6
//        10秒        │ 6.2（+38°）      │ 6.7（53°） │ 10.7
//    （仕切りなしは〈すり抜け〉にした仕切り。4辺の電流は 5% 以内でそろう。1 tick 2.7ms）
//  ★**右の辺の電場の帯は部屋の幅（CAP_W）いっぱい**（ohmLoopBands の rightW。平行板コンデンサー
//    モデルの帯と同じ）。通路の幅（90px）のままだと部屋の左右の張り出しに電場が無く、そこへ
//    押し出された電子が場の無い所に取り残されていた（指示）。広げる前の同じ手順の仕切りあり：
//    1.7／3.1／5.0／6.0・電荷 22.0／21.2／17.2／9.4、直流で電流が 0 になるまで 7秒＝ほとんど同じ
//    仕切りありは振動数にほぼ比例して増え、電場より進む（容量性）。仕切りなしは周期によらず 6.5〜6.8。
//    ★進みは 90° にはならない（抵抗がある RC 直列）。本文で「90°進む」とは言わない。
//    ★周期 10秒は電子の質量（コイルとしてはたらく。コイルのほうの★）が勝って遅れに転じる。
//      つまみの上限はコイルのほうと同じ 0.05Hz（周期20秒）で止める。
//    ★**電荷の振幅は周期40〜80秒で 21〜22 個と頭打ち**＝動ける電子がほぼ全部片側へ寄っている。
//      電圧に比例してたまる（Q=CV）のではなく、満ちきって止まる（平行板コンデンサーモデルの★と
//      同じ根）。電流が振動数に比例するのはこの「満ちきる」のおかげで、1/ωC の比例は見立て。
//    ★コイルのほうと違い、4辺の電流は周期20〜80秒でそろう（右の辺は部屋の中なので小さく出る）。
//  ★直流（つまみ 0）：上の辺の電流の1秒平均は 1.3 → 4.7 → 3.8 → 2.4 → 0.9 → 5秒目から 0。
//    仕切りなしは 20秒たっても 5〜7.6 で流れ続ける。
//  ★通路の外・島の中へ出た電子は延べ 0（0.05Hz・3周期、途中で仕切りを外して戻した）。
const CAPAC_FREQ  = 0.025;   // [Hz] 振動数の初期値（コイルのリアクタンスモデルと同じ。周期40秒）
const CAPAC_FMAX  = 0.05;    // [Hz] つまみの上限（上の★）
const CAPAC_SPEED = 2;
const CAPAC_SPAN  = 120;     // [s] カウンタのグラフの幅（周期40秒の3周期）
// [画面px] 輪を左へずらす量。★右へ張り出した極板の部屋が、右の窓（リモコン2台・カウンタ）の
//   下に隠れないように（コイルのほうは右の辺がただの導線なので、隠れても読みに困らない）
const CAPAC_SHIFT = 130;
function demoCapAcModel() {
  resetDemoWorld();
  setDemoGravity(0);              // ★正面から見た図（オームの法則モデルと同じ）
  updateGroundTerrain(false);
  world.sleeping  = false;
  world.substeps  = 2;            // ★コイルのリアクタンスモデルと同じ（2倍速で毎秒 120 tick）
  world.coulombOn = true;
  world.coulombK  = OHM_COULOMB_K;
  setSpeed(CAPAC_SPEED);

  setDemoCam(0, 0.62);
  const CX = -CAPAC_SHIFT / cam.zoom, CY = cam.y + 180, XR = CX + OHM_XR;
  const metal = { fillColor:'#78909c', strokeColor:'#b0bec5', strokeWidth:1.5,
                  friction:0, frictionStatic:0, restitution:0 };
  const ions = ohmPlaceIons(CX, CY);
  capLoopWalls(CX, CY, metal, []);
  // 仕切り（絶縁体）：壁とは別の物体（冒頭の★）。固定どうしは当たらないので壁に重ねてよい
  const part = new Body(Object.assign({ type:'box', x:XR, y:CY,
    w:CAP_W + 2*OHM_WALL, h:CAP_GAP, isStatic:true }, metal));
  Object.assign(part, { layers:OHM_LAYER_WALL, label:'コンデンサー（仕切り）' });
  objects.push(part);

  // ── 自由電子：コイルモデルと同じ並べかたで 50 個（仕切りの上には置かない）──
  { const PER = ohmLoopPerimeter(), step = PER / COIL_N_E;
    const clear = (x, y) => Math.abs(y - CY) > CAP_GAP/2 + OHM_E_R + 4
      && ions.every(i => (i.x - x)**2 + (i.y - y)**2 > (OHM_ION_R + OHM_E_R + 4)**2)
      && objects.every(o => !o.charge || (o.x - x)**2 + (o.y - y)**2 > (2*OHM_E_R + 4)**2);
    for (let i = 0; i < COIL_N_E; i++) {
      let put = null;
      for (let d = 0; d < 60 && !put; d += 4)
        for (const sgn of (d ? [1, -1] : [0]))
          for (const off of [0, 30, -30, 15, -15]) {
            if (put) continue;
            const p = ohmLoopPoint(i*step + sgn*d);
            const x = CX + p.x + p.nx*off, y = CY + p.y + p.ny*off;
            if (clear(x, y)) put = { x, y };
          }
      if (!put) continue;
      objects.push(new Body({ type:'circle', x:put.x, y:put.y, radius:OHM_E_R,
        mass:OHM_E_M, charge:OHM_E_Q, hasGravity:false, fixedRotation:true, layers:OHM_LAYER_E,
        friction:0, frictionStatic:0, restitution:0,
        fillColor:'#42a5f5', strokeColor:'#e3f2fd', strokeWidth:1.2 }));
    }
  }

  // ── 電場の帯8枚：電源を切った姿（E=0）で電子を反発で並ばせてから交流を入れる ──
  //   ★先に入れると先回しの 300 tick で位相が進む（コイルのリアクタンスモデルと同じ）
  ohmLoopBands(CX, CY, CAP_W);   // ★部屋の中にも電場（下の★）
  demoRunAhead(300);
  for (const f of emFields) { f.strength = OHM_E0; f.freq = CAPAC_FREQ; f.acPhase = 0; }

  // ── 窓：仕切りの有り無し（↑）と振動数のつまみ。どちらも同じ装置1台で比べる ──
  //   ★仕切りをすり抜けにすると部屋はただの太い導線になる＝冒頭の★の表の「仕切りなし」。
  //     極板に電子がたまっている途中で外すと、たまった電子がどっと戻る（物理として正しい）
  const swP = addRemote('ghost', part, 'body');
  if (swP) {
    swP.key = 'ArrowUp'; swP.savedLayers = OHM_LAYER_WALL;
    swP.fx = 0.795; swP.fy = 0.04;
    placeRemotePanel(swP); syncRemotePanel(swP);
  }
  const fq = addRemote('prop', emFields[0], 'emfield', emFields.map(f => f.id));
  if (fq) {
    fq.prop = 'freq'; fq.lo = 0; fq.hi = CAPAC_FMAX;
    fq.fx = 0.795; fq.fy = 0.28;
    placeRemotePanel(fq); syncRemotePanel(fq);
  }
  // ── 通過カウンタ：上の辺のまん中（コイルのリアクタンスモデルと同じ置き場所・同じ設定）──
  { const c = addCounter(CX, CY + OHM_YT - OHM_CORR/2 - 2, CX, CY + OHM_YT + OHM_CORR/2 + 2);
    if (c) {
      c.what = 'charged'; c.span = CAPAC_SPAN;
      c.absRate = true; c.absTotal = true;
      c.fx = 0.795; c.fy = 0.56;
      syncCounterPanel(c); placeCounterPanel(c);
    } }

  // ── 絵（物理には参加しない）──
  acSourceSketch(CX + OHM_XL, CY + 40);
  const ts = demoTextScale(cam.zoom);
  demoLabel(CX - 60, CY - 78, '● 陽イオン', '#ef5350', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 60, CY - 42, '● 自由電子', '#42a5f5', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 44, CY + 64, '抵抗', '#ef5350', DEMO_NOTE_SIZE * ts, true);
  demoLabel(XR + CAP_W/2 + OHM_WALL + 12, CY - 14, 'コンデンサー', '#b0bec5', DEMO_NOTE_SIZE * ts, true);

  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'コンデンサーのリアクタンスモデル', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    'オームの法則モデルの輪の右の辺に、平行板コンデンサーの極板と仕切り（絶縁体）を入れ、\n'
  + '交流で押す。電子は仕切りを越えられないが、下の極板へ寄る電子と上の極板から出ていく\n'
  + '電子が同時に動くので、輪の上では電流が流れる。\n'
  + '\n'
  + '【手順】▶実行 を押す（2倍速で再生している）\n'
  + '・カウンタは導線を1秒に通る電子の数（向きを問わず）＝電流の大きさ。\n'
  + '　グラフの山の高さか、累計平均で比べる（比べ直すときは 0 に戻す）\n'
  + '・↑ キーで仕切りをすり抜けに（コンデンサーを外す）：山が高くなる＝よく流れる\n'
  + '・振動数のつまみを上げる：コンデンサーがあると山が高くなる。外すとほとんど変わらない\n'
  + '　極板が満ちきる前に向きが変わるので止まる間が無い。コンデンサーは交流に対して\n'
  + '　抵抗のようにはたらき、振動数が低いほど強く妨げる（1/ωC）\n'
  + '・つまみを 0 にすると直流：極板が満ちると電流は止まる（直流は通さない）\n'
  + '・電流の向きが変わるのは電場より早い。極板が満ちてくると、電場が反転する前に流れが弱まる',
    DEMO_NOTE_SIZE * ts);
}

// ── 電気振動モデル（コイル＋コンデンサー）──────────────────────────
//  ★コイルモデルの輪（左うえの角に羽根車）の右の辺を、平行板コンデンサーモデルの極板の部屋と
//    仕切りにしたもの。寸法は OHM_*／CAP_*／COIL_* をそのまま使う。**抵抗（陽イオン）は置かない**。
//    **電子 50 個を仕切りの下の極板に詰めた姿（充電したコンデンサー）から始め、▶実行で放電が
//    始まる**（スイッチは置かない。指示）。電子が羽根車を回しながら抜け、羽根車の回りつづける
//    勢いで行き過ぎて上の極板にたまる。これをくり返す（周期 T = 2π√(LC) の見立て）。
//  ★2026-09 までは電場の帯8枚で充電させていた（電源の絵・〈電圧〉のつまみ・〈切る〉スイッチ）。
//    やめた理由と当時の実測は LC_PACK の★。下の★の「充電して切る」はその頃の手順。
//  ★いまの作りの実測（羽根車 8kg・刻み 2。開いてから 120秒。1秒平均。電荷＝極板の部屋の下−上の
//    電子の数）：電荷 50 → 28（最初の1秒）→ −10.6 → +6.0 → −2.5 → +2.5、羽根車 +1.02 → −0.64 →
//    +0.41 → −0.26 rad/s（半周期ごとの比 0.6 前後）、周期 約42秒（2倍速で見かけ 約21秒）。
//    詰めた 50 個のうち反対側へ渡るのは 10 個ほど：残りは下の辺・左の辺の導線へ散って、そこに
//    とどまる（導線そのものが電子の溜まり場になる。LC_PACK の★と同じ根）。通路の外へ出た電子 0。
//  ★羽根車の重さ（＝L）で減り方と周期が引き換えになる（刻み 4・120秒）：
//      2kg 比 0.45〜0.62・約24秒 ／ 4kg 0.45〜0.72・約34秒 ／ 8kg 0.59〜0.68・約42秒
//    8kg なら電荷が −10.3 → +8.7 → −5.7 → +3.8 → −2.3 と5回振れるが、周期が 45秒近くになる
//    （長すぎると言われた長さ）。羽根車なしは 約13秒 で −12.3 → +7.6 → −4.3 と振動する。
//  ★**羽根車を外しても振動する**。電子の質量そのものが小さなコイルとしてはたらくため（本物の
//    回路では導線の抵抗が勝って振動しない）。実測（下の表と同じ手順）：羽根車なしで周期 約11秒、
//    電荷 11.4 → −6 → +4.9。抵抗で止めようとすると、コイルありの振動もほとんど止まった：
//        抵抗の作り                     │ 羽根車なしの行き過ぎ │ 2kg の行き過ぎ │ 周期
//        陽イオン（区間を半分）・k=250   │   平均14%（2〜28%） │ 平均25%（18〜32%）│ 17秒
//        電子の抗力 Cd=1                 │       11%         │     32%        │ 21秒
//        電子の抗力 Cd=3                 │        0%         │     13%        │ 20秒
//        電子を 0.002kg＋陽イオン        │        —          │    7〜15%      │ 19秒
//    羽根車の L は電子の質量の L の約3倍しかない（周期 21秒 対 11秒）。本物のコイルは導線の L より
//    けた違いに大きいので分かれるが、ここでは差が小さすぎる。羽根車を重くすると周期が 45秒を超える。
//    ＝**「コイルがなければ振動しない」はこの模型では出せない**。本文でも言わない。羽根車の
//    〈すり抜けにする〉の窓を付けないのもこのため（指示）。
//  ★クーロン定数は 250（オームの法則モデルの 50 の5倍）。反発の強さが極板の戻す力＝1/C で、
//    50 では周期が 75秒（4kg）と遅すぎた。右パネルの全体設定で手で変えられる値。
//    実測（電子50・羽根車 2kg〜4kg・抵抗なし。40秒充電して切り、仕切りの下−上の電子の数を1秒平均）：
//        k   │ 羽根車 │ 周期  │ 電荷の振れ
//        50  │  4kg  │ 約75秒 │ 遅すぎて振動に見えない
//        150 │  4kg  │ 約45秒 │ 13 → −7.7 → +4.5 → −1
//        250 │  2kg  │ 約21秒 │ 10.3 → −6.2 → +3.9 → …   ★これ
//        400 │  4kg  │ 約30秒 │ 8.4 → −4.7 → +2.9（たまる電子が減る）
//  ★このデモそのものの実測（リモコンで入れて 35／40／45秒 充電して切る。1秒平均）：
//      電荷 10.4〜10.8 → −6.2〜−7.5（11〜13秒）→ +2.0〜+4.0（24〜28秒）→ −1 → 落ち着く（+1）
//      羽根車 +0.9〜1.0 → −0.5 → +0.25 → −0.1 rad/s。周期 約23秒・半周期ごとに振れが半分。
//      通路の外へ出た電子 0。1 tick 8ms（電子50・刻み4・k=250）。
//    ★2026-09 積分の順序を直したあと（下の★）の同じ手順：電荷 10.2〜11.1 → −6.4〜−7.7 →
//      +3.1〜+5.0 → −1〜−3、羽根車 +0.76〜1.05 → −0.4〜−0.65 → +0.17〜0.3 → −0.06〜−0.2 rad/s、
//      周期 約23〜25秒。2回目・3回目の振れが少し残るようになったが、半周期ごとにほぼ半分は同じ。
//  ★**振動を小さくしているのは電子と壁の衝突**で、羽根ではない。切って15秒の熱（物体の温度から）：
//      壁 1.03 J・羽根車 0.05 J・電子 0.003 J（同じ間に失われた力学的エネルギー 約1.1 J）。
//    反発係数を上げても減衰は変わらない（羽根車の振れの半周期ごとの比 0.5〜0.6）：電子と羽根車を
//    1 にしても 0.60、壁まで全部 1 にすると 0.26 と**かえって悪化**する。全部 1 のとき熱は 0.24 J に
//    減るが、エネルギーは同じだけ（約1.0 J）減っていて、残り 約0.8 J は熱にも数えられずに消えている。
//    ★消えていたのは積分の順序のせい：emStepPre がクーロン力を1サブステップぶん丸ごと速度に
//      足してから位置を進めていたので、弾む・押しつけられる電子からエネルギーが漏れていた。
//      2026-09 に半分ずつ位置の前後で効かせるよう直した（step.js の★）。切って15秒の収支：
//        反発0（このデモ）：ΔE −1.18 J・熱 1.09 J → ΔE −1.04 J・熱 1.14 J（ほぼ全部が熱）
//        全部 1          ：ΔE −1.03 J・熱 0.24 J → ΔE −0.44 J・熱 0。積分からの漏れは消えたが、
//                          羽根車のヒンジの補正で −0.54 J 出る（熱い電子に揺すられた車の軸。未調査）
//      直しても振動はほとんど良くならない：全部 1 だと充電中に電源の仕事が電子のばらばらな
//      運動にたまり（乱れの速さ 350px/s、反発0では 30〜100）、電荷の振れが雑音に埋もれる。
//      反発0 の振れは上の「このデモそのものの実測」の★。
//    反発係数の合成は積（geometry.js）。
//  ★電子を増やす・部屋を広げるは逆効果だった（抵抗ありで試した。電子70 や 幅400 で行き過ぎが
//    29% → 9〜15% に落ちた）。極板に正の電荷が無く、戻す力が輪全体の反発に散っているため
//    （平行板コンデンサーモデルで Q=CV が出ないのと同じ根）。
const LC_COULOMB_K = 250;  // 実効クーロン定数（上の★）
// [kg] 羽根車の質量（＝L）。★2 → 8 に上げ、再生を 2倍速にした（LC_SPEED。指示）。重くすると
//   半周期ごとの減り方が 0.45〜0.62 → 0.59〜0.68 に緩み、はっきり振れる回数が 3〜4 → 5〜6 に
//   増えるが、周期が 約24 → 42秒 に延びる（上の★の表）。見かけの周期は倍速で半分の 約21秒。
const LC_M         = 8;
// 再生の倍率（上のバーの〈速度〉と同じ。resetDemoWorld が 1 に戻すので、ほかのデモへは持ち越さない）
const LC_SPEED     = 2;
// [px] 最初に下の極板へ電子を詰める間隔（六方詰め。電子の直径は 14px）。
//   ★**電場で充電するのをやめ、詰めた姿から始める**（指示）。電場で充電していた頃の実測
//     （充電 35／40／45秒の平均。最初の振れ → 1回目の行き過ぎ → 2回目 [個]・周期）：
//       電圧 2  10.6 → −6.9 → +3.9  約24秒      電圧 6  15.6 → −9.3 → +5.8  約24秒
//       電圧 10 18.1 → −8.5 → +4.9               電圧 20 21.5 → −9.4 → +5.5
//     たまる電子は電圧に比例せず（下の極板に 11.7／17.2／21.0／27.9 個＠2／6／10／20）、
//     振れは 6 あたりで頭打ち：多く押し込んだぶんは切って1〜2秒で、羽根車が回り出す前に
//     下の辺の導線へ跳ね返った。場は外から与えっぱなしで打ち消されないので、導線そのものが
//     電子の溜まり場になる（Q=CV が出ないのと同じ根）。
//     ＝電場は振れを大きくする役に立たず、充電の手順だけがデモの半分を占めていた。
// 輪（OHM_*）の右の辺に極板の部屋（CAP_*）を張り出させた壁を1つの物体で置く。extra は
//   一緒に図形和する物体（電気振動モデルは仕切り）。仕切りと部屋の角の丸みも入れる。
//   電気振動モデルとコンデンサーのリアクタンスモデルで共有する
//   外側の壁：角丸の板＋部屋を包む箱 から、一回り小さい角丸の板と部屋を抜く。
//   島：部屋が食い込む側を削った中空の角丸（平行板コンデンサーモデルの島と同じ作り）
function capLoopWalls(CX, CY, metal, extra) {
  const H = OHM_CORR/2, W = OHM_WALL, RW = CAP_W/2, RH = CAP_H/2, XR = CX + OHM_XR;
  const roundParts = (A, B, R) => {
    const mk = o => new Body(Object.assign({ isStatic:true }, metal, o));
    const ps = [ mk({ type:'box', x:CX, y:CY, w:2*A,       h:2*(B - R) }),
                 mk({ type:'box', x:CX, y:CY, w:2*(A - R), h:2*B       }) ];
    for (const sx of [-1, 1]) for (const sy of [-1, 1])
      ps.push(mk({ type:'circle', x:CX + sx*(A - R), y:CY + sy*(B - R), radius:R }));
    return ps;
  };
  const room = () => new Body(Object.assign({ isStatic:true, type:'polygon', x:XR, y:CY, verts:[
    { x:-RW, y:-CAP_HS }, { x:-H, y:-RH }, { x:H, y:-RH }, { x:RW, y:-CAP_HS },
    { x:RW, y: CAP_HS }, { x:H, y: RH }, { x:-H, y: RH }, { x:-RW, y: CAP_HS } ] }, metal));
  const roomBox = () => new Body(Object.assign({ isStatic:true, type:'box',
    x:XR, y:CY, w:2*(RW + W), h:2*(RH + W) }, metal));
  const A0 = OHM_OUT_W/2, B0 = OHM_OUT_H/2, RO = OHM_CR + H + W;
  const outer = demoBoolean('diff', [ demoUnion(roundParts(A0, B0, RO), roomBox()),
    ...roundParts(A0 - W, B0 - W, RO - W), room() ]);
  const IA = OHM_XR - H, IB = OHM_YB - H, IR = OHM_CR - H;
  const hole = demoBoolean('diff', [ demoUnion(roundParts(IA - W, IB - W, IR - W)), roomBox() ]);
  const isl  = demoBoolean('diff', [ demoUnion(roundParts(IA, IB, IR)), hole, room() ]);
  const walls = demoUnion(outer, isl, ...extra, ...capFillets(XR, CY, metal));
  walls.layers = OHM_LAYER_WALL;
  return walls;
}

const LC_PACK      = 16;
function demoLcOscillationModel() {
  resetDemoWorld();
  setDemoGravity(0);
  updateGroundTerrain(false);
  world.sleeping  = false;
  // ★刻みは 2（コイルモデルは 4）。2倍速（LC_SPEED）で毎秒 120 tick 回すため。電子 50 個で
  //   1 tick 8.0 → 4.2ms。振動は変わらない（120秒の羽根車の山：刻み4 0.92 → −0.63 → +0.39 →
  //   −0.27、刻み2 1.02 → −0.64 → +0.41 → −0.26）。通路の外へ出た電子 0。弾けた直後の電子は
  //   最大 約640px/s で、1刻み 約5px ＝ 半径 7px より小さい。刻み4 のままだと 2倍速の実際の
  //   速さは 1.40倍にとどまった（計算が追いつかない。検証の環境で）。
  world.substeps  = 2;
  world.coulombOn = true;
  world.coulombK  = LC_COULOMB_K;
  setSpeed(LC_SPEED);             // ★LC_M の★（重い羽根車で延びた周期を見かけで半分に）

  setDemoCam(0, 0.62);
  const CX = 0, CY = cam.y + 180;
  const H = OHM_CORR/2, W = OHM_WALL, RW = CAP_W/2, RH = CAP_H/2, XR = CX + OHM_XR;
  const metal = { fillColor:'#78909c', strokeColor:'#b0bec5', strokeWidth:1.5,
                  friction:0, frictionStatic:0, restitution:0 };

  // ── 通路：オームの法則モデルの輪の右の辺に、極板の部屋を張り出させる。仕切りも壁と図形和 ──
  const part = new Body(Object.assign({ type:'box', x:XR, y:CY,
    w:CAP_W + 2*OHM_WALL, h:CAP_GAP, isStatic:true }, metal));
  capLoopWalls(CX, CY, metal, [part]);

  // ── 羽根車（コイルの見立て）：コイルモデルと同じ形・同じ置き場所 ──
  const WX = CX + OHM_XL + OHM_CR, WY = CY + OHM_YT + OHM_CR;
  const RT = OHM_CR + H - COIL_GAP;
  const onBlade = (x, y, pad) => {
    const dx = x - WX, dy = y - WY, r = Math.hypot(dx, dy);
    if (r > RT + pad) return false;
    if (r < COIL_HUB_R + pad) return true;
    for (let k = 0; k < COIL_NB; k++) {
      const a = k * Math.PI / COIL_NB;
      if (Math.abs(-Math.sin(a)*dx + Math.cos(a)*dy) < 4 + pad) return true;
    }
    return false;
  };

  // ── 自由電子：50 個を全部、仕切りの下の極板に詰めておく（充電しきった姿）──
  //   ★電場で充電させるのはやめた（指示）。場は外から与えっぱなしで打ち消されないので、
  //     強くしても極板にたまる数は頭打ちで、充電の手順がデモの半分を占めていた（冒頭の★）。
  //   ★詰めかたは六方（間隔 LC_PACK）。極板の六角形の内側から、壁・丸みに半径ぶんの余白を取る。
  { const hw = d => d <= CAP_HS ? RW : RW - (RW - H) * (d - CAP_HS) / (RH - CAP_HS);
    const m = OHM_E_R + 3, spots = [];
    for (let k = 0; ; k++) {
      const d = CAP_GAP/2 + OHM_E_R + 1 + k * LC_PACK * 0.866;
      if (d > RH - m) break;
      const w = hw(d + (d > CAP_HS ? OHM_E_R : 0)) - m
              - (d < CAP_GAP/2 + CAP_FILLET + 8 ? CAP_FILLET : 0);   // ★仕切りの角の丸み
      for (let x = -w + (k % 2) * LC_PACK/2; x <= w; x += LC_PACK) spots.push({ x:XR + x, y:CY + d });
    }
    for (const s of spots.slice(0, COIL_N_E))
      objects.push(new Body({ type:'circle', x:s.x, y:s.y, radius:OHM_E_R,
        mass:OHM_E_M, charge:OHM_E_Q, hasGravity:false, fixedRotation:true, layers:OHM_LAYER_E,
        friction:0, frictionStatic:0, restitution:0,
        fillColor:'#42a5f5', strokeColor:'#e3f2fd', strokeWidth:1.2 }));
  }

  const COIL = { fillColor:'#c77c48', strokeColor:'#ffccbc', strokeWidth:1.5,
                 friction:0, frictionStatic:0, restitution:0 };
  const parts = [ new Body(Object.assign({ type:'circle', x:WX, y:WY, radius:COIL_HUB_R }, COIL)) ];
  for (let k = 0; k < COIL_NB; k++)
    parts.push(new Body(Object.assign({ type:'box', x:WX, y:WY, w:2*RT, h:8,
      angle:k * Math.PI / COIL_NB }, COIL)));
  const wheel = demoUnion(parts);
  Object.assign(wheel, COIL, { isStatic:false, hasGravity:false, layers:OHM_LAYER_ION,
                               label:'コイル（羽根車）' });
  wheel.setMass(LC_M);
  joints.push(new Joint({ type:'hinge', bodyA:null, bodyB:wheel,
    anchorAx:WX, anchorAy:WY, anchorBx:WX - wheel.x, anchorBy:WY - wheel.y }));

  // ── 絵（物理には参加しない）──
  const ts = demoTextScale(cam.zoom);
  demoLabel(WX - 60, CY - OHM_OUT_H/2 - 26, 'コイル（羽根車で表した）', '#ffab91', DEMO_NOTE_SIZE * ts, true);
  demoLabel(XR + RW + W + 12, CY - 14, 'コンデンサー', '#b0bec5', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX - 60, CY - 42, '● 自由電子', '#42a5f5', DEMO_NOTE_SIZE * ts, true);

  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '電気振動モデル', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    'コイルモデルの羽根車（コイル）と、平行板コンデンサーモデルの極板（コンデンサー）を\n'
  + '1つの輪にした。抵抗は入れていない。電子どうしの反発は他のモデルより強くしてある。\n'
  + '最初、電子は仕切りの下の極板に詰めてある（充電したコンデンサー）。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・詰まっていた電子が羽根車を回しながら抜けていき、羽根車の勢いで行き過ぎて\n'
  + '　上の極板にたまる。これをくり返す＝電気振動。羽根車の回る向きも入れ替わる\n'
  + '・振動はだんだん小さくなる（電子が導線の壁にぶつかるたびに勢いを失う）',
    DEMO_NOTE_SIZE * ts);

  // ★先回し（demoRunAhead）はしない。▶実行を押した瞬間から放電が始まる＝詰めた姿で開く。
}

// ── 帯電した小球のつりあい（2球の反発）─────────────────────────
//  ★題材は「クーロンの法則」ではなく**つりあい**。小球にはたらく力は3つしかなく
//    （重力・糸の張力・静電気力）、その3つが閉じる角度で止まる。だから式は
//    tanθ = F/(mg) で、電気量のつまみと質量のつまみを**両方**置く。片方しか無いと
//    「電気を与えると開く」という片側の話になり、分母の mg が題材から落ちる。
//  ★糸は**小球の中心に留める**（anchorB を (0,0) にする）。上端（0,−r）に留めると、
//    糸の長さを一定に保っても支点から中心までの距離が**角度で変わる**（拘束式は
//    √(L²−2Lr·cosθ+r²) ＝ 糸の長さ。r=18px・糸 302px なら L は θ=0 で 320px、
//    θ=48° で 314px）＝ 長さの決まった振り子でなくなる。
//    つりあいの角度を数で読ませる題材なので、ここは譲れない。
//    ★中心留めは絵としても正しい：θ は「支点と中心を結ぶ線」と鉛直のなす角で、
//      教科書の図もその線を糸として描いている。
//  ★ロープは繋いだ相手とは当たらない（js/physics/rope.js:66）ので、糸の下端が球の
//    内側にあっても接触にはならない。
//  ★2球は同じ1台のつまみにつなぐ。別々にすると「電気量が違う2球」が作れてしまうが、
//    そのときも**たがいに及ぼす力は同じ大きさ**（作用・反作用）なので開き方は変わらず、
//    つまみが2つある意味がない。つまみは「効く操作だけ」に絞る。
//  ★色は銀。つまみで符号を反転できるので、赤（＋の色）に塗ると − にしたとき絵が嘘をつく。
//    符号は drawCharges が描く ⊕⊖ の記号が受け持つ。
//  ★**糸の線密度はこの題材に一切効かない。** 端どうしの距離が糸の長さぴったりなので
//    ロープはいつも張りきっていて、たるみは 0.0px。実測（0.01／0.05／0.2／1.0 kg/m の4つ）：
//    落ち着く角度・落ち着くまでの tick・残りの揺れが**4桁まで完全に一致**した。
//    ＝ この使い方のロープは「重さのない伸びない糸」そのもので、教科書の前提と食い違わない。
//  ★実測（乱数固定・3000tick 落ち着かせてから 300tick の時間平均）。理論は
//    tanθ = F/(mg) に F = kq²/r²・r = 2L sinθ を入れて解いた sin²θ·tanθ = k q²/((2L)²mg)：
//      q[C]  0.6   1.0   1.5   2.0  −0.6  −2.0 ／ q=0.6 で m=0.01  m=0.05 ／ q=2.0 m=0.05
//      実測 25.53 35.80 46.52 55.46 25.52 55.46        32.11   18.87        41.75
//      理論 25.54 35.79 46.51 55.47 25.54 55.47        32.13   18.83        41.71
//      揺れσ 0.02  0.11  0.10  0.09  0.11  0.09         0.04    0.30         0.31
//    ずれはどこも 0.04° 以内。**符号を反転した組は同じ角に落ちる**（25.53↔25.52、
//    55.46↔55.46）＝ q² で効くことが実測でも出ている。
//    ★この表は空気抵抗ありの頃（Cd=2.5）に取ったもの。落ち着く角そのものは抵抗では
//      変わらないので有効だが、**揺れσの列は Cd=0 のいまは当てにならない**
//      （つまみを回したあとは鳴り続ける。CB_DRAG の★に実測を置いた）。
//  ★電気量 0 では2球は触れ合う（θ = asin(r/L) = 3.22°、実測 3.16°）。鉛直にはならない。
//    同じ点から吊るした半径のある球なので当たり前で、直すところではない。
const CB_L     = 320;    // [px] 糸の長さ（支点から小球の中心まで）
const CB_R     = 18;     // [px] 小球の半径
// [kg] 小球の質量。★直径 36cm で 20g ＝ 密度 3.9 kg/m³ の「風船くらいの球」で、
//   落下（空気抵抗）のデモの球（直径 40cm・20g ＝ 3.2 kg/m³）と同じ扱い。
const CB_M     = 0.02;
const CB_MLO   = 0.01;   // [kg] 質量つまみの下限
// [kg] 質量つまみの上限。★もとは「これ以上だと揺れが止まらない」ことを理由に切っていたが、
//   空気抵抗を 0 にした（CB_DRAG の★）いまはどの質量でも止まらないので、その理由は無い。
//   0.01〜0.05 kg は tanθ = F/(mg) を読むのに十分な幅（0.6C で 32.1°〜18.8°）なので、
//   幅はそのまま残す。
const CB_MHI   = 0.05;
const CB_Q     = 0.6;    // [C]  電気量の初期値（この組み合わせで開きが 25.5°）
const CB_QMAX  = 2.0;    // [C]  電気量つまみの上限（同 55.5°）
const CB_HANG  = 500;    // [px] 地面から支点までの高さ
// 抗力係数。★**0 ＝ 空気抵抗なし**。教科書のつりあいの問題と同じ前提（はたらく力は
//   重力・張力・静電気力の3つだけ）に揃えるため、指示で 0 にした。
//   ★代償は実測してある。1800tick 落ち着かせてから電気量を 0.6→1.5 にしたときの、
//     最終角へ収まるまでの tick と、最後の 300tick での振れ幅：
//       Cd=2.5（もとの値）：±1° まで 587tick（9.8秒）・残りの振れ幅 0.35°
//       Cd=0  （これ）    ：**収まらない**・残りの振れ幅 42.63°（±21°で鳴り続ける）
//     ＝ つまみを回したあとは振り子が永久に鳴り、時間平均の角も 50.24°（理論 46.51°）と
//     ずれて読めなくなる。**開いた姿のまま眺めるぶんには効かない**（開時の振れ幅は
//     Cd=2.5 で 0.078°、Cd=0 で 0.13°）ので、静止した図として使うなら問題は出ない。
//   ★2026-09 電磁気の力を半分ずつ位置の前後で効かせるようにした（step.js の★）あとの実測
//     （1800tick 置いて 0.6→1.5C、6000tick 後の最後の300tick。上の表とは測る時刻が違い、
//     旧の順序でもこの手順では 42.63° にならない）：Cd=0 の振れ幅 旧 33.4° → 新 37.5°・平均
//     48.3° → 48.7°（エネルギーが漏れなくなったぶん大きく鳴る）。Cd=2.5 は ±1° まで 586 → 587tick。
//     上の表のつりあいの角は 9通りとも新旧の差 0.01° 以内。
//   ★振り子は抗力では止められない（減衰が v² で、小さい揺れに効かない）。ここを戻したく
//     なったら Cd を上げるのが唯一の手で、0.47（球の実測値）でも ±2° に 1544tick かかる。
const CB_DRAG  = 0;
// 力の矢印の倍率 [画面px/N]。★既定の 1 px/N では 0.2 N の重力が 0.2px ＝ 何も見えない。
//   360 なら既定の姿（20g）の重力 0.196 N が 71px ＝ 力学のデモとおおむね同じ長さになる。
//   矢印の頭打ちは 260px（js/render/vectors.js）で、この題材でいちばん長いのは
//   両方のつまみを上限にしたときの張力 0.657 N ＝ 237px。中に収まる。
const CB_FVS   = 360;

function demoChargedBallBalance() {
  resetDemoWorld();
  updateGroundTerrain(true);
  world.sleeping  = false;        // ★張力の矢印は解いた結果なので、眠らせると消える
  world.substeps  = 8;
  world.coulombOn = true;
  world.forceVizScale = CB_FVS;

  const gy = ground.y, HY = gy - CB_HANG;          // 支点（2本の糸を留める1点）
  // ── 天井のはり（固定した板）──
  objects.push(new Body({ type:'box', x:0, y:HY - 11, w:300, h:22, isStatic:true,
    friction:0, frictionStatic:0, restitution:0, label:'天井',
    fillColor:'#78909c', strokeColor:'#b0bec5', strokeWidth:1.5 }));

  // ── 小球2つ。★はじめから開いた姿（既定のつまみでのつりあい）で置く ──
  const th0 = 25.5 * Math.PI / 180;
  const balls = [-1, 1].map(sgn => {
    const b = new Body({ type:'circle', x: sgn * CB_L * Math.sin(th0),
      y: HY + CB_L * Math.cos(th0), radius:CB_R,
      mass:CB_M, charge:CB_Q, drag:CB_DRAG, fixedRotation:true, showForces:true,
      friction:0, frictionStatic:0, restitution:0,
      label: sgn < 0 ? '小球A' : '小球B',
      fillColor:'#cfd8dc', strokeColor:'#eceff1', strokeWidth:1.5 });
    objects.push(b);
    joints.push(new Joint({ type:'rope', bodyA:null, anchorAx:0, anchorAy:HY,
      bodyB:b, anchorBx:0, anchorBy:0,
      restLength:CB_L, maxLength:CB_L, radius:2, color:'#a5d6a7' }));
    return b;
  });

  // ── 操作：電気量と質量のつまみ。★どちらも2球へ同時に効かせる（1台で2つを受け持つ）──
  const ids = balls.map(b => b.id);
  const knob = (prop, lo, hi, fy) => {
    const r = addRemote('prop', balls[0], 'body', ids);
    if (!r) return;
    r.prop = prop; r.lo = lo; r.hi = hi; r.fx = 0.055; r.fy = fy;
    placeRemotePanel(r); syncRemotePanel(r);
  };
  //   ★窓は左に縦へ2つ。上は本文の下端、下は力の矢印の凡例（画面の左下）に掛からない
  //     高さに置く（窓の丈は 171px あり、この2つに挟まれた帯はちょうど2つぶんしかない）。
  knob('charge', -CB_QMAX, CB_QMAX, 0.36);
  knob('mass',   CB_MLO,   CB_MHI,  0.60);

  // ── 画面 ──
  setDemoCam(-340, 0.65);
  const ts = demoTextScale(cam.zoom);
  // 鉛直の補助線（θ を読むための線。物理には参加しない）
  demoDashedPath(0, HY, 0, HY + CB_L + 70, 'rgba(176,190,197,0.55)', 2);
  demoLabel(28, HY + 92, 'θ', '#cfd8dc', DEMO_NOTE_SIZE * ts, true);
  demoLabel(176, HY - 42, '天井（固定）', '#b0bec5', DEMO_NOTE_SIZE * ts);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '帯電した小球のつりあい', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    '同じ点から2本の糸で吊るした、同じ小球2つ。同じ符号に帯電させると反発して開く。\n'
  + 'はたらく力は3つだけ（重力・糸の張力・静電気力）で、tanθ = F/(mg) でつりあう。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・〈電荷〉を上げると反発が強くなって開く。開くほど間隔が広がって力は\n'
  + '　弱まり、どこかで釣り合って止まる。− 側へ回しても同じだけ開く（q² で効く）\n'
  + '・〈質量 [kg]〉を上げると、同じ電気量でも開きが小さくなる（mg が増える）\n'
  + '・矢印：静電気力（黄）と重力（赤）を合わせたぶんを、張力（緑）が引き受ける\n'
  + '・空気抵抗は無い。つまみを回したあとは新しい角度のまわりで揺れ続ける',
    DEMO_NOTE_SIZE * ts);

  // ★つりあいの姿で開く。置いた角度は計算値そのままなので、ここで解に落ち着かせる
  demoRunAhead(600);
}

// ── 電場と電気力線 ─────────────────────────────────────────
//  ★電気力線と等電位線を描く道具はもうある（js/em/charge-field.js）。だからこのデモの
//    仕事は「線を出すこと」ではなく、**線が何を意味するかを、動かして確かめられる形に
//    すること**。置いたのは次の3つだけ：
//      ・固定した電荷2つ（どちらもつまみで符号と大きさを変えられる）
//      ・試験電荷1つ（つかんで好きな所へ置き、放すと走り出す。電気量もつまみで変える）
//      ・力の矢印（試験電荷に1本だけ出す）
//    つまみで 双極子／同符号／単独 の3つの絵が続きで変わり、線の本数も |q| に
//    比例して増え減りする＝「線の密度＝電場の強さ」が絵の側で動いて見える。
//  ★**電場ベクトルの矢印は置かない**（機能ごと廃止した）。もとは力の矢印と同じ倍率で
//    重ねて出し、長さの比 ＝ 電気量（F = qE）を読ませていたが、**2本とも力に見えた**：
//    同じ根もとから生え、色もほとんど同じ（電場 #ffd54f と電気力 #ffca28）で、凡例には
//    「電気力 [N]」しか載らない。実際「電気力が2本出ているのはなぜ」と読まれた。
//    単位を書き分ける（N/C と N）のも試したが、矢印1本のために UI を5か所
//    （右パネル・メニュー・右クリック・全体設定・body プロパティ）持つ釣り合いではない。
//    ★残った読み方のほうが素直：**力の矢印1本を電気力線と見比べる**。⊕ なら線に沿い、
//      ⊖ なら線と逆を向く＝「電気力線の向きは ⊕ が受ける力の向き」がそのまま絵になる。
//    ★開く姿の試験電荷は負のまま（EF_TQ = −0.5C）。もとは「2本の矢印を離すため」に
//      負にしてあったが、その理由が消えたいまも負を既定にする理由はある——**逆向きのほうが
//      読みどころだから**（⊕ は「線に沿う」で当たり前に見えるが、⊖ は定義を裏返して
//      確かめる側）。⊕ はつまみを右へ回せばすぐ出る。
//      ★この配置（⊕ 側の下半分）で測った下の実測値は q = −0.5C のもの。符号を変えると
//        軌道はまったく別物になるので、既定を ⊕ に変えるなら測り直すこと。
//  ★試験電荷は**場の源から外す**（fieldSource:false）。教科書の「まわりの場を乱さない
//    ほど小さい電荷」がこれにあたる。外していることは画面の下に自動で出る
//    （js/render/vectors.js の drawFieldNotes）ので、こちらで断り書きを足さなくてよい。
//    ★外してよい根拠：源の2つは固定した物体なので、試験電荷から受ける力では動かない。
//      ＝「乱さない」は表示の都合ではなく、この配置では実際に成り立っている。
//  ★**電気力線は道すじではない。** 静止から放した瞬間だけは力線の向きへ動き出すが、
//    速さを持ったあとは慣性で外へふくらみ、軌道は力線から外れる。ここを混同させないのが
//    このデモでいちばん効く一行なので、本文にも明記する（線は「力の向き」の地図であって
//    「電荷の通り道」ではない）。
//    実測（既定の置き場所から放す）：放した1tick目の速度の向きは力の向きと**完全に一致**
//    （単位ベクトルの内積 1.000）。そこから 247px 走るあいだに、同じ点を通る力線から
//    最大 32px ＝ 13% ずれ、隣の線をまたいで ⊕ に落ちる（94tick ＝ 1.6秒）。
//    ★置き場所で効きは変わる。⊖ の側（図の右半分）へ置くと ⊖ に押されて ⊕ の井戸から
//      出てしまい、画面の外まで飛ぶ（走行 1200〜3000px）。既定を ⊕ の側に置いてあるのは、
//      「放して → 曲がって → 落ちる」までが 2秒たらずで1画面に収まるため。
//  ★重力は 0 で地面も出さない（回路図と同じ、正面から見た図）。オームの法則モデルと同じ扱い。
// [C] 固定した電荷の電気量。★8本/C なので 16本ずつ出る。3.0（24本）から下げた：
//   同符号にすると 48本になり、線が画面を埋めて説明の本文が読めなくなった。
//   16本なら双極子も同符号も形が読めて、つまみを上へ回せば本数が増えるのも見える。
//   ★2つとも上限まで回せば、いまでもその 48本の絵にはなる（両方 +3）。そこは止めない：
//     開く姿が埋まっているのと、自分で回して埋めたのとは別のこと。実際に撮ってみると
//     線は本文の後ろを通るだけで、文字は読めたままだった。
const EF_Q   = 2.0;
const EF_QMAX= 3.0;    // [C]  つまみの幅（−3〜+3。既定より増やせる側も要る）
const EF_R   = 26;     // [px] 固定した電荷の半径
const EF_D   = 170;    // [px] 中心から左右への距離（間隔 3.4m）
const EF_TQ  = -0.5;   // [C]  試験電荷の電気量（開く姿）。★負であることは上の★
// [C] 試験電荷のつまみの幅（−1〜+1）。★源の 2C より小さいところで切る：
//   「まわりの場を乱さないほど小さい電荷」という体裁は、場から外してあること
//   （fieldSource:false）だけでなく、数の大小でも合っていたほうがよい。
const EF_TQMAX = 1.0;
const EF_TM  = 0.2;    // [kg] 試験電荷の質量
const EF_TR  = 11;     // [px] 試験電荷の半径
// 力の矢印の倍率 [画面px/N]。★電場の矢印と対にしていた頃は 100 で、力はその半分の
//   27px しかなかった（長いほうは電場が受け持っていた）。矢印が1本になったので、
//   その電場が占めていた長さを力に渡す：200 なら既定の置き場所の力 0.27 N が 54px。
//   ★上限は頭打ちの 260px ＝ 1.3 N。試験電荷を ±1C にすると既定の位置で 0.54 N ＝ 108px、
//     固定した電荷のすぐそばでは頭打ちに当たる（そこは「強い」以上を読ませる場所ではない）。
const EF_VS  = 200;

function demoFieldLines() {
  resetDemoWorld();
  setDemoGravity(0);              // ★正面から見た図。地面も重力も出さない
  updateGroundTerrain(false);
  world.sleeping   = false;
  world.substeps   = 8;
  world.coulombOn  = true;
  world.showFieldLines    = true;
  world.showEquipotential = true;
  world.forceVizScale = EF_VS;

  // ★図は説明文（画面の左うえ）の右下へ。**つまみの窓2つに挟まれた帯に収める**ので、
  //   -330 から右へ寄せてある（-330 のままだと右の窓が右の電荷をまるごと覆う）。
  //   窓は左右とも幅 170px で、残る帯は画面 x 540〜840。図の差し渡しは 2×170px＋球の
  //   半径で、倍率 0.62 なら 246px なので、この帯の真ん中に置ける。
  setDemoCam(-180, 0.62);
  const CX = 0, CY = cam.y + 40;

  // ── 固定した電荷2つ。★動かないので、試験電荷から受ける力では姿が変わらない ──
  const src = (sx, q) => {
    const b = new Body({ type:'circle', x:CX + sx*EF_D, y:CY, radius:EF_R,
      charge:q, isStatic:true, fixedRotation:true,
      friction:0, frictionStatic:0, restitution:0,
      label: sx < 0 ? '固定した電荷A' : '固定した電荷B',
      fillColor:'#546e7a', strokeColor:'#b0bec5', strokeWidth:1.5 });
    objects.push(b); return b;
  };
  const left  = src(-1, EF_Q);
  const right = src(+1, -EF_Q);

  // ── 試験電荷。★源から外す（上の★）。重力は世界ごと 0 なので落ちない ──
  //   ★置き場所は図の**下半分**。もとは上半分（CY−250）に置いてあったが、図を右の窓の
  //     ぶんだけ左へ寄せたので、そこは説明文と矢印が重なる場所になった。2つの源は
  //     CY の水平線上にあり重力も 0 なので、上下は**厳密な鏡像**＝上の★の実測
  //     （1tick 目は力の向きと一致・247px で力線から 32px ずれて ⊕ に落ちる）は
  //     そのまま成り立つ。左右を入れ替えたわけではないことに注意（⊕ の側のまま）。
  const probe = new Body({ type:'circle', x:CX - 130, y:CY + 250, radius:EF_TR,
    mass:EF_TM, charge:EF_TQ, fieldSource:false, fixedRotation:true,
    showForces:true,
    friction:0, frictionStatic:0, restitution:0, label:'試験電荷',
    fillColor:'#cfd8dc', strokeColor:'#eceff1', strokeWidth:1.5 });
  objects.push(probe);

  // ── 操作：電気量のつまみ3つ（固定した電荷2つ＋試験電荷）──
  //   ★**窓の左右を電荷の左右に合わせる。** つなぎ線（水色）をたどればどの窓がどれか
  //     は分かるが、線は電気力線の上を横切るので目で追うのに手数が要る。左の電荷の
  //     つまみが画面の左、右の電荷のつまみが画面の右にあれば、その一手が要らない。
  //   ★試験電荷のつまみは左の下。こちらは持ち歩く側で画面上の定位置を持たないので、
  //     左右のどちらに置いても「位置＝相手」にはならない。固定した2つの対を崩さない
  //     高さ（左の列の下）に置いて、上の2つが横並びの対に見えるようにする。
  const knob = (b, lo, hi, fx, fy) => {
    const r = addRemote('prop', b, 'body');
    if (!r) return;
    r.prop = 'charge'; r.lo = lo; r.hi = hi; r.fx = fx; r.fy = fy;
    placeRemotePanel(r); syncRemotePanel(r);
  };
  knob(left,  -EF_QMAX,   EF_QMAX,   0.035, 0.46);
  knob(right, -EF_QMAX,   EF_QMAX,   0.795, 0.46);
  knob(probe, -EF_TQMAX,  EF_TQMAX,  0.035, 0.70);

  // ── 画面 ──
  const ts = demoTextScale(cam.zoom);
  demoLabel(CX - EF_D - 40, CY + EF_R + 34, '固定した電荷A', '#b0bec5', DEMO_NOTE_SIZE * ts, true);
  demoLabel(CX + EF_D - 40, CY + EF_R + 34, '固定した電荷B', '#b0bec5', DEMO_NOTE_SIZE * ts, true);
  // ★電気量はつまみで変わるので、札に数は書かない（書くと回した瞬間に嘘になる）
  demoLabel(CX - 130 + 22, CY + 250 - 16, '試験電荷', '#eceff1', DEMO_NOTE_SIZE * ts, true);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '電場と電気力線', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    '点電荷のまわりの電場を、電気力線（黄）と等電位線（赤・青の細い線）で描いた図。\n'
  + '線は ⊕ から出て ⊖ に入り、本数は電気量に比例する（1C あたり8本）。\n'
  + 'つまり線が混んでいる所ほど電場が強い。等電位線は力線と直交する。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・画面の左右のつまみが、それぞれ左右の固定した電荷。異符号なら双極子、同符号なら\n'
  + '　電場が 0 になる点（小さな丸）ができて線はそこで終わる。0 にすれば単独の放射状\n'
  + '・小さい球が試験電荷。✋つかむ ツール（D）で好きな所へ置いて放す\n'
  + '・黄色い矢印は試験電荷が受ける静電気力。球はいま ⊖ なので、力は電気力線と\n'
  + '　逆向きに出る。つまみを ＋ 側へ回すと裏返って線に沿う＝これが「電気力線の向きは\n'
  + '　⊕ が受ける力の向き」ということ。大きさは電気量に比例する（F = qE）\n'
  + '・放した瞬間は矢印の向きへ動き出すが、走り出すと慣性がついて、道すじは力線から\n'
  + '　ふくらんで外れていく。線は「力の向き」の地図で、「電荷の通り道」ではない',
    DEMO_NOTE_SIZE * ts);

  // ★止めたままでも力の矢印を出す（電気力はソルバが解いた結果なので、一度回さないと出ない）。
  //   試験電荷は釣り合っていないので、回した結果は捨てて姿勢を戻す。
  demoWarmForces(30);
}

// ── ローレンツ力（広い磁場の中の荷電粒子）─────────────────────────
//  ★題材は r = mv/(qB) の4つの量すべて。つまみは**飛んでいる粒子そのもの**（と磁場）に
//    つなぐ。回した瞬間、粒子はその点で前の円に接する新しい円へ乗り換える（位置も速度も
//    連続なので）。古い円は軌跡に残るので、変える前と後が並んで見える。
//    ★生成口＋〈設定変更を出ている物体にも反映〉は使えない：何か1つ触ると速度まで型の値に
//      揃え直すので、質量を変えただけで向きが打ち出したときの向きへ戻る（program.js の★）。
//  ★速さは〈速さ〉のつまみ（向きを保って大きさだけ変える。remote.js の _setBodySpeed）。
//    速度X・Y のつまみでは円運動の途中で速さだけを変えられない。
//  ★場は画面の右（本文の外）に広く取るが、壁では囲わない。半径が大きくなったり q・B を
//    0 にしたりすると粒子は場の外へ出て直進する——それも見せどころ。飛んでいった粒子は
//    ↩戻る で呼び戻す（本文で断る）。
//  ★重力は 0（真上から見た図。質量分析器・電場と電気力線と同じ扱い）。
//  ★粒子は場の中央から上向きに打ち出す。q>0 は右へ曲がる（⊙ の中で時計回り）ので、
//    開いた姿の円は中央から右へ 2r の幅に収まる。電気量の符号を反転しても左へ 2r で、
//    どちらも場の中に収まる（場の半幅 ≥ 2r になるよう既定の r を選んである）。
const LF_M   = 1;      // [kg]  開く姿の質量
const LF_Q   = 1;      // [C]   電気量
const LF_V   = 1;      // [m/s] 速さ
const LF_B   = 1;      // [T]   磁束密度（⊙）。★r = 1·1/(1·1) = 1 m、周期 2πm/(qB) ≈ 6.3 秒。
//   ★1.5 m にしていたときは基準の窓（998×736）で場の半幅 3.4 m に 2r = 3 m がほぼ接し、
//     速度の札が場の右端で切れた。4つとも 1 にそろえると r = mv/(qB) の読みも素直
const LF_MLO = 0.2, LF_MHI = 4;   // [kg] ★質量は 0 にできない（慣性の無い物体は定義できない）
const LF_QMAX = 3;                // [C]  −3〜+3（0 をまたいで向きの反転まで見せる）
const LF_VMAX = 4;                // [m/s]
const LF_BMAX = 2;                // [T]
const LF_R   = 10;     // [px] 粒子の半径
const LF_FVS = 45;     // [px/N]    ★既定の qvB = 1 N が 45px
const LF_VVS = 45;     // [px/(m/s)] ★既定の 1 m/s が 45px（力の矢印と同じ長さで直交する）
const LF_TRACE = 20;   // [s] 軌跡を残す長さ。★周期の約3周ぶん：変える前の円が、変えたあとの円と並んで残る

function demoLorentzForce() {
  resetDemoWorld();
  setDemoGravity(0);              // ★真上から見た図
  updateGroundTerrain(false);
  world.substeps  = 8;
  world.forceVizScale = LF_FVS;
  world.velVizScale   = LF_VVS;

  setDemoCam(0, 0.65);
  // ── 画面の右（本文の外）いっぱいを磁場にする ──
  //   ★本文は幅 500px（基準の窓）。題材は画面 x > 540 に置く約束
  const s = demoFitScale();
  const toWX = sx => cam.x + (sx - canvas.width  / 2) / cam.zoom;
  const toWY = sy => cam.y + (sy - canvas.height / 2) / cam.zoom;
  const fL = toWX(540 * s), fR = toWX(canvas.width - 20 * s);
  // ★上端は操作ヒントの帯（画面の右うえ、高さ約 60px）の下から
  const fT = toWY(70 * s),  fB = toWY(canvas.height - 20 * s);
  const cx = (fL + fR) / 2, cy = (fT + fB) / 2;
  const field = new EMField({ kind:'B', out:true, strength:LF_B,
    x:cx, y:cy, w:fR - fL, h:fB - fT });
  emFields.push(field);

  // ── 荷電粒子。場の中央から上へ ──
  const pt = new Body({ type:'circle', x:cx, y:cy, radius:LF_R,
    mass:LF_M, charge:LF_Q, fixedRotation:true, showForces:true, showVelocity:true,
    friction:0, frictionStatic:0, restitution:0,
    tracerEnabled:true, tracerColor:'#4dd0e1', tracerDuration:LF_TRACE,
    fillColor:'#ffb74d', strokeColor:'#ffffff', strokeWidth:1.5, label:'荷電粒子' });
  pt.vy = -LF_V * M2PX;           // ★内部 y は下向きが正。上へ打つので負
  objects.push(pt);

  // ── 画面 ──
  const ts = demoTextScale(cam.zoom);
  demoLabel(fR - 110 / cam.zoom * s, fB - 40 / cam.zoom * s, '磁場 ⊙', '#a5d6a7', DEMO_NOTE_SIZE * ts, true);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, 'ローレンツ力', DEMO_TITLE_SIZE * ts);
  const NOTE =
      '紙面の裏から表へ向かう磁場の中を、電気を帯びた\n'
    + '粒子が進む。ローレンツ力 F = qvB はいつも速度に\n'
    + '垂直なので、粒子は速さを変えずに円を描く。\n'
    + '半径は r = mv/(qB)。\n'
    + '\n'
    + '【手順】▶実行 を押し、飛んでいる途中につまみを回す\n'
    + '・質量・速さを上げると大きく回る\n'
    + '・電気量・磁場を強くすると小さく回る\n'
    + '・電気量の符号を変えると回る向きが逆になる\n'
    + '・場の外では力がはたらかず、まっすぐ進む\n'
    + '　（上の ↩（一手戻す）で呼び戻す）';
  const noteY = p.y + 54 * ts;
  demoNote(p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);

  // ── つまみ：本文の下に 2×2（質量・速さ／電気量・磁場）──
  //   ★置き方は平行板コンデンサー（回路）と同じ。窓は 170×180px 前後の固定の大きさなので、
  //     本文の下端を実際に測ってそこから詰める。縦が足りない窓では下端に収まるところまで上げる
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  const GAP = 6, RL = 56;           // RL は placeRemotePanel の左端の下限（左の操作ヒントを避ける）
  const put = (r, col, row) => {
    const w = r.panel.offsetWidth || 170, h = r.panel.offsetHeight || 180;
    const top = Math.min(noteBot + GAP, canvas.height - 2 * h - GAP - 4);
    r.fx = (RL + col * (w + GAP)) / canvas.width;
    r.fy = (top + row * (h + GAP)) / canvas.height;
    placeRemotePanel(r); syncRemotePanel(r);
  };
  const knob = (prop, lo, hi, col, row) => {
    const r = addRemote('prop', pt, 'body');
    if (r) { r.prop = prop; r.lo = lo; r.hi = hi; put(r, col, row); }
  };
  knob('mass',   LF_MLO,   LF_MHI,  0, 0);
  knob('speed',  0,        LF_VMAX, 1, 0);
  knob('charge', -LF_QMAX, LF_QMAX, 0, 1);
  const rb = addRemote('prop', field, 'emfield');
  if (rb) { rb.prop = 'strength'; rb.lo = 0; rb.hi = LF_BMAX; put(rb, 1, 1); }
}

// ── 質量分析器（ローレンツ力で質量を分ける）─────────────────────────────────
//  ★打ち出しは〈生成口＋「キーを押した瞬間」に生成するプログラム〉、質量は生成口に
//    つないだつまみ（リモコン）。どちらも手で置ける部品で、デモ専用の仕掛けは無い。
//    出てきた球は生成口の値の写しなので、つまみを回すと**次に打つ球から**質量が変わる
//    （〈設定変更を出ている物体にも反映〉は入れない。入れると着いた球まで一斉に
//    新しい質量へ書き換わり、「質量ごとに着く場所が分かれる」が消える）。
//  ★打ち出しは「同じ速さ」で揃える（生成口の速度がそのまま入る）。これで r = mv/(qB) が
//    m に比例し、検出板の目盛りが等間隔になる。
//    ★「同じ力を同じ時間かける」（動力を押している間だけ効かせる）で打つのは不可：
//      v = Ft/m なので mv = Ft が質量によらず、**どの質量も同じ半径**を描いて選別できない。
//    ★「同じ電圧で加速する」（電場の領域で qV = ½mv²）なら r = √(2mV/q)/B ∝ √m で、
//      こちらが本物の質量分析器に近い。ただ目盛りが √ で詰まるので、ローレンツ力の
//      単元では「速さを揃えた」ほうを採った（本文の最後の行で断る）。
//  ★磁場の下端は検出板の上面から球の半径ぶん上に置く。場は重心の位置で効くので、
//    こうすると重心が場を出る高さ＝球が板に触れる高さになり、着く点がちょうど 2r になる。
//  ★重力は 0（真上から見た図。電場と電気力線のデモと同じ扱い）。球どうしのクーロン力も
//    切る：入れると板に着いた球が次の球を押し、着く場所が質量で決まらなくなる。
//  ★検出板と球の摩擦は 1（合成は積なので**両方**に要る。球を 0 にしていたときは板の
//    1 が効かず、着いた球が板の上を這い続けた）。重力が無いので、着いたあとに残る
//    わずかな横すべり（出る角度がサブステップで刻まれるぶん。1.5kg で 0.54 px/s）を
//    止めるものがほかに無い（板に「焼き付く」写真乾板の役）。飛んでいる間は何にも
//    触れないので、半円には効かない。
const MS_Q   = 2;      // [C]  球の電気量
const MS_B   = 2;      // [T]  磁束密度（⊙ 紙面から出る向き → 上向きの ⊕ は右へ曲がる）
const MS_V   = 2;      // [m/s] 打ち出す速さ。★r = m·2/(2·2) = 0.5 m/kg → 2r = 1 m/kg
const MS_M   = 1;      // [kg] 開く姿の質量
const MS_MLO = 1, MS_MHI = 4;   // [kg] つまみの幅。★4kg で 2r = 4 m ＝ 板の右端の手前
const MS_R   = 10;     // [px] 球の半径
const MS_SLIT= 30;     // [px] 入口のすき間（球の直径＋10px）
const MS_FVS = 8;      // [px/N] 力の矢印。★qvB = 8 N が 64px
// [px] 磁場の下端と「板に着いた球の重心」のすき間。★0 だと着いた球の重心が場の縁
//   ちょうど（contains は縁を含む）に乗り、残ったわずかな速さが場で回されて板の上を
//   這い続けた（実測：1kg で 600tick 後も 0.017 m/s、着地点から 14cm 流れた）。
const MS_GAP = 2;

function demoMassSpectrometer() {
  resetDemoWorld();
  setDemoGravity(0);              // ★真上から見た図
  updateGroundTerrain(false);
  world.coulombOn = false;        // ★上の★（着いた球が次の球を押さない）
  world.substeps  = 8;
  world.forceVizScale = MS_FVS;

  const Z = 0.85;
  const XS = 100;                 // [px] 入口のすき間の中心（★題材を x=0 にまたがせない）
  setDemoCam(XS - (590 - DEMO_REF_W / 2) / Z, Z);
  const PY = cam.y + (480 - DEMO_REF_H / 2) / Z;   // 検出板の上面
  const perKg = 2 * MS_V / (MS_Q * MS_B) * M2PX;   // [px/kg] 2r の伸び
  const XR = XS + perKg * MS_MHI + 60;             // 板の右端

  // ── 磁場（⊙）。★下端は板の上面から球の半径ぶん上（上の★）──
  const fTop = PY - MS_R - (perKg * MS_MHI / 2 + 30);
  const fBot = PY - MS_R - MS_GAP, fL = XS - 40;
  emFields.push(new EMField({ kind:'B', out:true, strength:MS_B,
    x:(fL + XR) / 2, y:(fTop + fBot) / 2, w:XR - fL, h:fBot - fTop }));

  // ── 検出板（入口のすき間を挟んで左右2枚）──
  const plate = (x1, x2, label) => objects.push(new Body({ type:'box',
    x:(x1 + x2) / 2, y:PY + 8, w:x2 - x1, h:16, isStatic:true,
    friction:1, frictionStatic:1, restitution:0, label,
    fillColor:'#546e7a', strokeColor:'#b0bec5', strokeWidth:1.5 }));
  plate(fL - 20, XS - MS_SLIT / 2, '入口の板');
  plate(XS + MS_SLIT / 2, XR, '検出板');

  // ── 生成口（打ち出し口）。出てくる球が持つ値をここに持たせる ──
  const gun = new Body({ type:'circle', x:XS, y:PY + 80, radius:MS_R,
    mass:MS_M, charge:MS_Q, fixedRotation:true, showForces:true,
    friction:1, frictionStatic:1, restitution:0, isSpawner:true,   // ★摩擦は下の★
    tracerEnabled:true, tracerColor:'#4dd0e1', tracerDuration:600,
    fillColor:'#ffb74d', strokeColor:'#ffffff', strokeWidth:1.5, label:'打ち出し口' });
  gun.vy = -MS_V * M2PX;          // ★内部 y は下向きが正。上へ打つので負
  objects.push(gun);

  // ── 操作：Enter で1発（プログラム）と、質量のつまみ（リモコン）──
  const pg = addProgram(gun);
  if (pg) {
    Object.assign(pg, { trigger:'key', key:'Enter', action:'create', limit:30 });
    pg.reset(); syncProgramState(pg);
    // ★畳んでつまみの下へ。開いたままだと 300px の丈でつまみの窓に重なる
    pg.collapsed = true; pg.fx = 0.035; pg.fy = 0.84;
    syncProgramPanel(pg); placeProgramPanel(pg);
  }
  const r = addRemote('prop', gun, 'body');
  if (r) {
    r.prop = 'mass'; r.lo = MS_MLO; r.hi = MS_MHI; r.fx = 0.035; r.fy = 0.58;
    placeRemotePanel(r); syncRemotePanel(r);
  }

  // ── 画面 ──
  const ts = demoTextScale(cam.zoom);
  // 検出板の質量の目盛り（2r ∝ m なので等間隔）
  for (let m = MS_MLO; m <= MS_MHI; m++) {
    const x = XS + perKg * m;
    demoDashedPath(x, PY + 16, x, PY + 30, '#eceff1', 2, 3, 2);
    demoLabel(x - 22, PY + 36, m + ' kg', '#eceff1', DEMO_NOTE_SIZE * ts * 0.85, true);
  }
  demoLabel(XS - 110, PY + 70, '打ち出し口', '#ffcc80', DEMO_NOTE_SIZE * ts * 0.85, true);
  demoLabel(XR - 140, fTop - 30, '磁場 ⊙', '#a5d6a7', DEMO_NOTE_SIZE * ts, true);
  const p = demoTextTopLeft();
  demoTitle(p.x, p.y, '質量分析器', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, p.y + 54 * ts,
    '電気を帯びた球を、下の入口から同じ速さで磁場へ打ち出す。\n'
  + '磁場の中ではローレンツ力 F = qvB がいつも速度に垂直に\n'
  + 'はたらくので、球は等速円運動をして半円を描く。\n'
  + '半径は r = mv/(qB)。q・v・B が同じなら重い球ほど大きく回る。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・Enter キー（または左下の窓の ▶実行）で球を1つ打ち出す\n'
  + '・〈質量〉のつまみを回してから、また Enter で打つ\n'
  + '・球は検出板の、入口から 2r の所に着く＝目盛りが質量\n'
  + '・矢印はローレンツ力。大きさ qvB は質量によらず同じで、\n'
  + '　重い球ほど曲がりにくい（a = F/m）\n'
  + '・実際の装置では、打ち出す前に速さをそろえておく',
    DEMO_NOTE_SIZE * ts);
}

// ── 速度選択器（直交する電場と磁場）─────────────────────────────
//  平行板のあいだに上向きの電場 E と ⊙ の磁場 B を重ねる。右へ進む正の粒子は電場から
//  上向きに qE、磁場から下向きに qvB を受け、qE ＝ qvB すなわち v ＝ E/B の粒子だけが
//  まっすぐ抜けて出口のスリットを通る。遅い粒子は上へ（電場が勝つ）、速い粒子は下へ曲がる。
//  ★打ち出しは質量分析器と同じ〈生成口＋Enter で1発のプログラム〉と、生成口の〈速さ〉のつまみ。
//    出てくる球は生成口の値の写しなので、つまみは次に打つ球から効く＝打ち比べられる。
//  ★電気量・質量には寄らない（qE ＝ qvB の両辺に q、m は出てこない）。本文では言うだけにし、
//    つまみは v・E・B の3つにしぼる（質量のつまみを足すと「質量で選別される」と誤読されやすい）。
//  ★重力は 0（真上から見た図）。球どうしのクーロン力も切る（着いた球が次の球を押さないように。
//    質量分析器と同じ）。球と板の摩擦は 1・反発 0（着いたところに止まる。写真乾板の役）。
//  ★値：E ＝ 2V/m・B ＝ 1T → 通る速さ 2m/s。極板の長さ 3m・間隔 1m、スリットの幅は球の直径＋12px。
//    速さが 2 から ±0.1m/s ずれると、極板を出るまでに ±0.1m 曲がってスリットの壁に当たる
//    （横ずれ ≈ ½·(qE − qvB)/m·(L/v)²）。
const VS_Q = 1, VS_M = 1;            // [C]・[kg]
const VS_E = 2;                      // [V/m] 電場（上向き）
const VS_B = 1;                      // [T]   磁場（⊙）
const VS_V = 2;                      // [m/s] 打ち出す速さ（開く姿は通る速さ）
const VS_L = 300, VS_GAP = 100;      // [px]  極板の長さ・間隔
const VS_R = 6;                      // [px]  球の半径
const VS_SLIT = 2 * VS_R + 12;       // [px]  スリットの幅
const VS_VMAX = 4, VS_EMAX = 4, VS_BMAX = 2;   // つまみの上限（下限はどれも 0）
const VS_FVS = 30;                   // [px/N] 力の矢印。★qE ＝ 2N が 60px
function demoVelocitySelector() {
  resetDemoWorld();
  setDemoGravity(0);              // ★真上から見た図
  updateGroundTerrain(false);
  world.coulombOn = false;
  world.substeps  = 8;
  world.forceVizScale = VS_FVS;

  setDemoCam(900, 0.9);           // ★座標軸（世界の x=0・y=0）を画面の外へ出す
  cam.y -= 400;
  const s = demoFitScale();
  const toWX = sx => cam.x + (sx - canvas.width  / 2) / cam.zoom;
  const toWY = sy => cam.y + (sy - canvas.height / 2) / cam.zoom;
  // ★題材は画面 x > 540（本文の外）。打ち出し口 → 極板 → スリット → 検出板 を横一列に
  const X0 = toWX(600 * s);                  // 極板の左端
  const X1 = X0 + VS_L;                      // 極板の右端
  const XS = X1 + 40;                        // スリットの壁
  const XD = XS + 90;                        // 検出板
  const YC = toWY(250 * s);                  // 中心線
  const YT = YC - VS_GAP / 2, YB = YC + VS_GAP / 2;
  // ── 場：極板のあいだに電場（上向き）と磁場（⊙）を重ねる ──
  const fE = new EMField({ kind:'E', strength:VS_E, angle:-Math.PI / 2,
    x:(X0 + X1) / 2, y:YC, w:VS_L, h:VS_GAP });
  // ★磁場は極板の外まで上下に 30px ずつ高くする。同じ矩形だと左上の角の札（E = 2 V/m と
  //   B = 1 T）が重なった。極板の外側には粒子は行かないので効き方は変わらない
  const fB = new EMField({ kind:'B', out:true, strength:VS_B,
    x:(X0 + X1) / 2, y:YC, w:VS_L, h:VS_GAP + 60 });
  emFields.push(fE, fB);
  // ── 極板（上＝−、下＝＋ で電場が上向き）・スリットの壁・検出板 ──
  const wall = (x, y, w, h, label, fill) => objects.push(new Body({ type:'box', x, y, w, h,
    isStatic:true, friction:1, frictionStatic:1, restitution:0, label,
    fillColor:fill || '#546e7a', strokeColor:'#b0bec5', strokeWidth:1.5 }));
  wall((X0 + X1) / 2, YT - 5, VS_L, 10, '上の極板（−）', '#5c6bc0');
  wall((X0 + X1) / 2, YB + 5, VS_L, 10, '下の極板（＋）', '#e57373');
  const WH = 120;                            // 壁の片側の高さ
  wall(XS, YC - VS_SLIT / 2 - WH / 2, 10, WH, 'スリット');
  wall(XS, YC + VS_SLIT / 2 + WH / 2, 10, WH, 'スリット');
  wall(XD, YC, 10, VS_GAP + 60, '検出板');

  // ── 打ち出し口（生成口）。出てくる球の値をここに持たせる ──
  const gun = new Body({ type:'circle', x:X0 - 40, y:YC, radius:VS_R,
    mass:VS_M, charge:VS_Q, fixedRotation:true, showForces:true,
    friction:1, frictionStatic:1, restitution:0, isSpawner:true,
    tracerEnabled:true, tracerColor:'#4dd0e1', tracerDuration:600,
    fillColor:'#ffb74d', strokeColor:'#ffffff', strokeWidth:1.5, label:'打ち出し口' });
  gun.vx = VS_V * M2PX;
  objects.push(gun);

  // ── 画面 ──
  const ts = demoTextScale(cam.zoom);
  const LS = DEMO_NOTE_SIZE * ts * 0.85;
  demoLabel(XS - 30, YC + VS_SLIT / 2 + WH + 10 * ts, 'スリット', '#eceff1', LS, true);
  demoLabel(XD - 40, YC + VS_GAP / 2 + 40 * ts, '検出板', '#eceff1', LS, true);
  demoLabel(X0 - 90, YC + 30 * ts, '打ち出し口', '#ffcc80', LS, true);
  const p = demoTextTopLeft();
  const NOTE =
      '平行板のあいだに、上向きの電場 E と、紙面の\n'
    + '裏から表へ向かう磁場 B を重ねてある。\n'
    + '右へ進む正の粒子は、電場から上向きに qE、\n'
    + '磁場から下向きに qvB の力を受ける。\n'
    + 'qE ＝ qvB のとき、つまり v ＝ E／B の粒子だけが\n'
    + 'まっすぐ進んでスリットを通る（速度選択器）。\n'
    + '\n'
    + '【手順】▶実行 を押す\n'
    + '・Enter キーで粒子を1つ打ち出す\n'
    + '・〈速さ〉を変えてまた打つ。遅いと上へ、\n'
    + '　速いと下へ曲がって壁に当たる\n'
    + '・E や B を変えると、通る速さが変わる\n'
    + '・電気量や質量によらず、速さだけで選ばれる';
  const noteY = p.y + 54 * ts;
  demoNote(p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
  demoTitle(p.x, p.y, '速度選択器', DEMO_TITLE_SIZE * ts);

  // ── 操作：本文の下に つまみ3枚（速さ・電場・磁場）を横1列、その下に Enter の窓 ──
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  const rv = addRemote('prop', gun, 'body');
  if (rv) { rv.prop = 'speed'; rv.lo = 0; rv.hi = VS_VMAX; }
  const re = addRemote('prop', fE, 'emfield');
  if (re) { re.prop = 'strength'; re.lo = 0; re.hi = VS_EMAX; }
  const rb = addRemote('prop', fB, 'emfield');
  if (rb) { rb.prop = 'strength'; rb.lo = 0; rb.hi = VS_BMAX; }
  const row = [rv, re, rb].filter(Boolean);
  const h = Math.max(0, ...row.map(r => r.panel.offsetHeight || 180));
  const top = Math.min(noteBot + 6, canvas.height - h - 60);
  dcPlaceRow(row, 56, top);
  const pg = addProgram(gun);
  if (pg) {
    Object.assign(pg, { trigger:'key', key:'Enter', action:'create', limit:30 });
    pg.reset(); syncProgramState(pg);
    pg.collapsed = true;
    pg.fx = 56 / canvas.width; pg.fy = (top + h + 8) / canvas.height;
    syncProgramPanel(pg); placeProgramPanel(pg);
  }
}

// ── サイクロトロン ─────────────────────────────────────────────
//  左右2つの D 字形の磁場（⊙）と、そのあいだのすき間の交流の電場（横向き）。粒子は D の中で
//  半円を描き、すき間を渡るたびに電場で加速される。磁場の中の周期 T ＝ 2πm/(qB) は速さに
//  よらないので、電場の振動数を f ＝ qB/(2πm) に合わせておけば、毎回ちょうど加速の向きの
//  ときにすき間へ戻ってくる。半径 r ＝ mv/(qB) が1回ごとに大きくなり、渦巻きになる。
//  ★部品はどれも手で置ける：磁場の領域2つ・電場の領域1つ（右パネルの振動数＝EMField.freq）・
//    円の物体1つ。D の形は矩形の領域で代用（半円の軌道は矩形の中に収まるので、効き方は同じ）。
//  ★値：q ＝ 1C・m ＝ 1kg・B ＝ π T → T ＝ 2秒、f ＝ 0.5Hz。すき間 0.1m・E ＝ 20V/m で
//    1回に最大 qEd ＝ 2J 増える。D の半径 2.5m（出るときの速さ qBR/m ≈ 7.85m/s）。
//    ★B を π にしたのは、振動数のつまみ（0.01Hz 刻み）で共鳴がきりのよい 0.50 に来るように。
//      B のつまみ（0.05T 刻み）に触れると 3.15T に丸まるが、f は 0.501Hz で、ずれは1周 1°未満。
//  ★すき間は狭く（0.1m）・電場は強く。1回まわる時間は「半円 T/2 ×2 ＋ すき間を渡る時間」なので、
//    振動数を f ＝ qB/(2πm) に合わせても、渡るたびに位相が d/(πr) 周期ぶんずつ遅れる。
//    すき間 0.3m・E ＝ 6V/m（qEd ＝ 1.8J）では遅れが積もって、8秒（3.84m/s・半径 1.39m）で
//    減速に転じ、外へ出なかった。0.1m・20V/m にして外まで届いた。
//  ★実測（サブステップ8。電場の初めの位相 0）：
//      f ＝ 0.50Hz … 17.5秒・すき間を16回渡って 7.75m/s で D の外へ出る（上限 qBR/m ＝ 7.85）
//                   1回ごとの増え方は 0.47〜1.82J（最大 qEd ＝ 2J。遅れのぶん減る）
//      f ＝ 0.48Hz … 4.98m/s で頭打ちになり減速、60秒たっても外へ出ない（0.45Hz では 1.8m/s 止まり）
//      f ＝ 0.55Hz … 4.08m/s で頭打ち、60秒たっても出ない
//    ずらすと加速が止まる、が対照として見える。
//  ★重力 0（真上から見た図）。
const CY_Q = 1, CY_M = 1;            // [C]・[kg]
const CY_B = Math.PI;                // [T]  ★f ＝ qB/(2πm) ＝ 0.5Hz
const CY_F = 0.5;                    // [Hz] 電場の振動数（共鳴）
const CY_E = 20;                     // [V/m] 電場の振幅
const CY_RD = 250;                   // [px] D の半径（2.5m）
const CY_GAP = 10;                   // [px] すき間（0.1m）
const CY_R = 7;                      // [px] 粒子の半径
const CY_GAP_EXT = 30;               // [px] すき間の領域を D より上下に伸ばす長さ（札をずらすため）
const CY_FMAX = 1, CY_BMAX = 5, CY_EMAX = 40;   // つまみの上限（下限はどれも 0）
function demoCyclotron() {
  resetDemoWorld();
  setDemoGravity(0);              // ★真上から見た図
  updateGroundTerrain(false);
  world.substeps = 8;

  setDemoCam(900, 0.72);           // ★座標軸（世界の x=0・y=0）を画面の外へ出す（速度選択器と同じ）
  cam.y -= 400;
  const s = demoFitScale();
  const toWX = sx => cam.x + (sx - canvas.width  / 2) / cam.zoom;
  const toWY = sy => cam.y + (sy - canvas.height / 2) / cam.zoom;
  // ★題材は画面 x > 540。D の外形（幅 2R＋すき間）を本文の右の空きの中央へ
  const CX = toWX(790 * s), CY = toWY(330 * s);
  const H = 2 * CY_RD, W = CY_RD;
  const dL = new EMField({ kind:'B', out:true, strength:CY_B,
    x:CX - CY_GAP / 2 - W / 2, y:CY, w:W, h:H });
  const dR = new EMField({ kind:'B', out:true, strength:CY_B,
    x:CX + CY_GAP / 2 + W / 2, y:CY, w:W, h:H });
  // ★すき間の領域は D より上下に CY_GAP_EXT ずつ長い。領域の札は左上の角に出るので、
  //   D と同じ高さだとすき間の札（E = 20 V/m · 0.5 Hz）が D₂ の札（B = 3.142 T）に重なった。
  //   はみ出した部分に粒子が入るのは、最後に D の上下の縁から出ていくときだけ（1回かすめるだけ）
  const gap = new EMField({ kind:'E', strength:CY_E, angle:0, freq:CY_F,
    x:CX, y:CY, w:CY_GAP, h:H + 2 * CY_GAP_EXT });
  emFields.push(dL, dR, gap);

  const pt = new Body({ type:'circle', x:CX, y:CY, radius:CY_R,
    mass:CY_M, charge:CY_Q, fixedRotation:true, showVelocity:true,
    friction:0, frictionStatic:0, restitution:0,
    tracerEnabled:true, tracerColor:'#4dd0e1', tracerDuration:120,
    fillColor:'#ffb74d', strokeColor:'#ffffff', strokeWidth:1.5, label:'荷電粒子' });
  objects.push(pt);
  world.velVizScale = 12;         // [px/(m/s)] ★出るときの 7.9m/s が 95px

  // ── 画面 ──
  const ts = demoTextScale(cam.zoom);
  const LS = DEMO_NOTE_SIZE * ts;
  // ★D の札は下の縁の外（上の縁の外は領域の札が並ぶ）
  demoLabel(dL.x - 15, CY + CY_RD + 8 * ts, 'D₁', '#a5d6a7', LS, true);
  demoLabel(dR.x - 15, CY + CY_RD + 8 * ts, 'D₂', '#a5d6a7', LS, true);
  const p = demoTextTopLeft();
  const NOTE =
      '左右の D 字形の電極の中は磁場（紙面の裏から表）、\n'
    + 'あいだのすき間には交流の電場がかかっている。\n'
    + '粒子は D の中で半円を描き、すき間を渡るたびに\n'
    + '電場で加速されて、半径 r ＝ mv／qB が大きくなる。\n'
    + '半円にかかる時間 πm／qB は速さによらないので、\n'
    + '電場の振動数を f ＝ qB／2πm に合わせておけば\n'
    + 'いつも加速の向きのときに戻ってくる。\n'
    + '\n'
    + '【手順】▶実行 を押す\n'
    + '・グラフの速さは、すき間を渡るたびに段になって上がる\n'
    + '・振動数を少しずらすと加速が止まり、減速もする\n'
    + '・B を変えたら、振動数も合わせ直す\n'
    + '・外へ飛び出したら ↩（一手戻す）で呼び戻す';
  const noteY = p.y + 54 * ts;
  demoNote(p.x, noteY, NOTE, LS);
  demoTitle(p.x, p.y, 'サイクロトロン', DEMO_TITLE_SIZE * ts);

  // ── つまみ：本文の下に 振動数・B・E を横1列。グラフはその下 ──
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, LS));
  const rf = addRemote('prop', gap, 'emfield');
  if (rf) { rf.prop = 'freq'; rf.lo = 0; rf.hi = CY_FMAX; }
  // ★B のつまみは1台で D₁・D₂ の両方を受け持つ（窓の〈＋〉で相手を足したのと同じ）
  const rb = addRemote('prop', dL, 'emfield', [dL.id, dR.id]);
  if (rb) { rb.prop = 'strength'; rb.lo = 0; rb.hi = CY_BMAX; }
  const re = addRemote('prop', gap, 'emfield');
  if (re) { re.prop = 'strength'; re.lo = 0; re.hi = CY_EMAX; }
  const row = [rf, rb, re].filter(Boolean);
  dcPlaceRow(row, 56, noteBot + 6);
  const remBot = Math.max(0, ...row.map(r => r.panel.offsetTop + r.panel.offsetHeight));
  const g = velGraphNew(pt, { showPos:false, showVel:true, showAcc:false,
                              showX:false, showY:false, showMag:true });
  if (g) {
    const EDGE = 10;
    const dLeft = (CX - CY_RD - CY_GAP / 2 - cam.x) * cam.zoom + canvas.width / 2;   // D₁ の左端（画面 px）
    sizeDemoGraph(g, Math.min(560, dLeft - 2 * EDGE), canvas.height - remBot - 2 * EDGE);
    g.panel.style.left = EDGE + 'px'; g.panel.style.right = 'auto';
    moveDemoGraphBottom(g);
  }
}

// ── 導体棒に生じる誘導起電力（電源なし・一定の力で引く）─────────────────
//  磁場の中の2本のレール（導線）に導体棒を渡し、レールの左端を抵抗でつなぐ。電源は無い。
//  棒に動力（一定の力 F）を付けて右へ引き続けると、誘導起電力 vBL → 電流 I = vBL/R →
//  電磁力 IBL（運動を妨げる向き）が速さに比例して育ち、加速度が落ちて終端速度
//  v = FR/(BL)² の等速直線運動に近づく。運動方程式は m·dv/dt = F − (BL)²v/R なので
//  v(t) = v_t(1 − e^(−t/τ))、τ = mR/(BL)²。
//  ★組み立てはすべて手で置ける部品：導線2本（レール）・抵抗・導体棒ツールの棒・動力・
//    磁場の領域。BLv → 回路 → F=BIL の連成はエンジン側（js/em/circuit.js の
//    buildConductorRods / applyRodForces）がそのまま受け持つ。デモ専用の仕掛けは無い。
//  ★R は抵抗器と棒の内部抵抗（ROD_RESISTANCE = 0.5Ω、UI に出ない）の和。抵抗器を 1.5Ω に
//    して回路全体を 2Ω にそろえ、本文でも「棒自身の抵抗も含む」と断る。
//  ★値は B=1T・L=2m・R=2Ω・m=4kg・F=1N：(BL)²/R = 2 で v_t = 0.5 m/s、τ = 2 秒、
//    終端での電流 0.5A・電磁力 1N（＝動力）。16秒ほどで右端の車止めに着く。
//    ★L を 2m にしたのは倍率 0.5 でもレールの間隔が画面 100px 取れるようにするため。
//  ★実測（乱数を使わない題材なので1試行で決まる。サブステップ4）：
//      t = 1 / 2 / 4 / 10 秒 … v = 0.1965 / 0.3156 / 0.4316 / 0.4956 m/s
//      理論 0.5(1 − e^(−t/2))  … 0.1967 / 0.3161 / 0.4323 / 0.4966（ずれ 0.3% 以内。
//      デモの配置のまま 15 秒で 0.4987（理論 0.4997）。16 秒ほどで車止めに着いて止まる）
//      10 秒で電流 0.2483 A（理論 vBL/R = 0.2478）。磁場を ⊗ にしても、棒を
//      動きの制限（レール）に乗せても同じ速さ（電流の符号だけが反転）。
//  ★摩擦は 0（重力も 0 ＝真上から見た図なので、そもそも押しつける力が無い）。
//  ★動きの制限は付けない。力は動力も電磁力もレール方向だけなので要らず、付けると
//    水平のガイド線がレール（導線）に重なって描かれる。
//  ★装置（レール・磁場・棒・車止め・グラフ・つまみの置き方）は電源ありの版と
//    _irBuild で共有する。2つのデモの違いは左の辺（抵抗だけ／電源＋抵抗）と、
//    棒に動力を付けるかどうかだけ＝見比べたときに違いがそこにしか無いようにする。
const IR_B   = 1;      // [T]   磁束密度（⊙）
const IR_L   = 200;    // [px]  レールの間隔（2 m）
const IR_R   = 1.5;    // [Ω]   抵抗器。★棒の 0.5Ω と合わせて 2Ω
const IR_M   = 4;      // [kg]  棒の質量
const IR_F   = 1;      // [N]   動力
const IR_FMAX = 2, IR_BMAX = 2, IR_RMAX = 5;   // つまみの上限（下限はどれも 0）
const IR_FVS = 60;     // [px/N] 力の矢印。★動力 1 N が 60px

// 左の辺を leftSide(add, X0, YT, YM, YB) に組ませ、残りの装置を置く。
//   thrust：棒に付ける動力 [N]（0 なら付けない）。戻り値は rod・field と画面の換算
function _irBuild(leftSide, thrust) {
  resetDemoWorld();
  setDemoGravity(0);              // ★真上から見た図
  updateGroundTerrain(false);
  world.forceVizScale = IR_FVS;
  setDemoCam(1500, 0.5);
  cam.y -= 800;                   // ★座標軸（世界 x=0・y=0）を画面の外へ。目盛りの札がレールに重なる
  const s = demoFitScale();
  const ts = demoTextScale(cam.zoom);
  const toWX = sx => cam.x + (sx - canvas.width  / 2) / cam.zoom;
  const toWY = sy => cam.y + (sy - canvas.height / 2) / cam.zoom;
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const add = (type, ax, ay, bx, by, o) => {
    const e = new CircuitElement(type, ax, ay, bx, by);
    Object.assign(e, o || {});
    circuitElements.push(e);
    return e;
  };

  // ── レールと左の辺。本文の右（画面 x > 540）、右うえのグラフの下 ──
  const X0 = toWX(565 * s), X1 = toWX(canvas.width - 25 * s);
  const YM = toWY(545 * s), YT = YM - IR_L / 2, YB = YM + IR_L / 2;
  add('wire', X0, YT, X1, YT);
  add('wire', X0, YB, X1, YB);
  const parts = leftSide(add, X0, YT, YM, YB);

  // ── 磁場（⊙）。レールと棒の走る範囲をまるごと覆う ──
  const PAD = 70;
  const field = new EMField({ kind:'B', out:true, strength:IR_B,
    x:(X0 + X1) / 2, y:YM, w:(X1 - X0) + 2 * PAD, h:IR_L + 2 * PAD });
  emFields.push(field);

  // ── 導体棒（導体棒ツールと同じ作り）。左端から 1m のところ、レールから少しはみ出す ──
  //   ★棒の角度は +90°（上→下に引いた線）。動力の向きは物体基準なので −90° で右向きになる
  const RX = X0 + 100, OVER = 15;
  const m = MATERIALS['金属'];
  const rod = new Body({ ...condRodDesc({ x:RX, y:YT - OVER }, { x:RX, y:YB + OVER }),
    conductor:true, fixedRotation:true,
    friction:0, frictionStatic:0, restitution:0,
    fillColor:m.fillColor, strokeColor:'#eceff1', strokeWidth:1.5,
    showForces:true, label:'導体棒',
    thrusters: thrust ? [{ force:thrust, dir:-Math.PI / 2 }] : [] });
  rod.setMass(IR_M);
  rod.density = rod.mass / Math.max(rod.areaM2() * world.depth, 1e-9);
  objects.push(rod);

  // ── 車止め。レールの右端の手前 ──
  objects.push(new Body({ type:'box', x:X1 - 20, y:YM, w:14, h:IR_L + 2 * OVER + 20,
    isStatic:true, friction:0, frictionStatic:0, restitution:0,
    fillColor:'#546e7a', strokeColor:'#90a4ae', strokeWidth:1.5, label:'車止め' }));

  // ── グラフ：棒の速度と加速度（x 成分だけ）。右うえ ──
  //   ★実行と同時に記録する（autoStart）。出だしの加速度 0.25 m/s²（どちらの版も）は記録開始の
  //     しきい値 VG_START_TOL（0.9 m/s²）に届かず、既定のままでは待機から抜けない（実測）
  const g = velGraphNew(rod, { showPos:false, showVel:true, showAcc:true,
                               showX:true, showY:false, showMag:false,
                               autoStart:true });
  sizeDemoGraph(g, 400, 300);
  moveDemoGraphTop(g);
  demoLabel(X1 - 110, YB + PAD - 20, '磁場 ⊙', '#a5d6a7', DEMO_NOTE_SIZE * ts, true);

  // 本文とつまみ。つまみは本文の下（上の段に2つ、下の段の右に1つ）。置き方はローレンツ力のデモと同じ。
  //   knobs は [相手, 種類, 量, 上限] を3つ。★3つ目（下の段の右）は抵抗に近い側。左下は力の矢印の凡例
  const text = (title, NOTE, knobs) => {
    const p = demoTextTopLeft();
    demoTitle(p.x, p.y, title, DEMO_TITLE_SIZE * ts);
    const noteY = p.y + 54 * ts;
    demoNote(p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
    const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
    const GAP = 6, RL = 56;
    const put = (r, col, row) => {
      const w = r.panel.offsetWidth || 170, h = r.panel.offsetHeight || 180;
      const top = Math.min(noteBot + GAP, canvas.height - 2 * h - GAP - 4);
      r.fx = (RL + col * (w + GAP)) / canvas.width;
      r.fy = (top + row * (h + GAP)) / canvas.height;
      placeRemotePanel(r); syncRemotePanel(r);
    };
    const cells = [[0, 0], [1, 0], [1, 1]];
    knobs.forEach(([target, type, prop, hi], k) => {
      const r = addRemote('prop', target, type);
      if (r) { r.prop = prop; r.lo = 0; r.hi = hi; put(r, cells[k][0], cells[k][1]); }
    });
  };
  return { rod, field, parts, text };
}

function demoInducedEmfRod() {
  const { rod, field, parts, text } = _irBuild((add, X0, YT, YM, YB) => {
    const RH = 40;                                // [px] 抵抗器の半分の長さ
    add('wire', X0, YT, X0, YM - RH);
    const res = add('resistor', X0, YM - RH, X0, YM + RH, { R: IR_R });
    add('wire', X0, YM + RH, X0, YB);
    addCircTable(res.id, 0, 125);   // ★抵抗の真下・磁場の外。レールの内側に置くと走り出す前の棒に重なる
    return { res };
  }, IR_F);
  text('導体棒に生じる誘導起電力',
      '紙面の裏から表へ向かう磁場の中で、2本のレールに\n'
    + '導体棒を渡し、レールの左端を抵抗でつなぐ（電源はない）。\n'
    + '棒を動力で、一定の力 F で右へ引き続ける。\n'
    + '\n'
    + '棒が速さ v で動くと誘導起電力 vBL が生じ、\n'
    + '電流 I = vBL/R が流れる。この電流が磁場から受ける力\n'
    + 'IBL は運動を妨げる向き（レンツの法則）。速くなるほど\n'
    + '妨げる力が強まり、加速度は小さくなっていく。\n'
    + 'F = IBL になると等速直線運動：v = FR/(BL)²\n'
    + '（R は回路全体の抵抗。棒自身の抵抗も含む）\n'
    + '\n'
    + '【手順】▶実行 を押し、右うえのグラフを見る\n'
    + '・速度：傾きがだんだん緩やかになり、一定の値に近づく\n'
    + '・加速度：だんだん 0 に近づく\n'
    + '・棒の矢印：動力と、逆向きの電磁力が同じ長さになる\n'
    + '・つまみで F・B・R を変えると、落ち着く速さが変わる',
    [[rod.thrusters[0], 'thruster', 'force',    IR_FMAX],
     [field,            'emfield',  'strength', IR_BMAX],
     [parts.res,        'circuit',  'R',        IR_RMAX]]);
}

// ── 導体棒に生じる誘導起電力（電源あり・外力なし）─────────────────────
//  上と同じ装置で、左の辺を「電源 E ＋ 抵抗」にし、棒の動力を外す。
//  電源の電流が棒に電磁力 IBL を与えて右へ走らせる。走り出すと誘導起電力 vBL が電源と
//  逆向きに立つので、電流 I = (E − vBL)/R が減り、力も減る。vBL = E で電流も力も 0 になり、
//  等速直線運動 v = E/(BL)。運動方程式 m·dv/dt = (E − vBL)BL/R なので
//  v(t) = v_t(1 − e^(−t/τ))、τ = mR/(BL)²（電源なしの版と同じ形・同じ τ）。
//  ★終端速度は R によらない（R は近づく速さ τ だけを変える）。電源なしの版では v_t ∝ R なので、
//    つまみの R を回したときの効き方が2つの版で違う＝ここが見比べどころ。本文にもそう書く。
//  ★値は E=1V（B・L・R・m は電源なしの版と同じ）：v_t = 0.5 m/s、τ = 2 秒、出だしの電流 0.5A・
//    力 1N ＝ 電源なしの版の終端と同じ数字にそろえた（v(t) の曲線が2つの版で重なる）。
//  ★電源は＋極を下にする（dcsource は1点目が＋極）。電流は左の辺を下へ・棒を上へ流れ、
//    ⊙ の磁場で棒は右向きの力を受ける。＋極を上にすると棒は左へ走って抵抗の側へ寄り、
//    レールの左端で回路から外れる（実測：4.3m で止まった）。
//  ★電源の内部抵抗は 0（抵抗器 1.5Ω＋棒 0.5Ω で回路全体 2Ω。R が1か所に見えるように）。
//  ★実測（サブステップ4・乱数なし）：
//      t = 1 / 2 / 4 / 10 / 15 秒 … v = 0.1968 / 0.3162 / 0.4324 / 0.4966 / 0.4997 m/s
//      理論 0.5(1 − e^(−t/2))    … 0.1967 / 0.3161 / 0.4323 / 0.4966 / 0.4997
//      電流 0.3037 / 0.1841 / 0.0677 / 0.0034 / 0.0003 A（理論 (E − vBL)/R = 0.3033 / 0.1839 / 0.0677）
const IRS_E = 1;       // [V] 電源の起電力
const IRS_EMAX = 2;    // [V] つまみの上限
function demoInducedEmfRodSource() {
  const { rod, field, parts, text } = _irBuild((add, X0, YT, YM, YB) => {
    const H = 35, G = 15;                         // [px] 素子の半分の長さ・素子と素子のすき間の半分
    add('wire', X0, YT, X0, YM - G - 2 * H);
    const src = add('dcsource', X0, YM - G, X0, YM - G - 2 * H, { V: IRS_E, r: 0 });   // ★＋極（1点目）が下
    add('wire', X0, YM - G, X0, YM + G);
    const res = add('resistor', X0, YM + G, X0, YM + G + 2 * H, { R: IR_R });
    add('wire', X0, YM + G + 2 * H, X0, YB);
    addCircTable(res.id, 0, 100);   // ★抵抗の真下・磁場の外（抵抗が下半分にあるぶん電源なしの版より詰める）
    return { src, res };
  }, 0);
  text('導体棒に生じる誘導起電力（電源あり）',
      '紙面の裏から表へ向かう磁場の中で、2本のレールに\n'
    + '導体棒を渡し、レールの左端に電源 E と抵抗をつなぐ。\n'
    + '棒には外から力を加えない。\n'
    + '\n'
    + '電源の電流が磁場から受ける力 IBL で、棒は右へ走り出す。\n'
    + '動き出すと誘導起電力 vBL が電源と逆向きに生じ、\n'
    + '電流は I = (E − vBL)/R に減る。速くなるほど電流も\n'
    + '力も小さくなり、加速度は小さくなっていく。\n'
    + 'vBL = E になると電流も力も 0 で等速直線運動：v = E/(BL)\n'
    + '（R は回路全体の抵抗。棒自身の抵抗も含む）\n'
    + '\n'
    + '【手順】▶実行 を押し、右うえのグラフを見る\n'
    + '・速度：傾きがだんだん緩やかになり、一定の値に近づく\n'
    + '・加速度も、抵抗の表の電流も、棒の矢印も 0 に近づく\n'
    + '・つまみで E・B を変えると、落ち着く速さが変わる\n'
    + '・R を変えても落ち着く速さは同じ（近づく速さだけ変わる）',
    [[parts.src, 'circuit', 'V',        IRS_EMAX],
     [field,     'emfield', 'strength', IR_BMAX],
     [parts.res, 'circuit', 'R',        IR_RMAX]]);
}

// ── 自己誘導（RL回路の電流の立ち上がりと減衰）───────────────────────
//  平行板コンデンサー（回路で充電・放電）のコンデンサーをコイルに替えた回路。配置も操作も同じ。
//      電源 ─ S1 ─┬─ 抵抗 ─┐
//                 S2        L
//      電源 ──────┴────────┘
//    S1 を入れると電流は I = (E/R)(1 − e^(−t/τ)) で増え、S1 を切って S2 に切り替えると、
//    コイルが電流を流し続けようとして抵抗と S2 の輪を同じ向きに流れ、e^(−t/τ) で減る。τ = L/R。
//  ★コンデンサーの充放電はすでに「平行板コンデンサー」にあるので重複させず、対になる
//    コイルの側をここに置く（単元は電磁誘導の自己誘導）。並べて開くと、電圧と電流の役が
//    入れ替わっているのが読める（C は電圧が連続、L は電流が連続）。
//  ★S1 と S2 は同じキー（1）の窓2つで、二者択一の切り替えスイッチとして使う（非直線抵抗・
//    電位差計と同じ手）。初めを S1＝切・S2＝入 にしておけば、キーを押すたびに両方が同じ tick で
//    反転する。別々のキーにすると切る順番で困る：S2 を入れてから S1 を切ると一瞬電源が S2 で
//    短絡し、S1 を先に切るとコイルの電流の行き場が無くなって 1 tick で 0 に落ちる（そのときの
//    L·ΔI/Δt は数千 V。実物ならスイッチに火花が飛ぶ）。
//  ★値：E = 10V・R = 5Ω・L = 10H → 電流の行き着く先 2A、τ = 2秒（平行板コンデンサーの RC と同じ。
//    表の数字の変化が目で追える速さ）。2A なら電流の黄色い点が 120px/s で流れる。
//  ★電源は内部抵抗 0（理想）。直列の R が回路にあるので、コイルの直流分は R で減衰する
//    （CIRCUIT_DEFAULTS の dcsource の★は R の無い回路の話）。
//  ★L のつまみは 0〜20H（τ = 0〜4秒）。0 は解く側の床 0.01H（τ = 2ms）＝コイルの無い回路と同じで、
//    有り無しをつまみ1本で比べられる。
const RLT_E = 10;           // [V]  起電力
const RLT_R = 5;            // [Ω]  抵抗
const RLT_L = 10;           // [H]  自己インダクタンス
const RLT_VMAX = 20;        // [V]  電圧つまみの上限
const RLT_LMAX = 20;        // [H]  L のつまみの上限
function demoSelfInduction() {
  resetDemoWorld();
  setDemoGravity(0);              // ★回路図だけ。重力も地面も出さない
  updateGroundTerrain(false);

  // ★置き方は平行板コンデンサーと同じ（x=0 を画面の右の外へ・本文の右に回路）
  setDemoCam(-700, 0.9);
  const ts = demoTextScale(cam.zoom);
  const W = 330, H = 280;
  const OX = cam.x + (480 * demoFitScale() - canvas.width / 2) / cam.zoom;
  const OY = cam.y + (150 * demoFitScale() - canvas.height / 2) / cam.zoom;
  const XM = OX + 160, X2 = OX + W, Y0 = OY, Y1 = OY + H;
  const MA = OY + H / 2 - 40, MB = OY + H / 2 + 40;   // 縦の辺に入れる素子の上端・下端
  const add = (type, ax, ay, bx, by, o) => {
    const e = new CircuitElement(type, ax, ay, bx, by);
    Object.assign(e, o || {});
    circuitElements.push(e);
    return e;
  };
  // 左の辺：電源（1点目が＋極＝上）
  add('wire', OX, Y0, OX, MA);
  const src = add('dcsource', OX, MA, OX, MB, { V: RLT_E, r: 0 });
  add('wire', OX, MB, OX, Y1);
  // 上の辺：S1 → 分かれ目 → 抵抗 → 右の角
  add('wire', OX, Y0, OX + 50, Y0);
  const s1 = add('switch', OX + 50, Y0, OX + 120, Y0, { closed: false });
  add('wire', OX + 120, Y0, XM, Y0);
  add('wire', XM, Y0, XM + 40, Y0);
  const res = add('resistor', XM + 40, Y0, X2 - 40, Y0, { R: RLT_R });
  add('wire', X2 - 40, Y0, X2, Y0);
  // 真ん中：S2（電流を流し続ける道）
  add('wire', XM, Y0, XM, MA);
  const s2 = add('switch', XM, MA, XM, MB, { closed: true });
  add('wire', XM, MB, XM, Y1);
  // 右の辺：コイル（1点目＝上＝電流が入る側）
  add('wire', X2, Y0, X2, MA);
  const coil = add('inductor', X2, MA, X2, MB, { L: RLT_L });
  add('wire', X2, MB, X2, Y1);
  // 下の辺
  add('wire', X2, Y1, XM, Y1);
  add('wire', XM, Y1, OX, Y1);

  for (const e of [src, res, coil]) addCircTable(e.id);

  const p = demoTextTopLeft();
  const NOTE = '電源・抵抗・コイルをつないだ回路。\n'
  + '素子の横の表に、その素子の値が出る。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・キー 1 で S1 が入り S2 が切れる：電流は\n'
  + '　すぐには流れず、しだいに増えて E／R に近づく。\n'
  + '　コイルに電流の増加を妨げる起電力が生じる\n'
  + '・もう一度キー 1：電源が外れて S2 の輪になる。\n'
  + '　電流は同じ向きのまま、しだいに減る\n'
  + '・どちらも時定数 τ ＝ L／R\n'
  + '・つまみの L を大きくすると、ゆっくりになる';
  const noteY = p.y + 54 * ts;

  // ── 窓の置き場所：平行板コンデンサーと同じ（本文の下に 2×2、グラフはその右）──
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const noteBot  = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  const circBot  = toSY(Y1) + 12;
  const circLeft = (OX - cam.x) * cam.zoom + canvas.width / 2 - 40;
  const GAP = 6, RL = 56;
  const put = (r, col, row) => {
    const w = r.panel.offsetWidth || 170, h = r.panel.offsetHeight || 180;
    let top = noteBot + GAP;
    if (RL + 2 * w + GAP > circLeft) top = Math.max(top, circBot + GAP);
    top = Math.min(top, canvas.height - 2 * h - GAP - 4);
    r.fx = (RL + col * (w + GAP)) / canvas.width;
    r.fy = (top + row * (h + GAP)) / canvas.height;
    placeRemotePanel(r); syncRemotePanel(r);
  };
  const sw1 = addRemote('ghost', s1, 'circuit');
  if (sw1) { sw1.key = 'Digit1'; put(sw1, 0, 0); }
  const sw2 = addRemote('ghost', s2, 'circuit');
  if (sw2) { sw2.key = 'Digit1'; put(sw2, 0, 1); }
  const kv = addRemote('prop', src, 'circuit');
  if (kv) { kv.prop = 'V'; kv.lo = 0; kv.hi = RLT_VMAX; put(kv, 1, 0); }
  const kl = addRemote('prop', coil, 'circuit');
  if (kl) { kl.prop = 'L'; kl.lo = 0; kl.hi = RLT_LMAX; put(kl, 1, 1); }
  // ── コイルのグラフ（電圧・電流の時間変化。電流の軸に磁束 Φ = LI を併記）──
  const remRight = Math.max(0, ...[sw1, sw2, kv, kl].filter(Boolean)
    .map(r => r.panel.offsetLeft + r.panel.offsetWidth));
  const g = circGraphOpen([coil.id]);
  if (g) {
    const gl = remRight + 10, gt = circBot + 10, EDGE = 14;
    sizeDemoGraph(g, Math.min(640, canvas.width - gl - EDGE), canvas.height - gt - EDGE);
    g.panel.style.left = Math.round(gl) + 'px'; g.panel.style.right = 'auto';
    moveDemoGraphBottom(g);
  }

  const LC = '#ffd54f';
  demoLabel((OX + 50 + OX + 120) / 2 - 22, Y0 - 58 * ts, 'S1', LC, DEMO_NOTE_SIZE * ts, true);
  demoLabel(XM + 16, (MA + MB) / 2 - 12 * ts, 'S2', LC, DEMO_NOTE_SIZE * ts, true);

  demoTitle(p.x, p.y, 'コイルを含む直流回路', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── 平行板コンデンサー（回路で充電・放電）───────────────────────
//  ★題材は Q = CV と充電・放電。平行板コンデンサーモデル（電子の粒で組んだ模型）では
//    Q = CV が出なかった（CAP_* の上の★）ので、こちらは回路素子で組んで、
//    値は「回路の表」で読ませる。表は回路に何も足さない（計器と違って内部抵抗を持たない）。
//  ★回路は手で組める部品だけ：直流電源・スイッチ2つ・抵抗・コンデンサー・導線。
//      電源 ─ S1 ─┬─ 抵抗 ─┐
//                 S2        C
//      電源 ──────┴────────┘
//    S1 を入れると充電、S1 を切って S2 を入れると抵抗を通って放電。
//    ★S1 と S2 を同時に入れると電源が S2 で短絡する。二者択一のスイッチは素子に無いので、
//      本文で断る（内部抵抗 0 でも計算は破綻しない：SRC_R_MIN が当たり、非常に大きな
//      有限電流が表に出る＝短絡していると分かる。CIRCUIT_DEFAULTS の★）。
//  ★電源は内部抵抗 0（理想電源）。表の電源の電圧が起電力と一致し、充電しきったときの
//    コンデンサーの電圧がそのまま電源の電圧になる（内部抵抗があっても電流 0 なら同じだが、
//    充電中の電源の電圧が 10V からずれて KVL の足し算が表で合わなく見える）。
//  ★時定数 τ = RC = 20Ω × 0.1F = 2秒。表の数字の変化が目で追える速さ（既定の 10Ω×1mF は
//    10ms で、1 tick ＝ 16.7ms のうちに終わってしまい表では読めない）。
//  ★τ は R を小さく・C を大きくして作る（以前は 1kΩ × 2mF）。電流の黄色い点の速さは電流に
//    比例し 1A で 60px/s（FLOW_PX_PER_A）なので、1kΩ では入れた直後でも 10mA ＝ 0.6px/s、
//    点1個ぶん（20px）進むのに 33秒かかり止まって見えた。20Ω なら直後 0.5A ＝ 30px/s。
//    C はつまみの上限（CIRCUIT_KNOB_RANGE の 0.1F）に置く。
//  ★実測（デモのまま S1 を入れて。理論は V_C = 10(1 − e^(−t/2))、放電は V₀e^(−t/2)）：
//      充電  t = 0.5 / 1 / 2 / 4 秒 … V_C = 2.212 / 3.935 / 6.321 / 8.647 V（理論と4桁一致）
//            どの時刻も 抵抗の V ＋ コンデンサーの V ＝ 10.000 V
//      50秒で V_C = 10.00000 V。S1 を切って 600秒置いても変わらない（電気量は残る）
//      S1・S2 とも開いたまま 60秒置くと V_C = 0（厳密に0。以前は対接地 Gmin が漏れの道になって
//      1e-5 V/s で勝手に充電されていた。_floatingIslandRoots の★）
//      放電  t = 1 / 2 秒 … V_C = 6.065 / 3.679 V（理論と4桁一致）
//      つまみで 5V・50mF にして充電し直すと Q = 0.250 C（= CV）
//    （以上は 20Ω × 0.1F で測り直した値。τ が同じなので 1kΩ × 2mF のときと同じ数字になる）
//    台形則なので τ に対して 1 tick が十分短ければずれはこの桁に出ない。
const PPC_E  = 10;          // [V]  起電力
const PPC_R  = 20;          // [Ω]  抵抗
const PPC_C  = 0.1;         // [F]  容量（100mF）
const PPC_VMAX = 20;        // [V]  電圧つまみの上限
const PPC_CLO = 20, PPC_CHI = 100;   // [mF] 容量つまみの範囲（τ = 0.4〜2秒）
function demoParallelPlateCapacitor() {
  resetDemoWorld();
  setDemoGravity(0);              // ★回路図だけ。重力も地面も出さない
  updateGroundTerrain(false);

  // ★世界の x=0 を画面の右の外へ出す。縦軸の目盛りの札（4.5m・3m）が回路に重なる
  setDemoCam(-700, 0.9);
  // 回路の左上。★本文（画面の左 390px）の右へ置く：画面 x = (世界x − cam.x)·zoom + W/2
  //   ★各素子の横に回路の表が出るので、そのぶんの余白を回路の外に取る：
  //     抵抗の表は上（画面の上端 55px の操作ヒントの帯より下へ）、コンデンサーの表は右
  //     （幅 110px 前後）。電源の表は回路の内側（電源と S2 のあいだ）に入る。
  const ts = demoTextScale(cam.zoom);
  const W = 330, H = 280;
  const OX = cam.x + (480 * demoFitScale() - canvas.width / 2) / cam.zoom;
  const OY = cam.y + (150 * demoFitScale() - canvas.height / 2) / cam.zoom;
  const XM = OX + 160, X2 = OX + W, Y0 = OY, Y1 = OY + H;
  const MA = OY + H / 2 - 40, MB = OY + H / 2 + 40;   // 縦の辺に入れる素子の上端・下端
  const add = (type, ax, ay, bx, by, o) => {
    const e = new CircuitElement(type, ax, ay, bx, by);
    Object.assign(e, o || {});
    circuitElements.push(e);
    return e;
  };
  // 左の辺：電源（1点目が＋極＝上）
  add('wire', OX, Y0, OX, MA);
  const src = add('dcsource', OX, MA, OX, MB, { V: PPC_E, r: 0 });
  add('wire', OX, MB, OX, Y1);
  // 上の辺：S1 → 分かれ目 → 抵抗 → 右の角
  add('wire', OX, Y0, OX + 50, Y0);
  const s1 = add('switch', OX + 50, Y0, OX + 120, Y0, { closed: false });
  add('wire', OX + 120, Y0, XM, Y0);
  add('wire', XM, Y0, XM + 40, Y0);
  const res = add('resistor', XM + 40, Y0, X2 - 40, Y0, { R: PPC_R });
  add('wire', X2 - 40, Y0, X2, Y0);
  // 真ん中：S2（放電の道）
  add('wire', XM, Y0, XM, MA);
  const s2 = add('switch', XM, MA, XM, MB, { closed: false });
  add('wire', XM, MB, XM, Y1);
  // 右の辺：コンデンサー
  add('wire', X2, Y0, X2, MA);
  const cap = add('capacitor', X2, MA, X2, MB, { C: PPC_C });
  add('wire', X2, MB, X2, Y1);
  // 下の辺
  add('wire', X2, Y1, XM, Y1);
  add('wire', XM, Y1, OX, Y1);

  // ── 回路の表：電源・抵抗・コンデンサーの横に1枚ずつ ──
  for (const e of [src, res, cap]) addCircTable(e.id);

  const p = demoTextTopLeft();
  const NOTE = '電源・抵抗・コンデンサーをつないだ回路。\n'
  + '素子の横の表に、その素子の値が出る。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・S1 を入れる（キー 1）：コンデンサーに電気が\n'
  + '　たまる。電流はしだいに減り、コンデンサーの\n'
  + '　電圧が電源に追いつくと止まる（充電）\n'
  + '・途中も 抵抗の電圧＋コンデンサーの電圧＝電源\n'
  + '・S1 を切る：電気量はそのまま残る\n'
  + '・S2 を入れる（キー 2）：抵抗を通って\n'
  + '　逆向きに流れる（放電）\n'
  + '・つまみで電圧や容量を変えて充電し直す：Q ＝ CV\n'
  + '※ S1 と S2 を同時に入れるとショートする';
  const noteY = p.y + 54 * ts;

  // ── 窓の置き場所（キャンバスの左うえを原点とする画面 px）──
  //   ★リモコンの窓は倍率によらず 170×179px の固定の大きさ、本文と回路は demoFitScale で
  //     伸び縮みする。以前は窓を画面の割合（fx, fy）と決め打ちの px で置いていたので、
  //     窓の形によって重なった（実測：1366×768 でリモコン3・4の右端がグラフの左端に 8px
  //     掛かっていた）。そこで本文の下端・回路の下端を実際に測り、窓はそこから詰めて置く。
  //     リモコン：本文の下に 2×2。グラフ：リモコンの右、回路の下端より下の残り全部。
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const noteBot  = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  const circBot  = toSY(Y1) + 12;                                       // 下の辺の節点の丸のぶん
  const circLeft = (OX - cam.x) * cam.zoom + canvas.width / 2 - 40;    // 電源の「10V」の札のぶん
  // ── リモコン：S1・S2 の入り切り（キー 1・2）と、電圧・容量のつまみ ──
  //   ★窓はどれも高さ 180px 前後あるので、縦に4つは積めない
  const GAP = 6, RL = 56;           // RL は placeRemotePanel の左端の下限（左の操作ヒントを避ける）
  const put = (r, col, row) => {
    const w = r.panel.offsetWidth || 170, h = r.panel.offsetHeight || 180;
    let top = noteBot + GAP;
    // ★2列目が回路の真下に掛かる狭い窓では、回路の下端より下へ下げる
    if (RL + 2 * w + GAP > circLeft) top = Math.max(top, circBot + GAP);
    // ★縦が足りない窓では下端に収まるところまで上げる（掛かるのは本文の最終行の下の行間だけ）
    top = Math.min(top, canvas.height - 2 * h - GAP - 4);
    r.fx = (RL + col * (w + GAP)) / canvas.width;
    r.fy = (top + row * (h + GAP)) / canvas.height;
    placeRemotePanel(r); syncRemotePanel(r);
  };
  const sw1 = addRemote('ghost', s1, 'circuit');
  if (sw1) { sw1.key = 'Digit1'; put(sw1, 0, 0); }
  const sw2 = addRemote('ghost', s2, 'circuit');
  if (sw2) { sw2.key = 'Digit2'; put(sw2, 0, 1); }
  const kv = addRemote('prop', src, 'circuit');
  if (kv) { kv.prop = 'V'; kv.lo = 0; kv.hi = PPC_VMAX; put(kv, 1, 0); }
  const kc = addRemote('prop', cap, 'circuit');
  if (kc) { kc.prop = 'C'; kc.lo = PPC_CLO; kc.hi = PPC_CHI; put(kc, 1, 1); }
  // ── コンデンサーのグラフ（電圧・電流の時間変化。電圧の軸に電気量 Q = CV を併記）──
  //   ★リモコンの右、回路の下端より下の空きへ。幅は右端まで（上限 640px）、高さは下端まで
  //   ★本文には足さない（1行足すとリモコンの窓に本文の最終行が隠れる。実測）
  const remRight = Math.max(0, ...[sw1, sw2, kv, kc].filter(Boolean)
    .map(r => r.panel.offsetLeft + r.panel.offsetWidth));
  const g = circGraphOpen([cap.id]);
  if (g) {
    const gl = remRight + 10, gt = circBot + 10, EDGE = 14;
    sizeDemoGraph(g, Math.min(640, canvas.width - gl - EDGE), canvas.height - gt - EDGE);
    g.panel.style.left = Math.round(gl) + 'px'; g.panel.style.right = 'auto';
    moveDemoGraphBottom(g);
  }

  // ── 札 ──
  const LC = '#ffd54f';
  demoLabel((OX + 50 + OX + 120) / 2 - 22, Y0 - 58 * ts, 'S1', LC, DEMO_NOTE_SIZE * ts, true);
  demoLabel(XM + 16, (MA + MB) / 2 - 12 * ts, 'S2', LC, DEMO_NOTE_SIZE * ts, true);

  demoTitle(p.x, p.y, 'コンデンサーを含む直流回路', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ════════════════════════════════════════
//  ホイートストンブリッジ
// ════════════════════════════════════════
//  ひし形の4辺に抵抗、対角（上の角 C と下の角 D）に検流計（＝内部抵抗0の電流計）を渡す。
//  右下の Rx だけをつまみで変える。R1/R2 = R3/Rx のとき C と D が同じ電位になり、
//  検流計の点が止まる（つりあい）。つりあいを越えると検流計の電流が向きを変える。
//  ★電流の見え方は回路の黄色い点（drawCircuitFlow）に任せる。点の速さ ∝ 電流、間隔一定
//    なので、分かれ目での分流と「検流計だけ点が止まる」がそのまま絵になる。
//  ★電源は内部抵抗0（理想）。つりあいの条件に電源は入らないが、枝の電流を E/(R1+R2) と
//    暗算で合わせられるようにしておく。
//  ★つまみは 0 から線形（0 を含む）。つりあいの 30Ω が可動域のちょうど中央に来るように
//    上限を 60Ω にしてある。初期値はつりあいから外した 10Ω（開いたときに検流計が振れている）。
const WB_E   = 20;             // [V] 起電力（枝の電流 0.67A・0.57A 前後＝点が 30〜40px/s で見える速さ）
const WB_R1  = 10, WB_R2 = 20, WB_R3 = 15;   // [Ω] 左上・右上・左下
const WB_RX0 = 10;             // [Ω] 右下（可変）の初期値
const WB_RXMAX = 60;           // [Ω] つまみの上限（つりあいは R2·R3/R1 = 30Ω）
function demoWheatstoneBridge() {
  resetDemoWorld();
  setDemoGravity(0);              // ★回路図だけ。重力も地面も出さない
  updateGroundTerrain(false);

  setDemoCam(-700, 0.9);          // ★平行板コンデンサーと同じ構え（縦軸の目盛りを画面の外へ）
  const ts = demoTextScale(cam.zoom);
  // ひし形の左の角。★本文（画面の左）の右へ置く：画面 x = (世界x − cam.x)·zoom + W/2
  const W = 340, H = 300;
  const OX = cam.x + (540 * demoFitScale() - canvas.width / 2) / cam.zoom;
  const CY = cam.y + (330 * demoFitScale() - canvas.height / 2) / cam.zoom;
  const A = { x: OX,         y: CY };          // 左（電源の＋から）
  const C = { x: OX + W / 2, y: CY - H / 2 };  // 上
  const B = { x: OX + W,     y: CY };          // 右（電源の−へ）
  const D = { x: OX + W / 2, y: CY + H / 2 };  // 下
  const YS = D.y + 70;                         // 電源の段
  const add = (type, ax, ay, bx, by, o) => {
    const e = new CircuitElement(type, ax, ay, bx, by);
    Object.assign(e, o || {});
    circuitElements.push(e);
    return e;
  };
  // 辺 P→Q の真ん中 60% に素子を置き、両端を導線でつなぐ
  const side = (P, Q, type, o) => {
    const lerp = t => ({ x: P.x + (Q.x - P.x) * t, y: P.y + (Q.y - P.y) * t });
    const a = lerp(0.2), b = lerp(0.8);
    add('wire', P.x, P.y, a.x, a.y);
    const e = add(type, a.x, a.y, b.x, b.y, o);
    add('wire', b.x, b.y, Q.x, Q.y);
    return e;
  };
  const r1 = side(A, C, 'resistor', { R: WB_R1 });
  const r2 = side(C, B, 'resistor', { R: WB_R2 });
  const r3 = side(A, D, 'resistor', { R: WB_R3 });
  const rx = side(D, B, 'resistor', { R: WB_RX0 });
  // 対角：検流計（上→下を正）
  const g = side(C, D, 'ammeter', { r: 0 });
  // 電源：左の角から下り、下の段を右へ（1点目が＋極＝左）、右の角へ上る
  const XM = (A.x + B.x) / 2;
  add('wire', A.x, A.y, A.x, YS);
  add('wire', A.x, YS, XM - 40, YS);
  const src = add('dcsource', XM - 40, YS, XM + 40, YS, { V: WB_E, r: 0 });
  add('wire', XM + 40, YS, B.x, YS);
  add('wire', B.x, YS, B.x, B.y);

  // ── 回路の表：4つの抵抗の横に1枚ずつ（ひし形の外側へ）──
  //   ★つりあいでは R1 と R3、R2 と Rx の電圧がそろう＝上と下の角が同じ電位、が表で読める。
  //     検流計は表を持たない（読みは素子の横の数字）。dx・dy は素子の中点からの画面 px
  const TW = 122;
  addCircTable(r1.id, -TW - 60, -95);
  addCircTable(r2.id,  70,      -95);
  addCircTable(r3.id, -TW - 60,  40);
  addCircTable(rx.id,  70,       40);

  const p = demoTextTopLeft();
  const NOTE = 'ひし形の4辺に抵抗、上と下の角のあいだに\n'
  + '検流計 G をつないだ回路（ホイートストンブリッジ）。\n'
  + '黄色い点は電流の向きに動き、速いほど電流が大きい。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・つまみで Rx を変える\n'
  + '・R1 : R2 ＝ R3 : Rx になると、上の角と下の角が\n'
  + '　同じ電位になり、G の点が止まる（つりあい）\n'
  + '・そこを越えると G の電流が逆向きになる\n'
  + '・つりあいの Rx から Rx ＝ R2·R3 / R1 が分かる';
  const noteY = p.y + 54 * ts;

  // ── リモコン：Rx のつまみ（Rx の右下＝回路の下の段より下）──
  //   ★操作する抵抗のそばに置く。窓の左端を Rx の中点にそろえ、電源の段の下へ出す。
  //     窓は倍率によらず固定の大きさなので、右端・下端ではキャンバスの内側へ押し戻す
  const toSX = wx => (wx - cam.x) * cam.zoom + canvas.width / 2;
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const kx = addRemote('prop', rx, 'circuit');
  if (kx) {
    kx.prop = 'R'; kx.lo = 0; kx.hi = WB_RXMAX;
    const w = kx.panel.offsetWidth || 170, h = kx.panel.offsetHeight || 180;
    const left = Math.min(toSX((rx.ax + rx.bx) / 2), canvas.width - w - 10);
    const top  = Math.min(toSY(YS) + 16, canvas.height - h - 10);   // 下の段の節点の丸のぶん
    kx.fx = left / canvas.width;
    kx.fy = top / canvas.height;
    placeRemotePanel(kx); syncRemotePanel(kx);
  }

  // ── 札 ──
  const LC = '#ffd54f', LS = DEMO_NOTE_SIZE * ts;
  const mid = e => ({ x: (e.ax + e.bx) / 2, y: (e.ay + e.by) / 2 });
  const m1 = mid(r1), m2 = mid(r2), m3 = mid(r3), mx = mid(rx), mg = mid(g);
  demoLabel(m1.x + 14 * ts, m1.y + 22 * ts, 'R1', LC, LS, true);
  demoLabel(m2.x - 44 * ts, m2.y + 22 * ts, 'R2', LC, LS, true);
  demoLabel(m3.x + 14 * ts, m3.y - 40 * ts, 'R3', LC, LS, true);
  demoLabel(mx.x - 44 * ts, mx.y - 40 * ts, 'Rx', LC, LS, true);
  demoLabel(mg.x + 22 * ts, mg.y - 12 * ts, 'G', LC, LS, true);

  demoTitle(p.x, p.y, 'ホイートストンブリッジ', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ════════════════════════════════════════
//  直流回路（電源と抵抗・直列回路・並列回路）
// ════════════════════════════════════════
//  電源と抵抗だけの回路を3つのデモに分ける。どれも電源と抵抗のすべてにつまみを付け、
//  素子の横の表で電圧・電流を読む。
//  ★電源は内部抵抗0（理想）。値は暗算で合う組にしてある：
//    電源と抵抗 E = 6V・R = 10Ω → I = 0.6A
//    直列 E = 12V・R1 = 10Ω・R2 = 20Ω → I = 0.4A・V1 = 4V・V2 = 8V
//    並列 E = 12V・R1 = 10Ω・R2 = 20Ω → I1 = 1.2A・I2 = 0.6A・I = 1.8A
//  ★つまみは 0 から線形（0 を含む）。抵抗を 0 にすると電源がショートするが、ソルバは
//    発散せず大きな有限の電流を返す（実測：12V で 12kA）。ショートを試せるのも遊び道具のうち。
//  ★回路の表は素子の札（10Ω）の反対側＝上に出る。素子は横向きに置き、電源は下の辺へ。
//    縦向きに置いた素子の表は回路の内側に入り、導線や隣の素子の札に掛かった（実測）。
const DC_VMAX = 20;              // [V] 電圧つまみの上限
const DC_RMAX = 50;              // [Ω] 抵抗つまみの上限
// 3つのデモで共通の構え：回路図だけ（重力も地面も出さない）、縦軸の目盛りを画面の外へ
function dcBegin(zoom) {
  resetDemoWorld();
  setDemoGravity(0);
  updateGroundTerrain(false);
  setDemoCam(-700, zoom);         // ★ホイートストンブリッジと同じ構え
  cam.y -= 300;                   // ★横軸（世界 y=0）の目盛りを回路の下端から離す
  const fromSX = sx => cam.x + (sx - canvas.width / 2) / cam.zoom;
  const fromSY = sy => cam.y + (sy - canvas.height / 2) / cam.zoom;
  const toSY = wy => (wy - cam.y) * cam.zoom + canvas.height / 2;
  const add = (type, ax, ay, bx, by, o) => {
    const e = new CircuitElement(type, ax, ay, bx, by);
    Object.assign(e, o || {});
    circuitElements.push(e);
    return e;
  };
  return { ts: demoTextScale(cam.zoom), fromSX, fromSY, toSY, add };
}
// つまみのリモコン。targets は [素子, 'V' か 'R', 上限]
function dcKnobs(targets) {
  return targets.map(([e, prop, hi]) => {
    const r = addRemote('prop', e, 'circuit');
    if (r) { r.prop = prop; r.lo = 0; r.hi = hi; }
    return r;
  }).filter(Boolean);
}
// リモコンを横1列に並べる（画面 px の左端・上端）。★窓は倍率によらず固定の大きさ
function dcPlaceRow(rs, left, top) {
  const GAP = 6;
  let x = left;
  for (const r of rs) {
    const w = r.panel.offsetWidth || 170;
    r.fx = x / canvas.width;
    r.fy = top / canvas.height;
    placeRemotePanel(r); syncRemotePanel(r);
    x += w + GAP;
  }
}
// つまみの窓を1枚、素子のすぐ横に置く。side は窓を素子のどちら側に出すか
//   'left'・'right'：窓の縦の中央を素子の中点の高さにそろえる（上端は minTop より下）。
//     edgeX（世界 x）を渡すと、窓をその線より外に出す（回路の辺の外）。★素子の中点から
//     測ると、右の窓が右の縦の導線と抵抗の表に掛かった（実測）
//   'below'：窓の横の中央を素子の中点にそろえる
//   ★窓から素子へのつなぎ線が短く出て、どの窓がどの素子か位置で分かる
//   ★左右の gap は素子の値の札（「12V」）が素子と窓のあいだに入るぶんを取る
function dcKnobAt(r, e, side, minTop, edgeX) {
  if (!r) return;
  const w = r.panel.offsetWidth || 170, h = r.panel.offsetHeight || 180;
  const sx = ((e.ax + e.bx) / 2 - cam.x) * cam.zoom + canvas.width / 2;
  const sy = ((e.ay + e.by) / 2 - cam.y) * cam.zoom + canvas.height / 2;
  const ex = edgeX === undefined ? sx : (edgeX - cam.x) * cam.zoom + canvas.width / 2;
  const top = Math.max(minTop || 0, sy - h / 2);
  if (side === 'left')       dcPlaceRow([r], Math.min(sx, ex) - 40 - w, top);
  else if (side === 'right') dcPlaceRow([r], Math.max(sx, ex) + 16, top);
  else                       dcPlaceRow([r], sx - w / 2, sy + 30);
}
// 素子の札（R1・R2）。素子の値の札（10Ω）のすぐ下に置く
function dcNameLabel(e, s, ts) {
  demoLabel((e.ax + e.bx) / 2 - 12 * ts, (e.ay + e.by) / 2 + 22 * ts, s,
            '#ffd54f', DEMO_NOTE_SIZE * ts, true);
}

// ── 電源と抵抗 ──────────────────────────────
//  電源に抵抗を1つだけつなぐ。つまみは電源の電圧と抵抗。
//  ★グラフは抵抗の電流−時間と電圧−時間を別の窓に分ける。回路グラフの窓は1つで V と I を
//    両方描けるが、表示のチェックで片方ずつにして2枚開く（手でも同じ操作で作れる）。
//    つまみを動かした瞬間に段になって変わる＝直流は時間で変わらない、が読める。
const DC1_E = 6, DC1_R = 10;
function demoDCSimple() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.1);
  const toSX = wx => (wx - cam.x) * cam.zoom + canvas.width / 2;
  // 上の辺に抵抗、左の辺に電源（1点目が＋極＝上）
  //   ★四隅は画面 px で決める（本文の右・グラフの上に収める）。左右には つまみの窓
  //     （幅 170px）を1枚ずつ置くので、回路の幅はその残り
  //   ★電源を下の辺に置くと、左に置いたつまみの窓からのつなぎ線が回路の左の導線を
  //     斜めに横切った（実測）。左の辺に立てれば線は真横に短く出る
  const f = demoFitScale();
  const OX = fromSX(555 * f), X2 = fromSX(810 * f);
  const OY = fromSY(165 * f), Y1 = fromSY(375 * f);
  const XM = (OX + X2) / 2;
  add('wire', OX, OY, XM - 55, OY);
  const res = add('resistor', XM - 55, OY, XM + 55, OY, { R: DC1_R });
  add('wire', XM + 55, OY, X2, OY);
  add('wire', X2, OY, X2, Y1);
  add('wire', X2, Y1, OX, Y1);
  const YM = (OY + Y1) / 2;
  add('wire', OX, Y1, OX, YM + 45);
  const src = add('dcsource', OX, YM - 45, OX, YM + 45, { V: DC1_E, r: 0 });
  add('wire', OX, YM - 45, OX, OY);
  for (const e of [src, res]) addCircTable(e.id);

  const p = demoTextTopLeft();
  const NOTE = '電源に抵抗を1つだけつないだ回路。\n'
  + '素子の横の表に、その素子の電圧と電流が出る。\n'
  + '黄色い点は電流の向きに動き、速いほど電流が大きい。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・つまみで電源の電圧と抵抗を変える\n'
  + '・電流は電圧に比例し、抵抗に反比例する\n'
  + '　I ＝ V／R（オームの法則）\n'
  + '・グラフ：つまみを動かすまでは一定（直流）';
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));

  // ── リモコン：つないだ素子のすぐ横 ──
  //   ★抵抗のつまみは上の辺の右、電源のつまみは左の辺の左（本文の下）。窓から素子への
  //     つなぎ線が短く横に出て、どの窓がどの素子か位置で分かる。電源の窓は電源の高さに
  //     合わせるが、本文の最終行には掛けない
  const [kv, kr] = dcKnobs([[src, 'V', DC_VMAX], [res, 'R', DC_RMAX]]);
  const GAP = 12;
  if (kr) dcPlaceRow([kr], toSX(X2) + GAP, toSY(OY) - (kr.panel.offsetHeight || 180) / 2);
  if (kv) dcPlaceRow([kv], toSX(OX) - 40 - (kv.panel.offsetWidth || 170),    // 40 は電源の「6V」の札のぶん
                     Math.max(noteBot + 6, toSY(YM) - (kv.panel.offsetHeight || 180) / 2));
  const ks = [kv, kr].filter(Boolean);
  // ── グラフ：抵抗の電流−時間（左）・電圧−時間（右）。リモコンと回路の下から下端まで ──
  const remBot = Math.max(toSY(Y1) + 30, ...ks.map(r => r.panel.offsetTop + r.panel.offsetHeight));
  const EDGE = 10, gw = Math.floor((canvas.width - 3 * EDGE) / 2);
  const gh = canvas.height - remBot - 2 * EDGE;
  [[{ showV: false }, '電流−時間'], [{ showI: false }, '電圧−時間']].forEach(([o, title], k) => {
    const g = circGraphOpen([res.id], o);
    if (!g) return;
    g.titleEl.textContent = title;
    sizeDemoGraph(g, gw, gh);
    g.panel.style.left = (EDGE + k * (gw + EDGE)) + 'px'; g.panel.style.right = 'auto';
    moveDemoGraphBottom(g);
  });

  dcNameLabel(res, 'R', ts);
  demoTitle(p.x, p.y, '電源と抵抗', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── 直列回路 ──────────────────────────────
//  左の辺に電源、上の辺に R1、下の辺に R2 の輪。つまみは電源・R1・R2 の3つで、
//  それぞれ素子のすぐ横に置く（電源は左＝本文の下、R1 は右、R2 は下）。
//  ★R1 は上の辺の右寄りに置き、右の窓からのつなぎ線を短くする。R2 は下の辺の右寄りに置き、
//    表（R2 の上＝輪の内側）が電源の表（電源の右＝輪の内側）と重ならないようにする
const DC_E = 12, DC_R1 = 10, DC_R2 = 20;
function demoSeriesCircuit() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.0);
  const f = demoFitScale();
  const OX = fromSX(560 * f), X2 = fromSX(800 * f);
  const OY = fromSY(150 * f), Y1 = fromSY(420 * f);
  const YM = (OY + Y1) / 2, C1 = X2 - 80, C2 = X2 - 90;   // R1・R2 の中点の x
  add('wire', OX, OY, C1 - 50, OY);
  const r1 = add('resistor', C1 - 50, OY, C1 + 50, OY, { R: DC_R1 });
  add('wire', C1 + 50, OY, X2, OY);
  add('wire', X2, OY, X2, Y1);
  add('wire', X2, Y1, C2 + 50, Y1);
  const r2 = add('resistor', C2 - 50, Y1, C2 + 50, Y1, { R: DC_R2 });
  add('wire', C2 - 50, Y1, OX, Y1);
  add('wire', OX, Y1, OX, YM + 45);
  const src = add('dcsource', OX, YM - 45, OX, YM + 45, { V: DC_E, r: 0 });   // 1点目が＋極＝上
  add('wire', OX, YM - 45, OX, OY);
  for (const e of [src, r1, r2]) addCircTable(e.id);

  const p = demoTextTopLeft();
  const NOTE = '電源に抵抗を2つ、一列につないだ回路（直列）。\n'
  + '素子の横の表に、その素子の電圧と電流が出る。\n'
  + '黄色い点は電流の向きに動き、速いほど電流が大きい。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・電流はどこも同じ\n'
  + '・電圧は抵抗の大きさに比例して分かれ、\n'
  + '　V1 ＋ V2 ＝ 電源の電圧\n'
  + '・合成抵抗 R ＝ R1 ＋ R2\n'
  + '・つまみで電源と抵抗を変えて確かめる';
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  const [kv, k1, k2] = dcKnobs([[src, 'V', DC_VMAX], [r1, 'R', DC_RMAX], [r2, 'R', DC_RMAX]]);
  dcKnobAt(kv, src, 'left', noteBot + 6);
  dcKnobAt(k1, r1, 'right', 0, X2);
  dcKnobAt(k2, r2, 'below');

  dcNameLabel(r1, 'R1', ts);
  dcNameLabel(r2, 'R2', ts);
  demoTitle(p.x, p.y, '直列回路', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── 並列回路 ──────────────────────────────
//  左右の縦の導線のあいだに R1・R2・電源を3段に渡す。つまみは電源・R1・R2 の3つで、
//  それぞれ素子のすぐ横に置く（R1・R2 は右にその段の高さで、電源は真下）。
//  ★R1 と R2 の段の間隔は、右に縦に並べる窓の高さ（180px 前後）より広く取る。
//    R1・R2 は段の右寄りに置き、右の窓からのつなぎ線を短くする
function demoParallelCircuit() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.0);
  const f = demoFitScale();
  const OX = fromSX(560 * f), X2 = fromSX(800 * f), XM = (OX + X2) / 2;
  const PY0 = fromSY(150 * f), PY1 = fromSY(340 * f), PY2 = fromSY(490 * f);
  const rung = (y, cx, type, o) => {
    add('wire', OX, y, cx - 50, y);
    const e = add(type, cx - 50, y, cx + 50, y, o);
    add('wire', cx + 50, y, X2, y);
    return e;
  };
  const r1 = rung(PY0, X2 - 80, 'resistor', { R: DC_R1 });
  const r2 = rung(PY1, X2 - 80, 'resistor', { R: DC_R2 });
  const src = add('dcsource', XM - 40, PY2, XM + 40, PY2, { V: DC_E, r: 0 });   // 1点目が＋極＝左
  add('wire', OX, PY2, XM - 40, PY2);
  add('wire', XM + 40, PY2, X2, PY2);
  add('wire', OX, PY0, OX, PY1);  add('wire', OX, PY1, OX, PY2);
  add('wire', X2, PY0, X2, PY1);  add('wire', X2, PY1, X2, PY2);
  // ★電源の表の電流が回路全体の電流。I ＝ I1 ＋ I2 がこの表と抵抗の表で読める
  for (const e of [src, r1, r2]) addCircTable(e.id);

  const p = demoTextTopLeft();
  const NOTE = '電源の両端に抵抗を2つ、枝分かれさせて\n'
  + 'つないだ回路（並列）。\n'
  + '素子の横の表に、その素子の電圧と電流が出る。\n'
  + '黄色い点は電流の向きに動き、速いほど電流が大きい。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・電圧はどの抵抗も電源と同じ\n'
  + '・電流は抵抗に反比例して分かれ、\n'
  + '　I1 ＋ I2 ＝ 電源の電流\n'
  + '・合成抵抗 1/R ＝ 1/R1 ＋ 1/R2\n'
  + '・つまみで R2 を変えても、R1 の電流は変わらない';
  const noteY = p.y + 54 * ts;
  const [kv, k1, k2] = dcKnobs([[src, 'V', DC_VMAX], [r1, 'R', DC_RMAX], [r2, 'R', DC_RMAX]]);
  dcKnobAt(kv, src, 'below');
  dcKnobAt(k1, r1, 'right', 0, X2);
  dcKnobAt(k2, r2, 'right', 0, X2);

  dcNameLabel(r1, 'R1', ts);
  dcNameLabel(r2, 'R2', ts);
  demoTitle(p.x, p.y, '並列回路', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── 分流器 ──────────────────────────────
//  上の辺（本線）に内部抵抗 rA の電流計、その上に張り出した段にスイッチ S と分流器 RS を
//  並列に渡し、右の辺を下りて下の辺に負荷の抵抗 R、左の辺に電源の輪。
//  つまみは電源・電流計の内部抵抗 rA・RS、S は入り切りの窓。
//  ★電流計は回路の電流計（ammeter）の内部抵抗 r を 0.9Ω にしただけ。右パネルで手で同じにできる。
//    RS ＝ 0.1Ω で I ＝ (1 ＋ rA/RS)·IA ＝ 10·IA。電流計の読み（素子の横の数字）と電源の表の
//    電流を見くらべる。電流計に最大目盛りの概念は無い（振り切れない）ので、本文でも
//    「最大目盛り」は式の説明にだけ使い、画面に上限の札は立てない
//  ★電流計が本線、分流器が張り出した段（ユーザーの指示で入れ替えた）。S は分流器へ向かう
//    左の縦の導線に入れる。S を切って始める＝まず電流計だけで I ＝ IA を見て、入れると分かれる。
//    ★負荷 R ＝ 100Ω ≫ rA にして、S を入れても I がほぼ変わらない＝「同じ電流を測り直す」図にする
//    （ユーザーの指示）。rA ＝ 9Ω・R ＝ 2Ω では S で I が 1.09→4.14A と4倍になっていた。
//    RS はつまみの下限 0.1Ω で、n ＝ 10 に割り切れるよう rA ＝ 0.9Ω を逆算した。
//    実測：S 切で I ＝ IA ＝ 118.9mA、S 入で I ＝ 119.9mA（＋0.8%）・IA ＝ 11.99mA（比 10.0）
const SH_E = 12, SH_RA = 0.9, SH_RS = 0.1, SH_R = 100;
// ★RS は 0〜20Ω。RS ≫ rA（分けない＝n→1）と RS ≪ rA（IA が小さすぎる）の両端まで回せる幅
//   （ユーザーの指示で 0〜2Ω から広げた）。どちらの端でも I はほぼ変わらない＝I を変えるのは R と rA の比
//   実測（R ＝ 100Ω、S 入）：RS ＝ 20Ω で I 119.0mA・IA 113.9mA（n ＝ 1.04）、RS ＝ 0.1Ω で I 119.9mA・IA 12.0mA
const SH_RSMAX = 20;            // [Ω] RS のつまみの上限
// ★rA のつまみ：rA を R に近づけると S の入り切りで I 自体が跳ぶ（電流計が回路を乱す）。
//   I を変えるのは rA と R の比なので、R ではなく rA を回す（R のつまみは置いたが外した。
//   ユーザーの判断：R は固定でよい）。電流計の性質として回すほうが「計器の条件」として読める。
//   実測（RS ＝ 0.1Ω）：rA ＝ 100Ω で S 切 60.0mA → S 入 119.9mA（2倍）。rA ＝ 0.9Ω では ＋0.8%
const SH_RAMAX = 200;           // [Ω] rA のつまみの上限（R ＝ 100Ω を中ほどに入れる）
function demoShunt() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.0);
  const toSX = wx => (wx - cam.x) * cam.zoom + canvas.width / 2;
  const f = demoFitScale();
  // ★右の辺は 750（800 から詰めた）。右の列＝リモコン2とグラフの幅を広げるため
  const OX = fromSX(560 * f), X2 = fromSX(750 * f);
  const YA = fromSY(190 * f), OY = fromSY(310 * f), Y1 = fromSY(620 * f);
  const XP = OX + 50, XQ = X2 - 40, XC = (XP + XQ) / 2, YM = (OY + Y1) / 2;
  const YS = (YA + OY) / 2;       // S の中点の高さ
  // 上の辺（本線）：P まで → 電流計（1点目が＋端子＝左）→ Q から右の角へ
  add('wire', OX, OY, XP, OY);
  add('wire', XP, OY, XC - 40, OY);
  const am = add('ammeter', XC - 40, OY, XC + 40, OY, { r: SH_RA });
  add('wire', XC + 40, OY, XQ, OY);
  add('wire', XQ, OY, X2, OY);
  // 分流器の段：P から S を通って上がり、右へ RS、Q へ下りる
  add('wire', XP, OY, XP, YS + 25);
  const sw = add('switch', XP, YS + 25, XP, YS - 25, { closed: false });
  add('wire', XP, YS - 25, XP, YA);
  add('wire', XP, YA, XC - 45, YA);
  const rs = add('resistor', XC - 45, YA, XC + 45, YA, { R: SH_RS });
  add('wire', XC + 45, YA, XQ, YA);
  add('wire', XQ, YA, XQ, OY);
  // 右の辺・下の辺（負荷 R）・左の辺（電源。1点目が＋極＝上）
  add('wire', X2, OY, X2, Y1);
  add('wire', X2, Y1, XC + 50, Y1);
  const rl = add('resistor', XC - 50, Y1, XC + 50, Y1, { R: SH_R });
  add('wire', XC - 50, Y1, OX, Y1);
  add('wire', OX, Y1, OX, YM + 45);
  const src = add('dcsource', OX, YM - 45, OX, YM + 45, { V: SH_E, r: 0 });
  add('wire', OX, YM - 45, OX, OY);
  // ★電源の表の電流が測りたい電流 I。電流計の読み IA と RS の表の電流で I ＝ IA ＋ IS。
  //   RS の表は自動で段の上（札の反対側）に出る
  for (const e of [src, rs, rl]) addCircTable(e.id);

  const p = demoTextTopLeft();
  const NOTE = '電流計 A（内部抵抗 rA）に抵抗 RS を\n'
  + '並列につなぐと、電流の大部分は RS を通り、\n'
  + 'A にはその一部だけが流れる。この RS が分流器。\n'
  + '黄色い点は電流の向きに動き、速いほど電流が大きい。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・S が切れている間は、A の読み IA ＝ 電流 I\n'
  + '・S を入れると電流が分かれ、IA は I の一部になる\n'
  + '　（rA が R より十分小さいので、I はほぼ変わらない）\n'
  + '・A と RS は電圧が同じなので　IA·rA ＝ IS·RS\n'
  + '・I ＝ (1 ＋ rA／RS)·IA\n'
  + '・最大目盛りの n 倍まで測るには\n'
  + '　RS ＝ rA／(n − 1)\n'
  + '・rA を R に近づけると、S で I そのものが変わる\n'
  + '・RS ≫ rA では分かれず、RS ≪ rA では IA が小さすぎる';
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  const [ka, kv, ks] = dcKnobs([[am, 'r', SH_RAMAX], [src, 'V', DC_VMAX], [rs, 'R', SH_RSMAX]]);
  dcKnobAt(ks, rs, 'right', 0, X2);
  // rA と電源のつまみ：回路の左の外に縦に2枚（本文の下から）。★rA を上＝電流計の本線に近い側、
  //   電源を下＝電源の高さに寄せる。回路の右の列はグラフ、R の下は画面の下端で入らない。
  //   下端からはみ出さないよう下から押し戻す
  {
    const L = r => toSX(OX) - 40 - (r.panel.offsetWidth || 170);
    let top = noteBot + 6;
    if (ka) { dcPlaceRow([ka], L(ka), top); top += (ka.panel.offsetHeight || 180) + 6; }
    if (kv) dcPlaceRow([kv], L(kv), Math.min(top, canvas.height - (kv.panel.offsetHeight || 180) - 4));
  }
  // S の入り切り：S のすぐ左（ユーザーの指示）。
  //   ★dcKnobAt の 'left' で S の高さに中央をそろえると、窓の下端が輪の左上の角と本線に
  //     掛かった（実測）。窓の下端を本線より上に止め、右端は札「S」の手前で切る。
  //     左端は本文の長い行（画面 x≈395）の右に収まる
  const kw = addRemote('ghost', sw, 'circuit');
  if (kw) {
    kw.key = 'ArrowDown';
    const w = kw.panel.offsetWidth || 170, h = kw.panel.offsetHeight || 180;
    dcPlaceRow([kw], toSX(XP) - 36 - w, Math.min(toSY(YS) - h / 2, toSY(OY) - 8 - h));
  }
  // ── グラフ：電流計の電流−時間。RS のつまみ（リモコン2）の下、回路の右の外へ ──
  //   ★S を入れた瞬間に IA が 1/10 へ段になって落ちる。I は電源の表で読む（ほぼ変わらない）
  //   ★左下に置くと電源のつまみの下の空きが 130px しかなく見切れた（ユーザーの指摘）。
  //     幅はリモコン2と同じ列（右の導線より外）、高さは下端まで
  const g = circGraphOpen([am.id], { showV: false });
  if (g) {
    g.titleEl.textContent = '電流計の電流−時間';
    const EDGE = 10;
    const gl = ks ? ks.panel.offsetLeft : toSX(X2) + 16;
    const gt = ks ? ks.panel.offsetTop + ks.panel.offsetHeight + EDGE : toSY(OY);
    sizeDemoGraph(g, canvas.width - gl - EDGE, canvas.height - gt - EDGE - 14);
    g.panel.style.left = Math.round(gl) + 'px'; g.panel.style.right = 'auto';
    moveDemoGraphBottom(g);
  }

  dcNameLabel(rs, 'RS', ts);
  dcNameLabel(rl, 'R', ts);
  demoLabel(XP - 30 * ts, YS - 6 * ts, 'S', '#ffd54f', DEMO_NOTE_SIZE * ts, true);
  // ★値ではなく名前だけ（rA はつまみで変わる。値はつまみの窓で読む）
  demoLabel(XC - 8 * ts, OY + 40 * ts, 'rA', '#ffd54f', DEMO_NOTE_SIZE * ts, true);
  demoTitle(p.x, p.y, '分流器', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── 倍率器 ──────────────────────────────
//  分流器のデモと同じ構え。上の辺（本線）に測られる抵抗 R2、その上に張り出した段に
//  電圧計 V（内部抵抗 rV）と倍率器 RM を直列に渡し、R2 と並列にする。下の辺に R1、
//  左の辺に電源。S は RM を短絡するスイッチで、RM の真下に渡す。
//  つまみは電源・電圧計の内部抵抗 rV・RM、S は入り切りの窓。
//  ★電圧計は回路の電圧計（voltmeter）の内部抵抗 R を 10kΩ にしただけ。右パネルで手で同じにできる。
//    RM ＝ 90kΩ で V2 ＝ (1 ＋ RM/rV)·VV ＝ 10·VV。電圧計の読み（素子の横の数字）と R2 の表の
//    電圧を見くらべる。電圧計にも最大目盛りの概念は無い（振り切れない）ので、分流器と同じく
//    「最大目盛り」は式の説明にだけ使う
//  ★S は「入れる＝RM を短絡」。入れて始める＝まず電圧計だけで VV ＝ V2 を見て、切ると RM が入る。
//    分流器（S を入れると分流器が入る）とは入り切りの向きが逆になるが、倍率器は直列なので
//    「外す」には短絡するしかない（手で組むときも同じ）
//  ★分流器の rA ≪ R に対応する条件は rV ≫ R2。R1 ＝ R2 ＝ 100Ω、rV ＝ 10kΩ で
//    実測：S 入で VV ＝ V2 ＝ 5.970V、S 切で V2 ＝ 5.997V（＋0.5%）・VV ＝ 0.5997V（比 10.0）
const MP_E = 12, MP_R1 = 100, MP_R2 = 100, MP_RV = 10000, MP_RM = 90000;
// ★rV のつまみ：rV を R2 に近づけると S の入り切りで V2 自体が変わる（電圧計が回路を乱す）。
//   実測（RM ＝ 90kΩ）：rV ＝ 100Ω で S 入 V2 ＝ 4.00V → S 切 6.00V（＋50%）・VV ＝ 6.7mV
//   RM のつまみ：RM ≪ rV で分けず（n→1）、RM ≫ rV で読みが小さすぎる。どちらも 0〜200kΩ
//   実測（rV ＝ 10kΩ、S 切）：RM ＝ 100Ω で VV ＝ 5.91V（n ＝ 1.01）
const MP_RVMAX = 200000, MP_RMMAX = 200000;
function demoMultiplier() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.0);
  const toSX = wx => (wx - cam.x) * cam.zoom + canvas.width / 2;
  const f = demoFitScale();
  // ★寸法は分流器と同じ（右の列＝リモコンとグラフの幅を残す）
  const OX = fromSX(560 * f), X2 = fromSX(750 * f);
  // ★RM の段は分流器より 40px 高い（画面 150）。電圧計の段に S の段が重なるので、電圧計を
  //   本線寄りに下げ、読みの札を S の段から離す（190 のままだと札が S の段の導線に掛かった）
  const YA = fromSY(150 * f), OY = fromSY(310 * f), Y1 = fromSY(620 * f);
  const XP = OX + 50, XQ = X2 - 40, XC = (XP + XQ) / 2, YM = (OY + Y1) / 2;
  const YS = OY - 55;             // 電圧計の中点の高さ（本線寄り）
  const YB = YA + 45;             // S の段（RM の真下）
  // ★RM の段は P〜Q の 100px に S の段を抱えるので、RM は 60px・S は 40px に詰める。
  //   RM を 90px（分流器の RS と同じ）にすると、S の段の分かれ目が P より左へ出た（実測）
  const XL = XC - 42, XR = XC + 42;   // S の段が RM の段から分かれる点
  // 上の辺（本線）：P まで → R2 → Q から右の角へ
  add('wire', OX, OY, XP, OY);
  add('wire', XP, OY, XC - 45, OY);
  const r2 = add('resistor', XC - 45, OY, XC + 45, OY, { R: MP_R2 });
  add('wire', XC + 45, OY, XQ, OY);
  add('wire', XQ, OY, X2, OY);
  // 電圧計の段：P から電圧計（1点目が＋端子＝下＝電位の高い P の側）を通って上がり、
  //   右へ RM、Q へ下りる
  add('wire', XP, OY, XP, YS + 40);
  const vm = add('voltmeter', XP, YS + 40, XP, YS - 40, { R: MP_RV });
  add('wire', XP, YS - 40, XP, YA);
  add('wire', XP, YA, XL, YA);
  add('wire', XL, YA, XC - 30, YA);
  const rm = add('resistor', XC - 30, YA, XC + 30, YA, { R: MP_RM });
  add('wire', XC + 30, YA, XR, YA);
  add('wire', XR, YA, XQ, YA);
  add('wire', XQ, YA, XQ, OY);
  // S：RM の両端を短絡する段（入れて始める）
  add('wire', XL, YA, XL, YB);
  add('wire', XL, YB, XC - 20, YB);
  const sw = add('switch', XC - 20, YB, XC + 20, YB, { closed: true });
  add('wire', XC + 20, YB, XR, YB);
  add('wire', XR, YB, XR, YA);
  // 右の辺・下の辺（R1）・左の辺（電源。1点目が＋極＝上）
  add('wire', X2, OY, X2, Y1);
  add('wire', X2, Y1, XC + 50, Y1);
  const r1 = add('resistor', XC - 50, Y1, XC + 50, Y1, { R: MP_R1 });
  add('wire', XC - 50, Y1, OX, Y1);
  add('wire', OX, Y1, OX, YM + 45);
  const src = add('dcsource', OX, YM - 45, OX, YM + 45, { V: MP_E, r: 0 });
  add('wire', OX, YM - 45, OX, OY);
  // ★R2 の表の電圧が測りたい電圧 V2。電圧計の読み VV と RM の表の電圧で V2 ＝ VV ＋ VM。
  //   R2 の表は自動だと札の反対側＝S の段に掛かるので、輪の内側（R2 の名札の下）へ出す
  addCircTable(src.id); addCircTable(r1.id); addCircTable(rm.id);
  addCircTable(r2.id, 30, 85);

  const p = demoTextTopLeft();
  const NOTE = '電圧計 V（内部抵抗 rV）に抵抗 RM を\n'
  + '直列につなぐと、電圧の大部分は RM にかかり、\n'
  + 'V にはその一部だけがかかる。この RM が倍率器。\n'
  + '黄色い点は電流の向きに動き、速いほど電流が大きい。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・S が入っている間は RM が短絡され、\n'
  + '　V の読み VV ＝ R2 の電圧 V2\n'
  + '・S を切ると RM が入り、VV は V2 の一部になる\n'
  + '　（rV ≫ R2 なので、V2 はほぼ変わらない）\n'
  + '・V と RM は電流が同じ　VV／rV ＝ VM／RM\n'
  + '・V2 ＝ (1 ＋ RM／rV)·VV\n'
  + '・最大目盛りの n 倍まで測るには\n'
  + '　RM ＝ (n − 1)·rV\n'
  + '・rV を R2 に近づけると、S で V2 自体が変わる\n'
  + '・RM ≪ rV では分かれず、\n'
  + '　RM ≫ rV では VV が小さすぎる';
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  const [ka, kv, km] = dcKnobs([[vm, 'R', MP_RVMAX], [src, 'V', DC_VMAX], [rm, 'R', MP_RMMAX]]);
  dcKnobAt(km, rm, 'right', 0, X2);
  // rV と電源のつまみ：回路の左の外に縦に2枚（本文の下から）。分流器と同じ並び
  {
    const L = r => toSX(OX) - 40 - (r.panel.offsetWidth || 170);
    let top = noteBot + 6;
    if (ka) { dcPlaceRow([ka], L(ka), top); top += (ka.panel.offsetHeight || 180) + 6; }
    if (kv) dcPlaceRow([kv], L(kv), Math.min(top, canvas.height - (kv.panel.offsetHeight || 180) - 4));
  }
  // S の入り切り：電圧計の段の左上（本線より上）。分流器と同じ置き場。
  //   ★右端は電圧計の名札「rV」（P の左）の手前で切る
  const kw = addRemote('ghost', sw, 'circuit');
  if (kw) {
    kw.key = 'ArrowDown';
    const w = kw.panel.offsetWidth || 170, h = kw.panel.offsetHeight || 180;
    dcPlaceRow([kw], toSX(XP) - 40 - w, Math.min(toSY(YS) - h / 2, toSY(OY) - 8 - h));
  }
  // ── グラフ：電圧計の電圧−時間。RM のつまみの下、回路の右の外へ（分流器と同じ）──
  const g = circGraphOpen([vm.id], { showI: false });
  if (g) {
    g.titleEl.textContent = '電圧計の電圧−時間';
    const EDGE = 10;
    const gl = km ? km.panel.offsetLeft : toSX(X2) + 16;
    const gt = km ? km.panel.offsetTop + km.panel.offsetHeight + EDGE : toSY(OY);
    sizeDemoGraph(g, canvas.width - gl - EDGE, canvas.height - gt - EDGE - 14);
    g.panel.style.left = Math.round(gl) + 'px'; g.panel.style.right = 'auto';
    moveDemoGraphBottom(g);
  }

  dcNameLabel(rm, 'RM', ts);
  dcNameLabel(r2, 'R2', ts);
  dcNameLabel(r1, 'R1', ts);
  demoLabel(XC - 4 * ts, YB + 26 * ts, 'S', '#ffd54f', DEMO_NOTE_SIZE * ts, true);
  // ★値ではなく名前だけ（rV はつまみで変わる。値はつまみの窓で読む）
  demoLabel(XP - 30 * ts, YS + 6 * ts, 'rV', '#ffd54f', DEMO_NOTE_SIZE * ts, true);
  demoTitle(p.x, p.y, '倍率器', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── 電池の起電力と内部抵抗 ──────────────────────────────
//  内部抵抗 r の電池に、つまみ付きの抵抗 X を1つだけつなぐ。電池の端子電圧 V と電流 I を
//  回路グラフの〈電流−電圧〉で描くと、つまみを回して通った点が V ＝ E − rI の直線に並ぶ。
//  直線の傾きが −r、のばして縦軸（I ＝ 0）と交わる所が起電力 E。
//  ★グラフは縦横を入れ替えた向き（横＝I・縦＝V）で開く。教科書のこの実験の向きで、
//    傾きがそのまま −r になる。横＝V のままだと傾きは −1/r で、r が直接読めない。
//  ★グラフにするのは計器の読み：電流計（X と直列）と電圧計（電池の両端）。回路グラフは
//    電流計と電圧計を両方入れると読みを組にして1系列で描く（cgIVSeries）。どちらも理想の計器
//    （電流計 0Ω・電圧計 10MΩ）なので、読みは端子電圧と回路の電流そのもの。
//    ★計器の向き：電圧計は1点目（a）を＋極の側、電流計は1点目を電流が入ってくる側に置く。
//      逆に置くと読みが負になり、点が第4象限へ行く。
//  ★内部抵抗は電源の r で持たせる。別の抵抗を電池の横に並べると、それは「電池の中」ではなく
//    回路の一部に見える。
//  ★値は乾電池の見当：E ＝ 1.5V。r は教科書の実物（0.1〜0.5Ω 程度）より大きい 1Ω にした。
//    実物どおりだと V が E から1割も下がらず、直線の傾きが目で読めない（縮尺模型の水増し）。
//  ★X の可動域 0〜BAT_XMAX は、V が 0 付近から E の9割まで届く幅（X ＝ 9r で V ＝ 0.9E）。
//    下限は解く側の床 CIRCUIT_KNOB_RANGE.R.lo（0.1Ω）なので、両端とも軸には届かない＝
//    実験と同じく直線をのばして切片を読む。
//  ★実測（X を 0〜10Ω で掃引、202点）：電流計と電圧計の読みがどの点も V ＝ E − rI から 1.4e-7 V 以内
//    （電圧計の 10MΩ に流れるぶん。計器を入れる前の電池の読みは丸め誤差 2e-16 の範囲で一致していた）。
//    V は 0.14〜1.36V、I は 0.14〜1.36A を通る。
const BAT_E = 1.5, BAT_R = 1, BAT_X0 = 2;
const BAT_XMAX = 10;             // [Ω] X のつまみの上限
function demoBatteryEmf() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.1);
  const toSX = wx => (wx - cam.x) * cam.zoom + canvas.width / 2;
  // ★置き方は「電源と抵抗」がもと（X のつまみを上の辺の右へ出す）
  const f = demoFitScale();
  const OX = fromSX(555 * f), X2 = fromSX(810 * f);
  const OY = fromSY(150 * f), Y1 = fromSY(360 * f);   // ★X の表（上の辺の上）を上端の操作ヒントの帯より下へ
  // 左の辺に電池、そのすぐ右に電圧計（電池の両端＝上下の導線に渡す）、上の辺に X、
  //   右の辺に電流計（上から下へ流れる）。★電圧計を電池の左に出すと本文の下のグラフに掛かる
  const VX = OX + 70, XM = (VX + X2) / 2 + 10, YM = (OY + Y1) / 2;
  add('wire', OX, OY, VX, OY);
  add('wire', VX, OY, XM - 55, OY);
  const rx = add('resistor', XM - 55, OY, XM + 55, OY, { R: BAT_X0 });
  add('wire', XM + 55, OY, X2, OY);
  add('wire', X2, OY, X2, YM - 30);
  const am = add('ammeter', X2, YM - 30, X2, YM + 30);          // 1点目＝上＝電流が入る側
  add('wire', X2, YM + 30, X2, Y1);
  add('wire', X2, Y1, VX, Y1);
  add('wire', VX, Y1, OX, Y1);
  add('wire', VX, OY, VX, YM - 30);
  const vm = add('voltmeter', VX, YM - 30, VX, YM + 30);        // 1点目＝上＝＋極の側
  add('wire', VX, YM + 30, VX, Y1);
  add('wire', OX, Y1, OX, YM + 45);
  const src = add('dcsource', OX, YM - 45, OX, YM + 45, { V: BAT_E, r: BAT_R });
  add('wire', OX, YM - 45, OX, OY);
  // ★表は X だけ（抵抗値のつまみの読み）。電池の表は電圧計と場所が重なるうえ、読みは計器が出す
  addCircTable(rx.id);

  const p = demoTextTopLeft();
  const NOTE = '起電力 E・内部抵抗 r の電池に、つまみの付いた\n'
  + '抵抗 X をつないだ回路。電流計 A で電流 I を、\n'
  + '電圧計 V で電池の両端の電圧（端子電圧）V を測る。\n'
  + 'グラフは電流計の読み（横軸）と電圧計の読み（縦軸）。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '・X のつまみを端から端まで回して、点の跡を残す\n'
  + '・電流が流れると内部抵抗で rI だけ下がるので\n'
  + '　V ＝ E − rI、点は傾きが負の直線に並ぶ\n'
  + '・直線の傾きが −r（内部抵抗）\n'
  + '・直線をのばして縦軸と交わる所（I ＝ 0）が起電力 E';
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));

  // ── つまみ：X の右（上の辺の右端の外）──
  const [kx] = dcKnobs([[rx, 'R', BAT_XMAX]]);
  if (kx) dcPlaceRow([kx], toSX(X2) + 12, Math.max(56, toSY(OY) - (kx.panel.offsetHeight || 180) / 2));
  // ── グラフ：電流計と電圧計の読み。本文の下の空きいっぱい（回路の左の電池の札まで）──
  //   ★回路の下・右寄りに置くと、窓の下半分がチェックの行で埋まって点の描ける所が
  //     高さ 130px しか残らなかった（実測）。本文の下は幅も高さも取れる
  const g = circGraphOpen([am.id, vm.id], { iv: true, ivSwap: true });
  if (g) {
    g.titleEl.textContent = '電流計と電圧計の読み';
    const top = noteBot + 8, EDGE = 10;
    sizeDemoGraph(g, Math.floor(toSX(OX) - 40 - 2 * EDGE), Math.max(300, canvas.height - top - 14));
    moveDemoGraphLeft(g);
    moveDemoGraphBottom(g);
  }

  dcNameLabel(rx, 'X', ts);
  // ★電池の札は左（「1.5V」の下）。dcNameLabel の位置（素子の下）は縦の電池だと導線に掛かる
  demoLabel(OX - 62 * ts, YM + 14 * ts, 'E・r', '#ffd54f', DEMO_NOTE_SIZE * ts, true);
  demoTitle(p.x, p.y, '電池の起電力と内部抵抗', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── 非直線抵抗 ──────────────────────────────
//  電源 E（つまみ）・抵抗 R・豆電球の直列。豆電球の位置には、つまみ付きの抵抗 X の枝を
//  並べてあり、スイッチ2つで豆電球と X を差し替える。電流計（本線）と電圧計（豆電球／X の両端）
//  の読みを回路グラフの〈電流−電圧〉（横＝V・縦＝I）で描く。
//    ① 豆電球のまま E を 0 から上げる → 点の跡が豆電球の特性曲線（寝ていく曲線）
//    ② E を止めて X に替え、X を回す → 点の跡が直線 V ＝ E − RI（電池の内部抵抗のデモと同じ仕組み）
//    ③ 豆電球に戻す → 点は曲線と直線の交点に止まる
//  ★特性曲線は式で与えていない。豆電球はフィラメントの温度を状態に持ち、R(T) で抵抗が増える
//    （circuit.js の豆電球の★）。曲線はその結果として点の跡に出る。
//  ★差し替えは「同じキーの窓2つ」で作る。初めを 豆電球＝入・X＝切 にしておけば、キーを押すたびに
//    両方が反転して、二者択一のスイッチとして働く（平行板コンデンサーの S1 と同じ手）。
//    窓のボタンを押すと片方だけ変わる。両方入ると並列、両方切れると電流 0 ＝ 点は (E, 0)。
//  ★豆電球は熱の遅れなし（τ ＝ 0。右パネルの「熱の時定数」を 0 にしたもの）。電流と電圧はいつも
//    特性曲線の上に来て、E を回す速さで曲線の形が変わらない。突入電流は出ない（③で豆電球に
//    戻すと、点は交点へ一度に跳ぶ）。
//    既定の 0.12秒のままだと低い電圧で温度が追いつかず、点の跡が回す速さで変わる。
//    豆電球の冷め方が放射だけだったころは、E を 0→5V で上げたとき V ＝ 0.25V の I が
//    10秒 0.183A・20秒 0.153A・2分 0.093A（十分待つと 0.077A）。伝導の項を足した今でも、
//    20秒で上げて V ≧ 0.5V の電流が静特性から最大 24% 外れる（circuit.js の bulbLoss の★）。
//    τ ＝ 0 では 1秒で回しても 20秒で回しても、どの点も特性曲線から 0.3μA 以内。
//  ★実測（τ ＝ 0）：E ＝ 3V で交点 1.75V・0.249A、E ＝ 4V で 2.50V・0.300A（定格）。
//    X の直線は V ＝ E − RI から 0.6mV 以内。
//  ★R ＝ 5Ω は E ＝ 4V のとき交点がちょうど定格（2.5V・0.3A）に来る値（2.5 ＋ 5×0.3 ＝ 4）。
//    E の上限 NLR_EMAX ＝ 5V では豆電球は定格を少し越えるが、融点（切れる）にはまだ遠い。
//  ★X の可動域 0〜NLR_XMAX は、直線の V ＝ 0 付近から E の9割近くまで届く幅。
const NLR_R = 5, NLR_X0 = 5;
const NLR_TAU = 0;               // [s] 豆電球の熱の時定数。0 ＝ 熱の遅れなし（上の★）
const NLR_EMAX = 5;              // [V] E のつまみの上限
const NLR_XMAX = 40;             // [Ω] X のつまみの上限（X ＝ 40 で V ＝ 0.89E）
function demoNonlinearResistor() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.1);
  const toSX = wx => (wx - cam.x) * cam.zoom + canvas.width / 2;
  const f = demoFitScale();
  const SX = x => fromSX(x * f), SY = y => fromSY(y * f);
  // 画面 px で組む。左の辺に電源、上の辺に R、そのあと 電圧計・豆電球の枝・X の枝 の3本を
  //   上下の導線に渡す。電流計は下の導線（右から左へ流れる向きに1点目＝右）。
  //   ★T字の分かれ目は導線の端点で作る（端点どうしが近いとノードになる。途中の点には付かない）
  const OX = SX(545), RA = SX(572), RB = SX(642), VX = SX(672), BX = SX(740), XX = SX(815);
  const AA = SX(640), AB = SX(585);
  const OY = SY(150), Y1 = SY(400), YM = (OY + Y1) / 2;
  const SWA = SY(175), SWB = SY(225), EA = SY(275), EB = SY(345);
  add('wire', OX, OY, RA, OY);
  const rr = add('resistor', RA, OY, RB, OY, { R: NLR_R });
  add('wire', RB, OY, VX, OY); add('wire', VX, OY, BX, OY); add('wire', BX, OY, XX, OY);
  add('wire', XX, Y1, BX, Y1); add('wire', BX, Y1, VX, Y1); add('wire', VX, Y1, AA, Y1);
  const am = add('ammeter', AA, Y1, AB, Y1);                     // 1点目＝右＝電流が入る側
  add('wire', AB, Y1, OX, Y1);
  add('wire', VX, OY, VX, YM - 28);
  const vm = add('voltmeter', VX, YM - 28, VX, YM + 28);         // 1点目＝上＝高い側
  add('wire', VX, YM + 28, VX, Y1);
  const branch = (x, part) => {
    add('wire', x, OY, x, SWA);
    const sw = add('switch', x, SWA, x, SWB);
    add('wire', x, SWB, x, EA);
    const e = part(x);
    add('wire', x, EB, x, Y1);
    return [sw, e];
  };
  const [swB, bulb] = branch(BX, x => add('bulb', x, EA, x, EB, { tau: NLR_TAU }));
  const [swX, rx]   = branch(XX, x => add('resistor', x, EA, x, EB, { R: NLR_X0 }));
  swB.closed = true; swX.closed = false;
  add('wire', OX, Y1, OX, YM + 45);
  const src = add('dcsource', OX, YM - 45, OX, YM + 45, { V: 0, r: 0 });   // 1点目が＋極＝上
  add('wire', OX, YM - 45, OX, OY);
  markCircuitDiscontinuity(false);

  const p = demoTextTopLeft();
  const NOTE = '豆電球（非直線抵抗）に抵抗 R を直列につなぎ、\n'
  + '電源 E につないだ回路。電流計と電圧計で豆電球の\n'
  + '電流 I と電圧 V を測り、グラフに点の跡を残す。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '① E のつまみを 0 から上げる。点の跡は\n'
  + '　曲線になる（特性曲線）。熱くなるほど抵抗が\n'
  + '　増えるので、曲線はしだいに寝ていく\n'
  + '② E を止め、キー 1 で豆電球を X に切り替えて\n'
  + '　X のつまみを回す。点の跡は直線 V ＝ E − RI\n'
  + '③ キー 1 で豆電球に戻す。点は曲線と直線の\n'
  + '　交点に止まる＝実際に流れる電流と電圧';
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));

  // ── 操作の窓 ──
  //   ★右の列（X の枝の右）に X の切り替えと X のつまみ、回路の下に E のつまみと豆電球の切り替え。
  //     それぞれ相手の素子のすぐ近くに置き、つなぎ線を短くする
  const [kE, kX] = dcKnobs([[src, 'V', NLR_EMAX], [rx, 'R', NLR_XMAX]]);
  const rB = addRemote('ghost', swB, 'circuit');
  const rX = addRemote('ghost', swX, 'circuit');
  for (const r of [rB, rX]) if (r) { r.key = 'Digit1'; syncRemotePanel(r); }
  const GAP = 8, right = toSX(XX) + 22;
  const hOf = r => r ? (r.panel.offsetHeight || 150) : 0;
  let y = 56;
  if (rX) { dcPlaceRow([rX], right, y); y += hOf(rX) + GAP; }
  if (kX) dcPlaceRow([kX], right, Math.max(y, toSY((EA + EB) / 2) - hOf(kX) / 2));
  const rowTop = toSY(Y1) + 34;
  const row = [kE, rB].filter(Boolean);
  dcPlaceRow(row, toSX(OX) - 20, rowTop);

  // ── グラフ：電流計と電圧計の読み。本文の下の空きいっぱい ──
  const g = circGraphOpen([am.id, vm.id], { iv: true });
  if (g) {
    g.titleEl.textContent = '電流計と電圧計の読み';
    const top = noteBot + 8, EDGE = 10;
    sizeDemoGraph(g, Math.floor(toSX(OX) - 40 - 2 * EDGE), Math.max(300, canvas.height - top - 14));
    moveDemoGraphLeft(g);
    moveDemoGraphBottom(g);
  }

  dcNameLabel(rr, 'R', ts);
  // ★X の札は左（値の札「5Ω」の下）。右は X の窓が来る
  demoLabel(XX - 34 * ts, (EA + EB) / 2 + 10 * ts, 'X', '#ffd54f', DEMO_NOTE_SIZE * ts, true);
  demoLabel(OX - 44 * ts, YM + 14 * ts, 'E', '#ffd54f', DEMO_NOTE_SIZE * ts, true);
  demoTitle(p.x, p.y, '非直線抵抗', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── 電位差計 ──────────────────────────────
//  一様な抵抗線 AB（すべり抵抗・長さ 100cm）に電池 E0 と抵抗 Rh で一定の電流を流し、
//  A と接点 P のあいだの電圧を、検流計 G を通して電池の起電力とくらべる。
//    ① 標準電池 Es をつなぎ、P を動かして G の電流が 0 になる長さ ℓs を読む
//    ② キー 1 で未知の電池 Ex に替え、同じく ℓx を読む → Ex ＝ Es·ℓx/ℓs
//    ③ キー 2 で電圧計を Ex につなぐ → 電圧計は E − rI（電池に電流が流れる）
//  ★つりあいでは G にも電池にも電流が流れない。だから内部抵抗 r の電圧降下が 0 で、
//    起電力そのものを測れる（電池の起電力と内部抵抗のデモと対になる題材）。
//    ③で電圧計をつなぐと、電圧計に流れるぶん電池に電流が流れて端子電圧が下がる。
//    P のつりあいの位置もその端子電圧のところへずれる（電圧計が測定を乱す、も見える）。
//  ★抵抗線は新しく足した「すべり抵抗」（回路ツールから置ける 3 端子の素子）。接点の端子 c は
//    抵抗線の中点の下に固定で、P へはリード線が伸びる。P のつまみはリモコンの〈接点の位置〉。
//  ★倍率 2 は抵抗線 100cm（＝100px）を画面 200px にするため。回路の座標は基準画面の px で
//    組むので、倍率 2 のとき 200px がちょうど 100cm になる（端 B は A から 100 を足して置く）。
//  ★値：E0 ＝ 3V・Rh ＝ 5Ω・抵抗線 10Ω → 抵抗線の電流 0.2A、1cm あたり 0.02V。
//    Es ＝ 1.02V（標準電池＝ウェストン電池の 1.0186V を 2 桁に丸めた値）→ ℓs ＝ 51.0cm、
//    Ex ＝ 1.5V → ℓx ＝ 75.0cm。
//  ★Ex の内部抵抗 r ＝ 1Ω と電圧計の内部抵抗 10Ω は水増し（実物は r が 0.1Ω 前後、電圧計は
//    数 kΩ 以上）。実物の比のままだと電圧計の読みが Ex と 3 桁目まで同じになり、差が見えない。
//    電圧計の読みは 1.5 × 10/11 ＝ 1.36V。
//  ★差し替えは非直線抵抗のデモと同じ「同じキーの窓 2 つ」（S1＝入・S2＝切 から始める）。
//  ★実測（P を二分法で動かして G の電流の符号が変わる位置）：ℓs ＝ 51.003cm（理論 51.0）、
//    ℓx ＝ 75.005cm（理論 75.0）→ Es·ℓx/ℓs ＝ 1.50001V。S3 を入れると ℓ ＝ 68.186cm（理論 1.5×10/11÷0.02
//    ＝ 68.18）、そのときの電圧計 1.3636V・Ex の電流 0.1364A。P ＝ 30cm（初め）の G は 0.175A。
const PM_E0 = 3, PM_RH = 5, PM_RW = 10;   // [V]・[Ω]・[Ω] 電池 E0・抵抗 Rh・抵抗線の全体
const PM_ES = 1.02, PM_EX = 1.5, PM_RX = 1;   // [V]・[V]・[Ω]
const PM_RV = 10;                          // [Ω] 電圧計の内部抵抗（上の★）
const PM_P0 = 30;                          // [cm] 接点の初めの位置（つりあいから外しておく）
const PM_RHMAX = 20;                       // [Ω] Rh のつまみの上限
function demoPotentiometer() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(2.0);
  const f = demoFitScale();
  const SX = x => fromSX(x * f), SY = y => fromSY(y * f);
  // 基準画面の px で組む。上の辺＝E0 と Rh、中段＝抵抗線 AB、下の2段＝Es と Ex の枝、
  //   いちばん下＝電圧計の枝。★端点どうしは 10cm（画面 20px）より離す（近いと1つのノードに縮む）
  const AX = SX(590), BX = AX + 100, XR = BX;          // 抵抗線の両端（ちょうど 100cm）
  const YT = SY(160), YW = SY(250), Y1 = SY(440), Y2 = SY(520), Y3 = SY(600);
  const XS0 = AX, XS1 = SX(630), XE0 = SX(650), XE1 = SX(730), XV = SX(760), XVS = SX(695);
  // 上の辺：E0（＋極＝左）→ 左へ回って A、抵抗線を A→B、B から上がって Rh を通り E0 の−極へ
  add('wire', AX, YW, AX, YT);
  add('wire', AX, YT, SX(620), YT);
  const e0 = add('dcsource', SX(620), YT, SX(680), YT, { V: PM_E0, r: 0 });
  add('wire', SX(680), YT, SX(710), YT);
  const rh = add('resistor', SX(710), YT, SX(770), YT, { R: PM_RH });
  add('wire', SX(770), YT, XR, YT);
  add('wire', XR, YT, BX, YW);
  const sw = add('slidewire', AX, YW, BX, YW, { R: PM_RW, pos: PM_P0 / 100, cOff: 40 });
  const C = slideWireC(sw);
  // 接点の端子 c → 検流計 G（上→下を正）→ 右の縦の導線へ
  const g = add('ammeter', C.x, C.y, C.x, SY(390), { r: 0 });
  add('wire', C.x, SY(390), XR, SY(390));
  add('wire', XR, SY(390), XR, Y1);
  add('wire', XR, Y1, XR, Y2);
  // 左の縦の導線：A から下の2段へ
  add('wire', AX, YW, AX, Y1);
  add('wire', AX, Y1, AX, Y2);
  // Es と Ex の枝（＋極＝左＝A の側。A の電位が高いので、つりあいで V_A − V_P ＝ E）
  const branch = (y, E, r) => {
    const s = add('switch', XS0, y, XS1, y);
    add('wire', XS1, y, XE0, y);
    const cell = add('dcsource', XE0, y, XE1, y, { V: E, r });
    return [s, cell];
  };
  const [s1, es] = branch(Y1, PM_ES, 0);
  add('wire', XE1, Y1, XR, Y1);
  const [s2, ex] = branch(Y2, PM_EX, PM_RX);
  add('wire', XE1, Y2, XV, Y2);                 // ★電圧計の戻りのために XV で切っておく
  add('wire', XV, Y2, XR, Y2);
  s1.closed = true; s2.closed = false;
  // 電圧計の枝：Ex の＋極から下りて S3・電圧計、Ex の−極の側（XV）へ戻る
  add('wire', XE0, Y2, XE0, Y3);
  const s3 = add('switch', XE0, Y3, XVS, Y3);
  s3.closed = false;
  const vm = add('voltmeter', XVS, Y3, XV, Y3, { R: PM_RV });   // 1点目＝左＝＋極の側
  add('wire', XV, Y3, XV, Y2);
  markCircuitDiscontinuity(false);

  const p = demoTextTopLeft();
  const NOTE = '一様な抵抗線 AB に電池 E0 で電流を流し、\n'
  + 'A と接点 P のあいだの電圧を、検流計 G を通して\n'
  + '電池の起電力とくらべる（電位差計）。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '① 接点のつまみで P を動かし、G の読みが 0 に\n'
  + '　なる長さ ℓs を読む（Es：標準電池）\n'
  + '② キー 1 で Ex（未知の電池）に替え、同じく ℓx\n'
  + '　を読む。Ex ＝ Es × ℓx ÷ ℓs\n'
  + '・つりあいでは電池に電流が流れないので、\n'
  + '　内部抵抗があっても起電力そのものが測れる\n'
  + '③ キー 2 で電圧計を Ex につなぐ。電流が流れ、\n'
  + '　読みは起電力より小さい V ＝ E − rI になる';
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));

  // ── 操作の窓 ──
  //   本文の下に2段：上の段に 接点・Rh のつまみ、下の段に S1・S2・S3 のキーの窓。
  //   ★回路の右の列に縦に積むと、キーの窓3枚（1枚およそ 150px）が画面の下からはみ出した
  const [kP, kR] = dcKnobs([[sw, 'pos', 100], [rh, 'R', PM_RHMAX]]);
  const r1 = addRemote('ghost', s1, 'circuit');
  const r2 = addRemote('ghost', s2, 'circuit');
  const r3 = addRemote('ghost', s3, 'circuit');
  for (const r of [r1, r2]) if (r) { r.key = 'Digit1'; syncRemotePanel(r); }
  if (r3) { r3.key = 'Digit2'; syncRemotePanel(r3); }
  const row1 = [kP, kR].filter(Boolean), row2 = [r1, r2, r3].filter(Boolean);
  const LEFT = 60;                                  // ★窓の左端の下限は 56px（placeRemotePanel）。20 だと押し戻されて隣と重なる
  dcPlaceRow(row1, LEFT, noteBot + 8);
  const h1 = Math.max(0, ...row1.map(r => r.panel.offsetHeight || 170));
  dcPlaceRow(row2, LEFT, noteBot + 8 + h1 + 8);

  // ── 札 ──
  const LC = '#ffd54f', LS = DEMO_NOTE_SIZE * ts;
  demoLabel(AX - 22 * ts, YW - 8 * ts, 'A', LC, LS, true);
  demoLabel(BX + 8 * ts, YW - 8 * ts, 'B', LC, LS, true);
  demoLabel((e0.ax + e0.bx) / 2 - 12 * ts, YT - 30 * ts, 'E0', LC, LS, true);
  demoLabel((rh.ax + rh.bx) / 2 - 12 * ts, YT - 30 * ts, 'Rh', LC, LS, true);
  demoLabel(C.x + 16 * ts, (g.ay + g.by) / 2 - 8 * ts, 'G', LC, LS, true);
  demoLabel((es.ax + es.bx) / 2 - 10 * ts, Y1 - 36 * ts, 'Es', LC, LS, true);
  demoLabel((ex.ax + ex.bx) / 2 - 10 * ts, Y2 - 36 * ts, 'Ex', LC, LS, true);
  demoLabel((s1.ax + s1.bx) / 2 - 10 * ts, Y1 + 12 * ts, 'S1', LC, LS, true);
  demoLabel((s2.ax + s2.bx) / 2 - 10 * ts, Y2 + 12 * ts, 'S2', LC, LS, true);
  demoLabel((s3.ax + s3.bx) / 2 - 10 * ts, Y3 + 12 * ts, 'S3', LC, LS, true);
  demoTitle(p.x, p.y, '電位差計', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ── ダイオード（順方向と逆方向）─────────────────────────────────
//  向きを逆にした直流電源 E1・E2 を並べ、スイッチ S1・S2 でどちらか一方をダイオードと抵抗 R の
//  直列につなぐ。E1 はダイオードに順方向、E2 は逆方向の電圧をかける。
//    ① E1 のまま電圧のつまみを 0 から上げる → 点の跡が順方向の特性曲線（0.6V ほどから急に立つ）
//    ② キー 1 で E2 に切り替えて、つまみを回す → 電流はほぼ 0（点は電圧が負の側の横線）
//  ★交流は使わない。ダイオードを習う時点ではまだ交流を習っていないため（交流で掃いて
//    特性曲線と半波整流を1度に見せる版を先に作ったが、単元の順に合わないので改めた）。
//  ★切り替えは「同じキーの窓2つ」（非直線抵抗・自己誘導と同じ手）。初めを S1＝入・S2＝切
//    にしておけば、キーを押すたびに両方が同じ tick で反転する。窓のボタンで片方だけ入れると
//    E1 と E2 が逆向きに並列になって短絡する（非直線抵抗の「両方入ると並列」と同じ）。
//  ★電圧のつまみは1台で E1・E2 の両方を受け持つ（窓の〈＋〉で相手を足したのと同じ）。
//    どちらにつないでも同じ大きさの電圧で、向きだけが違う＝比べるのは向きだけになる。
//  ★特性曲線は式で描いていない：ダイオードは Shockley の式 I = Is(e^(V/nVt) − 1) で解いている
//    （circuit.js の★）。立ち上がりも逆方向で流れないのも、そこから出る。
//  ★値：R ＝ 10Ω・Vf ＝ 0.7V（シリコン）・つまみ 0〜5V。5V の順方向で電流 0.42A 前後。
//  ★実測（つまみを上げて 5 tick 待つ。ダイオードの電圧・電流）：
//      E1（順方向） 0.5V … 0.498V・0.2mA   0.7V … 0.644V・5.6mA   1V … 0.715V・28mA
//                   2V … 0.779V・122mA    5V … 0.833V・417mA（(5 − 0.833)/10 ＝ 0.417A）
//      E2（逆方向） 0.5〜5V … ダイオードの電圧がそのまま −E、電流 −2.4nA（行列を支える Gmin の漏れ）
const DIO_R = 10;           // [Ω]
const DIO_EMAX = 5;         // [V]  電圧つまみの上限
function demoDiode() {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.1);
  const toSX = wx => (wx - cam.x) * cam.zoom + canvas.width / 2;
  const f = demoFitScale();
  const SX = x => fromSX(x * f), SY = y => fromSY(y * f);
  // 画面 px で組む。左に E1・E2 の枝を2本（上下の導線に渡す）、上の辺にダイオード
  //   （1点目＝左＝アノード）、右の辺に R。電流の正の向きは時計回り。
  //   ★T字の分かれ目は導線の端点で作る（非直線抵抗と同じ）
  const XA = SX(545), XB = SX(625), DA = SX(665), DB = SX(745), X2 = SX(815);
  const OY = SY(150), Y1 = SY(400), YM = (OY + Y1) / 2;
  const SWA = SY(175), SWB = SY(225), EA = SY(275), EB = SY(345);
  add('wire', XA, OY, XB, OY); add('wire', XB, OY, DA, OY);
  const dio = add('diode', DA, OY, DB, OY, { Vf: 0.7 });
  add('wire', DB, OY, X2, OY);
  add('wire', X2, OY, X2, YM - 45);
  const res = add('resistor', X2, YM - 45, X2, YM + 45, { R: DIO_R });
  add('wire', X2, YM + 45, X2, Y1);
  add('wire', X2, Y1, XB, Y1); add('wire', XB, Y1, XA, Y1);
  // 枝：上から スイッチ → 電源。plusTop が真なら＋極が上（順方向）
  const branch = (x, plusTop) => {
    add('wire', x, OY, x, SWA);
    const sw = add('switch', x, SWA, x, SWB);
    add('wire', x, SWB, x, EA);
    const e = plusTop ? add('dcsource', x, EA, x, EB, { V: 0, r: 0 })    // 1点目が＋極
                      : add('dcsource', x, EB, x, EA, { V: 0, r: 0 });
    add('wire', x, EB, x, Y1);
    return [sw, e];
  };
  const [s1, e1] = branch(XA, true);
  const [s2, e2] = branch(XB, false);
  s1.closed = true; s2.closed = false;
  markCircuitDiscontinuity(false);
  for (const e of [dio, res]) addCircTable(e.id);

  const p = demoTextTopLeft();
  const NOTE = 'ダイオードと抵抗 R を直列にして、電源につないだ回路。\n'
  + 'E1 と E2 は向きが逆で、キー 1 でどちらか一方に\n'
  + '切り替わる。E1 はダイオードの矢印の向き（順方向）、\n'
  + 'E2 は逆向き（逆方向）に電圧をかける。\n'
  + '\n'
  + '【手順】▶実行 を押す\n'
  + '① E1 のまま、電圧のつまみを 0 から上げる。\n'
  + '　0.6V ほどまではほとんど流れず、越えると\n'
  + '　急に流れる（グラフの点の跡）\n'
  + '② キー 1 で E2 に切り替えて、つまみを回す。\n'
  + '　電圧を上げても電流はほぼ 0\n'
  + '・ダイオードは一方の向きにしか電流を通さない';
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));

  // ── 操作の窓：回路の下に 電圧のつまみ・S1・S2 を横1列、右端にそろえる ──
  //   ★回路の左端から並べると3枚目が画面の右端で押し戻されて2枚目に重なった（実測）
  const kE = addRemote('prop', e1, 'circuit', [e1.id, e2.id]);
  if (kE) { kE.prop = 'V'; kE.lo = 0; kE.hi = DIO_EMAX; }
  const r1 = addRemote('ghost', s1, 'circuit');
  const r2 = addRemote('ghost', s2, 'circuit');
  for (const r of [r1, r2]) if (r) { r.key = 'Digit1'; syncRemotePanel(r); }
  const row = [kE, r1, r2].filter(Boolean);
  const EDGE = 10;
  const rowW = row.reduce((w, r) => w + (r.panel.offsetWidth || 170) + 6, -6);
  const rowLeft = canvas.width - EDGE - rowW;
  dcPlaceRow(row, rowLeft, toSY(Y1) + 34);

  // ── グラフ：ダイオードの電流−電圧。本文の下の空きいっぱい ──
  const g = circGraphOpen([dio.id], { iv: true });
  if (g) {
    g.titleEl.textContent = 'ダイオードの電流−電圧';
    // ★幅は操作の窓の列の左まで（回路の左端までにすると窓と重なる）
    const top = noteBot + 8;
    sizeDemoGraph(g, Math.floor(Math.min(toSX(XA) - 40, rowLeft) - 2 * EDGE), Math.max(300, canvas.height - top - 14));
    moveDemoGraphLeft(g);
    moveDemoGraphBottom(g);
  }

  dcNameLabel(res, 'R', ts);
  const LC = '#ffd54f', LS = DEMO_NOTE_SIZE * ts;
  demoLabel(XA - 44 * ts, (EA + EB) / 2 + 10 * ts, 'E1', LC, LS, true);
  demoLabel(XB + 14 * ts, (EA + EB) / 2 + 10 * ts, 'E2', LC, LS, true);
  demoLabel(XA - 44 * ts, (SWA + SWB) / 2 + 10 * ts, 'S1', LC, LS, true);
  demoLabel(XB + 14 * ts, (SWA + SWB) / 2 + 10 * ts, 'S2', LC, LS, true);
  demoTitle(p.x, p.y, 'ダイオード', DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
}

// ════════════════════════════════════════
//  交流の直列回路（RL・RC・RLC）
// ════════════════════════════════════════
//  交流電源に抵抗・コイル・コンデンサーを一列につなぐ（記号の回路）。3つとも同じ組み立て
//  （acSeriesBuild）で、入れる素子だけが違う。
//  ★読むのは回路グラフの段積み＋フェーザ図（1段＝1素子）。各段の V と I の矢印のなす角が
//    その素子の位相差で、抵抗 0°・コイル +90°・コンデンサー −90° が段の中で読める。
//    電源の段の角が回路全体の位相差 tanφ ＝ (ωL − 1/ωC)/R。電流の矢印は全段で同じ向き
//    （直列なので電流はどこも同じ）。
//  ★つまみの主役は電源の振動数。リアクタンス ωL・1/ωC は振動数で変わるのに、それを回す
//    手段が右パネルしか無かったので、交流電源のリモコンに〈振動数〉を足した。回しても位相が
//    跳ねないよう、交流電源の位相は acSourceTheta で引き継ぐ。
//  ★電源は内部抵抗0（理想）。直列の R が投入時の直流分を減衰させるので、理想電源でも
//    フェーザ図は出る（CIRCUIT_DEFAULTS の★は R の無い回路の話）。
//  ★値は「時定数が振動の周期より十分短い」組にしてある。フェーザ図は定常になってから
//    （2周期ぶん記録してから）しか出ないので、過渡が長いと待たされる。
//    RL：τ ＝ L/R ＝ 0.2秒、RC：τ ＝ RC ＝ 0.05秒、RLC：包絡線の τ ＝ 2L/R ＝ 0.4秒。
//  ★実測（つまみで振動数を変えて 6秒回したあとのフェーザ図。電源の段の φ・電流の振幅／理論）：
//      RL  0.5/1/2 Hz … φ 32.14/51.49/68.31°（理論 32.14/51.49/68.30）、I 1.693/1.244/0.735 A（理論 1.694/1.245/0.739）
//      RC  0.5/1/2 Hz … φ −81.07/−72.56/−57.85°（理論 −81.07/−72.56/−57.86）、I 0.310/0.599/1.058 A（理論 0.310/0.599/1.064）
//      RLC 1/1.59/2.5 Hz … φ −62.56/0.03/61.84°（理論 −62.57/0/61.84）、I 0.920/1.993/0.935 A（理論 0.921/2.000/0.944）
//    どの素子の段も R 0°・L 90°・C −90° ちょうど。電流の振幅が理論より 0.1〜0.9% 小さいのは
//    グラフの直交検波の癖（1 tick ごとの標本を線形補間するので振幅が cos(πf/60) 倍になる。
//    電源の電圧も同じだけ小さく出る＝回路は正しい）。
//  ★振動数を変えた直後の電源の電圧の段（1 tick）：1.3V 以下（RLC で 1→1.3Hz、変える時刻3通り）。
//    位相を引き継ぐ前は 8〜12V 跳ねていた。フェーザ図が戻るまで 2.6秒（前は 3.1秒）。
const ACS_V = 10;          // [V]  振幅
const ACS_F = 1;           // [Hz] 振動数の初期値（周期1秒。波形の山が目で追える速さ）
const ACS_R = 5;           // [Ω]
const ACS_L = 1;           // [H]  ωL ＝ 6.3Ω（1Hz）
const ACS_C = 0.01;        // [F]  1/ωC ＝ 15.9Ω（1Hz）。RLC の共振 f0 ＝ 1/(2π√LC) ＝ 1.59Hz
const ACS_FMAX = 3;        // [Hz] 振動数つまみの上限（RLC の共振 1.59Hz を中ほどに入れる）
const ACS_RMAX = 20, ACS_LMAX = 3, ACS_CMAX = 50;   // つまみの上限 [Ω]・[H]・[mF]
//  kinds：'R'・'L'・'C' を並べた順に、上の辺・右の辺・下の辺へ置く
function acSeriesBuild(kinds, title, NOTE) {
  const { ts, fromSX, fromSY, toSY, add } = dcBegin(1.0);
  const toSX = wx => (wx - cam.x) * cam.zoom + canvas.width / 2;
  const f = demoFitScale();
  const OX = fromSX(290 * f), X2 = fromSX(500 * f);
  const OY = fromSY(300 * f), Y1 = fromSY(470 * f);
  const XM = (OX + X2) / 2, YM = (OY + Y1) / 2;
  const HL = 45;                       // 素子の半分の長さ
  // 電源：左の辺（1点目が＋極＝上）
  add('wire', OX, OY, OX, YM - HL);
  const src = add('acsource', OX, YM - HL, OX, YM + HL, { V: ACS_V, freq: ACS_F, r: 0 });
  add('wire', OX, YM + HL, OX, Y1);
  // ★どの素子も時計回り（電流の正の向き）に a→b をそろえる
  const TYPE = { R: ['resistor', { R: ACS_R }], L: ['inductor', { L: ACS_L }], C: ['capacitor', { C: ACS_C }] };
  const edges = [
    [OX, OY, X2, OY],     // 上の辺（左→右）
    [X2, OY, X2, Y1],     // 右の辺（上→下）
    [X2, Y1, OX, Y1],     // 下の辺（右→左）
  ];
  const parts = {};
  edges.forEach(([ax, ay, bx, by], k) => {
    const kind = kinds[k];
    if (!kind) { add('wire', ax, ay, bx, by); return; }
    const L = Math.hypot(bx - ax, by - ay), ux = (bx - ax) / L, uy = (by - ay) / L;
    const mx = (ax + bx) / 2, my = (ay + by) / 2;
    add('wire', ax, ay, mx - ux * HL, my - uy * HL);
    const [type, o] = TYPE[kind];
    parts[kind] = add(type, mx - ux * HL, my - uy * HL, mx + ux * HL, my + uy * HL, o);
    add('wire', mx + ux * HL, my + uy * HL, bx, by);
  });

  const p = demoTextTopLeft();
  const noteY = p.y + 54 * ts;
  const noteBot = toSY(demoNoteBelow(noteY, NOTE, 0, DEMO_NOTE_SIZE * ts));
  // ── リモコン：電源の振動数は電源の左、素子のつまみは回路の下に横1列 ──
  const kf = addRemote('prop', src, 'circuit');
  if (kf) { kf.prop = 'freq'; kf.lo = 0; kf.hi = ACS_FMAX; }
  dcKnobAt(kf, src, 'left', noteBot + 6);
  const HI = { R: ACS_RMAX, L: ACS_LMAX, C: ACS_CMAX }, PROP = { R: 'R', L: 'L', C: 'C' };
  const ks = kinds.filter(Boolean).map(kd => {
    const r = addRemote('prop', parts[kd], 'circuit');
    if (r) { r.prop = PROP[kd]; r.lo = 0; r.hi = HI[kd]; }
    return r;
  }).filter(Boolean);
  const kTop = Math.max(toSY(Y1) + 40, kf ? kf.panel.offsetTop + kf.panel.offsetHeight + 8 : 0);
  dcPlaceRow(ks, 56, Math.min(kTop, canvas.height - 190));
  // ── グラフ：電源と各素子の段積み＋フェーザ図。つまみの列の右から右端まで・縦いっぱい ──
  const remRight = Math.max(toSX(X2) + 40, ...[kf, ...ks].filter(Boolean)
    .map(r => r.panel.offsetLeft + r.panel.offsetWidth));
  const pins = [src, ...kinds.filter(Boolean).map(kd => parts[kd])].map(e => e.id);
  const g = circGraphOpen(pins, { showPhasor: true });
  if (g) {
    const EDGE = 10, gl = remRight + EDGE, gt = 60;
    sizeDemoGraph(g, canvas.width - gl - EDGE, canvas.height - gt - EDGE - 14);
    g.panel.style.left = Math.round(gl) + 'px'; g.panel.style.right = 'auto';
    moveDemoGraphBottom(g);
  }

  for (const kd of kinds) if (kd) dcNameLabel(parts[kd], kd, ts);
  demoTitle(p.x, p.y, title, DEMO_TITLE_SIZE * ts);
  demoNote (p.x, noteY, NOTE, DEMO_NOTE_SIZE * ts);
  return { src, parts, g };
}
function demoRLSeries() {
  acSeriesBuild(['R', 'L'], 'RL直列回路',
    '交流電源に抵抗 R とコイル L を一列につないだ回路。\n'
  + 'グラフは1段に1つの素子。左の円はその素子の\n'
  + '電圧（実線）と電流（破線）の回転ベクトル。\n'
  + '\n'
  + '【手順】▶実行 を押す（2周期ほどで円が出る）\n'
  + '・R の電圧は電流と同じ向き、L の電圧は 90° 進む\n'
  + '・電源の電圧は電流より φ 進む：tanφ ＝ ωL／R\n'
  + '・振動数を上げると ωL が大きくなり、電流は減る\n'
  + '　電流の振幅 ＝ V／√(R² ＋ (ωL)²)');
}
function demoRCSeries() {
  acSeriesBuild(['R', 'C'], 'RC直列回路',
    '交流電源に抵抗 R とコンデンサー C を一列に\n'
  + 'つないだ回路。グラフは1段に1つの素子。左の円は\n'
  + 'その素子の電圧（実線）と電流（破線）の回転ベクトル。\n'
  + '\n'
  + '【手順】▶実行 を押す（2周期ほどで円が出る）\n'
  + '・R の電圧は電流と同じ向き、C の電圧は 90° 遅れる\n'
  + '・電源の電圧は電流より φ 遅れる：tanφ ＝ 1／(ωCR)\n'
  + '・振動数を上げると 1／ωC が小さくなり、電流は増える\n'
  + '　電流の振幅 ＝ V／√(R² ＋ (1／ωC)²)');
}
function demoRLCSeries() {
  acSeriesBuild(['R', 'L', 'C'], 'RLC直列回路',
    '交流電源に抵抗・コイル・コンデンサーを一列に\n'
  + 'つないだ回路。グラフは1段に1つの素子。左の円は\n'
  + 'その素子の電圧（実線）と電流（破線）の回転ベクトル。\n'
  + '\n'
  + '【手順】▶実行 を押す（2周期ほどで円が出る）\n'
  + '・L と C の電圧はいつも逆向き（打ち消し合う）\n'
  + '・振動数をゆっくり上げると、ωL ＝ 1／ωC で\n'
  + '　電流がいちばん大きくなる（共振）\n'
  + '　共振周波数 f₀ ＝ 1／(2π√(LC))\n'
  + '・共振のとき電源の電圧と電流の向きがそろう（φ ＝ 0）');
}
